(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,41240,a=>{a.v(JSON.parse('[{"id":"W2_Q1","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Hukuk düzeni tarafından kişilere tanınan, korunan menfaati ve bu menfaatin gerçekleştirilmesi için hak sahibine sağlanan irade ve yetkiyi ifade eden kavram aşağıdakilerden hangisidir?","tooltips":{"Yaptırım":"Bir kuralın ihlali durumunda kamu gücüyle uygulanan hukuki yaptırım veya cebir tedbiri.","İcbar":"Bir kimseyi belirli bir davranışı yerine getirmesi için kamu gücüyle zorlama durumu."},"options":{"A":"Hürriyet","B":"Ödev","C":"Hak","D":"Yaptırım","E":"İcbar"},"correct_option":"C","explanations":{"A":"Yanlış. Hürriyet, dışsal bir tanımaya veya yetkilendirmeye ihtiyaç duymayan genel hareket serbestisidir.","B":"Yanlış. Ödev, bir yetkiyi veya korunan menfaati değil, yerine getirilmesi gereken yükümlülüğü ifade eder.","C":"Doğru. Hukuk düzenince korunan menfaat ve bu menfaati gerçekleştirmek üzere tanınan irade kudreti hak olarak tanımlanır.","D":"Yanlış. Yaptırım, bir kuralın ihlali durumunda kamu gücüyle devreye giren hukuki sonucu ifade eder.","E":"Yanlış. İcbar, bir kimseyi belirli bir davranışı yapmaya zorlama durumudur ve yetkiyi değil zorlamayı belirtir."},"overall_explanation":"Hak, hukuk düzeni tarafından kişilere tanınan ve korunan menfaat ile bu menfaatin korunmasını talep etme yetkisini içeren hukuki kavramdır."},{"id":"W2_Q2","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"İnsanın sırf insan olması sebebiyle doğuştan sahip olduğu, dışsal bir tanımaya ya da hukuk düzeninin yetkilendirmesine ihtiyaç duymayan hareket serbestisi aşağıdakilerden hangisidir?","tooltips":{"İltizam":"Kişinin hukuken bir edimi yerine getirme taahhüdüyle borç altına girmesi.","Edim":"Borçlunun alacaklıya karşı yerine getirmekle yükümlü olduğu verme, yapma veya yapmama davranışı."},"options":{"A":"Hürriyet","B":"Hak","C":"İltizam","D":"Muafiyet","E":"Edim"},"correct_option":"A","explanations":{"A":"Doğru. Hürriyet, insanın doğuştan kazandığı ve hukuk düzeninin bahşetmesine gerek olmaksızın var olan eylemde bulunma serbestisidir.","B":"Yanlış. Hak, hukuk düzeni tarafından tanınan, sınırları çizilen ve korunan menfaattir.","C":"Yanlış. İltizam, bir yükümlülük altına girme veya borçlanma iradesini ifade eder.","D":"Yanlış. Muafiyet, belirli bir kural veya yükümlülüğün kapsamı dışında tutulma halidir.","E":"Yanlış. Edim, borç ilişkisinde alacaklının talep edebileceği borç konusu davranıştır."},"overall_explanation":"Hürriyet, insanın doğuştan getirdiği dışsal bir izne bağlı olmayan hareket alanını ifade ederken, hak bu serbestinin hukuk düzenince korunup sınırlandırılmış halidir."},{"id":"W2_Q3","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Bir bireyin tek başına yaşadığı bir ortamda yalnızca hürriyetten söz edilirken, ikinci bir kişinin varlığıyla birlikte hak kavramının zorunlu hale gelmesinin temel sebebi aşağıdakilerden hangisidir?","tooltips":{"hürriyetten":"Kişinin tek başına bulunduğu alandaki sınırsız hareket serbestisinden.","menfaatlerin":"Bireylerin elde etmeyi amaçladığı maddi veya manevi hukuki yararların."},"options":{"A":"Devlet gücünün tek taraflı olarak bireye üstün gelmesi","B":"Toplumdaki ahlak kurallarının tamamen etkisini yitirmesi","C":"Maddi ceza kurallarının kendiliğinden yürürlüğe girmesi","D":"Çatışan menfaatlerin sınırlandırılması ve korunması ihtiyacı","E":"Pozitif hukukun doğal hukukun yerine tamamen geçmesi"},"correct_option":"D","explanations":{"A":"Yanlış. Hakkın doğuşu devletin bireye üstün gelmesiyle değil, bireyler arası serbesti alanlarının kesişmesiyle ilgilidir.","B":"Yanlış. Toplumsal yaşamda ahlak kuralları etkisini kaybetmez, varlığını sürdürür.","C":"Yanlış. Hak kavramının ortaya çıkışı doğrudan ceza kurallarının kendiliğinden yürürlüğe girmesiyle açıklanamaz.","D":"Doğru. İkinci bir kişinin varlığıyla hürriyet alanları kesişir ve çatışan menfaatlerin hukuken sınırlandırılıp korunması zorunluluğu hakkı doğurur.","E":"Yanlış. Bu durum pozitif hukukun doğal hukukun yerine geçmesi meselesi değildir."},"overall_explanation":"Tek başına olan birey mutlak bir hürriyet alanına sahipken, toplumsal yaşamda diğer bireylerin varlığı menfaat çatışmalarını doğurur ve bu çatışmaları dengelemek için hak kavramı ortaya çıkar."},{"id":"W2_Q4","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Kişinin hak sahibi olabilme iktidarı ile sahip olduğu hakları bizzat kendi iradesi ve eylemleriyle kullanabilme kudreti sırasıyla hangi kavramlarla ifade edilir?","tooltips":{"tasarruf yetkisi":"Bir kimsenin bir hak üzerinde devir veya sınırlama gibi hukuki işlem yapabilme iktidarı.","temsil yetkisi":"Bir kimsenin başka bir şahıs adına ve hesabına hukuki işlem gerçekleştirebilme gücü."},"options":{"A":"İntifa ehliyeti ve tasarruf yetkisi","B":"Hak ehliyeti ve fiil ehliyeti","C":"Dava ehliyeti ve temsil yetkisi","D":"Taraf ehliyeti ve iddia kudreti","E":"Hukuki ehliyet ve yargılama hakkı"},"correct_option":"B","explanations":{"A":"Yanlış. İntifa bir eşyadan yararlanma hakkıdır; tasarruf yetkisi ise hak üzerinde devir veya sınırlama yapma iktidarıdır.","B":"Doğru. Haklara sahip olabilme iktidarı hak ehliyeti, bu hakları bizzat eylemlerle kullanabilme yeteneği ise fiil ehliyetidir.","C":"Yanlış. Dava ehliyeti bir davayı bizzat takip edebilme, temsil yetkisi ise başkası adına işlem yapabilme iktidarıdır.","D":"Yanlış. Taraf ehliyeti bir davada davacı veya davalı olabilme sıfatıdır ve medeni haklardan yararlanma ehliyetinin usul hukukundaki karşılığıdır.","E":"Yanlış. Yargılama hakkı kişilerin uyuşmazlıkların çözümü için mahkemelere başvurma serbestisini tanımlar."},"overall_explanation":"Hukukta insan olmak hak ehliyeti için yeterliyken, hakları bizzat kullanıp borç altına girebilmek ayırt etme gücü ve erginlik gibi şartlara tabi olan fiil ehliyetini gerektirir."},{"id":"W2_Q5","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Pozitif hukuk sisteminde hak süjesi sıfatına sahip olan ve hukuken hak edinebilen varlıklar aşağıdakilerin hangisinde birlikte ve eksiksiz verilmiştir?","tooltips":{"hak süjesi":"Hukuk düzeninde hak ve borçlara sahip olabilen kişi veya varlık.","tüzel kişiler":"Belirli bir amacı gerçekleştirmek üzere örgütlenmiş kişi veya mal toplulukları."},"options":{"A":"Yalnızca ergin kılınmış gerçek kişiler","B":"Gerçek kişiler ve hayvanlar","C":"Kamu kurumları ve doğal çevre varlıkları","D":"Yalnızca fiil ehliyetine sahip gerçek kişiler","E":"Gerçek kişiler ve tüzel kişiler"},"correct_option":"E","explanations":{"A":"Yanlış. Ergin olmayanlar da hak ehliyetine sahip olup hak süjesidir; ayrıca tüzel kişiler dışarıda bırakılmıştır.","B":"Yanlış. Hayvanlar pozitif hukukta hak süjesi değil, eşya statüsünde kabul edilir.","C":"Yanlış. Doğal çevre varlıkları pozitif hukuk sistemimizde hak öznesi sıfatına sahip değildir.","D":"Yanlış. Fiil ehliyeti bulunmayan küçükler ve kısıtlılar da hak süjesidir.","E":"Doğru. Pozitif hukukta yalnızca insanlar yani gerçek kişiler ile belirli kişi veya mal topluluklarından oluşan tüzel kişiler hak süjesidir."},"overall_explanation":"Hukuk düzeninde hak süjesi yani hak ve borçların sahibi olabilen varlıklar yalnızca gerçek kişiler (insanlar) ve tüzel kişilerdir."},{"id":"W2_Q6","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Bir hakkı ihlal edilen kişinin, bizzat güç veya zor kullanarak hakkını elde etmesinin yasaklanması ve hakkın yalnızca devlet organları aracılığıyla talep edilebilmesi ilkesi aşağıdakilerden hangisidir?","tooltips":{"Masumiyet karinesi":"Kişinin suçluluğu mahkeme kararıyla kesinleşinceye kadar masum sayılması ilkesi.","Tabiî hâkim güvencesi":"Kişinin eyleminden önce kanunla kurulmuş yetkili mahkemede yargılanması hakkı."},"options":{"A":"İhkak-ı hak yasağı","B":"Kanunilik ilkesi","C":"Masumiyet karinesi","D":"Hukuki güvenlik ilkesi","E":"Tabiî hâkim güvencesi"},"correct_option":"A","explanations":{"A":"Doğru. Hakkı ihlal edilen kişinin bizzat cebir kullanarak hakkını elde etmesinin yasaklanıp devlet organlarına başvurma zorunluluğu getirilmesi ihkak-ı hak yasağıdır.","B":"Yanlış. Kanunilik ilkesi suç ve cezaların veya vergilerin ancak kanunla konulabileceğini ifade eder.","C":"Yanlış. Masumiyet karinesi, bir suç ile itham edilen kişinin kesin hüküm verilene kadar masum kabul edilmesidir.","D":"Yanlış. Hukuki güvenlik, kuralların öngörülebilir ve geriye yürümez olmasını güvenceye bağlar.","E":"Yanlış. Tabiî hâkim güvencesi, yargılamanın eylemden önce kanunla kurulmuş mahkemelerce yapılmasını şart koşar."},"overall_explanation":"İhkak-ı hak yasağı, toplumsal düzeni korumak amacıyla kişilerin kendi haklarını bizzat güç kullanarak almalarını yasaklayıp hakkın korunmasını münhasıran yargı ve icra organlarına bırakan temel ilkedir."},{"id":"W2_Q7","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"İhkak-ı hak yasağı uyarınca hakkı ihlal edilen bir kimsenin, hakkın teslimini ve cebri icrasını talep edebileceği anayasal devlet organları aşağıdakilerin hangisinde birlikte verilmiştir?","tooltips":{"cebri icrasını":"Borcun rıza ile ödenmemesi durumunda kamu gücü marifetiyle zorla yerine getirilmesini.","İhkak-ı hak yasağı":"Kişinin kendi hakkını bizzat kuvvet kullanarak almasını yasaklayan temel hukuk kuralı."},"options":{"A":"Yasama ve denetim organları","B":"İdare ve kolluk makamları","C":"Yargı ve icra organları","D":"Noterlik ve arabuluculuk büroları","E":"Danıştay ve Sayıştay kurulları"},"correct_option":"C","explanations":{"A":"Yanlış. Yasama organı genel ve soyut kurallar koyar, uyuşmazlıklarda somut hak teslimini yerine getirmez.","B":"Yanlış. İdare ve kolluk düzeni korur ancak hakkın tespiti ve cebri icrası yargı ve icra sisteminin temel görevidir.","C":"Doğru. İhkak-ı hak yasağının bir sonucu olarak hak sahibi, hakkın tespiti için yargı organlarına, ifası için ise icra organlarına başvurmak zorundadır.","D":"Yanlış. Noterlik ve arabuluculuk alternatif veya tescil mekanizmalarıdır, hakkın zorla yerine getirilmesini doğrudan sağlamaz.","E":"Yanlış. Danıştay yüksek idari yargı merciidir, Sayıştay ise mali denetim organıdır; genel hak arama sürecinin icra ayağını oluşturmazlar."},"overall_explanation":"İhkak-ı hak yasağı gereğince bireyler hakkın varlığını yargı organları marifetiyle tespit ettirir ve ifasını icra organları aracılığıyla kamu gücüyle sağlar."},{"id":"W2_Q8","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Hukuk kurallarını diğer toplumsal düzen kurallarından ayıran ve hukukun tanımında belirleyici nitelik taşıyan en temel unsur aşağıdakilerden hangisidir?","tooltips":{"Hukuk kurallarını":"Toplumsal ilişkileri düzenleyen ve kamu gücüyle desteklenen bağlayıcı kuralları.","toplumsal düzen kurallarından":"Toplum hayatında insan ilişkilerini düzenleyen kuralların bütününden."},"options":{"A":"Toplum vicdanında genel kabul görmesi","B":"Evrensel ahlaki değerlerle bütünüyle örtüşmesi","C":"Dinî inanç sistemleriyle uyumlu olması","D":"Yazılı metinler biçiminde kaleme alınması","E":"Kamu gücüyle desteklenmiş maddi yaptırıma bağlanması"},"correct_option":"E","explanations":{"A":"Yanlış. Toplum vicdanında kabul görme ahlak ve örf kurallarında da mevcuttur, hukuka özgü ayırıcı ölçüt değildir.","B":"Yanlış. Ahlaki değerlerle örtüşmek hukukun etik amacı olabilir fakat ayırıcı tanımlayıcı unsuru değildir.","C":"Yanlış. Din kurallarıyla uyumluluk laik hukuk sistemlerinde bir geçerlilik unsuru değildir.","D":"Yanlış. Örf ve âdet hukuku gibi yazısız hukuk kaynakları da bulunduğundan yalnızca yazılılık hukukun ayırıcı unsuru olamaz.","E":"Doğru. Hukuk kurallarını din, ahlak ve görgüden ayıran temel nitelik, devlet gücüyle uygulanan maddi yaptırımla desteklenmiş olmasıdır."},"overall_explanation":"Hukuk kurallarının ayırıcı vasfı, arkasında devletin örgütlü cebir gücünün bulunması ve ihlali halinde maddi yaptırımlarla desteklenmiş olmasıdır."},{"id":"W2_Q9","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Toplumda geçerli olan ahlak kurallarının ihlali durumunda karşılaşılan temel yaptırım türü aşağıdakilerden hangisidir?","tooltips":{"cebri icra":"Hukuki yükümlülüklerin kamu gücü marifetiyle zorla yerine getirilmesi işlemi.","kesin hükümsüzlük":"Kanunun emredici normlarına aykırı hukuki muamelelerin baştan itibaren geçersiz sayılması."},"options":{"A":"Hapis cezası ve adli para cezası","B":"Manevi nitelikteki bireysel iç muhakeme ve vicdan azabı","C":"Kamu gücü eliyle uygulanan cebri icra tedbirleri","D":"İdari organlar tarafından uygulanan kınama yaptırımı","E":"Hukuki işlemlerin kesin hükümsüzlük ile iptali"},"correct_option":"B","explanations":{"A":"Yanlış. Hapis ve adli para cezası ceza hukuku yaptırımı olup maddi cebir niteliğindedir.","B":"Doğru. Ahlak kurallarının ihlalinde devreye giren yaptırım manevidir; bireyin kendi vicdan azabı ve iç hesaplaşmasıdır.","C":"Yanlış. Cebri icra hukuk kurallarının ihlaline bağlanan maddi bir yaptırımdır.","D":"Yanlış. İdari kınama, mevzuata dayalı resmi bir disiplin yaptırımıdır.","E":"Yanlış. Kesin hükümsüzlük medeni hukukun işlemler üzerindeki maddi yaptırımıdır."},"overall_explanation":"Ahlak kuralları maddi cebir gücünden yoksundur; bu kurallara uyulmaması bireysel vicdan azabı ve manevi iç hesaplaşma gibi yaptırımlarla karşılık bulur."},{"id":"W2_Q10","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Toplumsal yaşamda görgü veya örf-âdet kurallarına aykırı hareket eden bir kişinin karşılaşacağı müeyyidenin mahiyeti aşağıdakilerden hangisidir?","tooltips":{"müeyyidenin":"Bir kurala aykırılık halinde kamu gücü veya toplum tarafından gösterilen yaptırım tepkisinin.","müsadere":"Suçla ilişkili eşyanın veya suç gelirinin mülkiyetinin devlete geçirilmesi yaptırımı."},"options":{"A":"Devlet gücüyle uygulanan hapis veya haciz tedbiri","B":"Kişinin ahirette günahkâr sayılması ve uhrevi ceza","C":"Hukuki hakkın icra dairesince zorla yerine getirilmesi","D":"Toplum tarafından ayıplanma, kınanma ve dışlanma","E":"Malvarlığı haklarının idari kararla müsadere edilmesi"},"correct_option":"D","explanations":{"A":"Yanlış. Hapis veya haciz yalnızca hukuk kurallarının ihlali halinde uygulanan maddi yaptırımlardır.","B":"Yanlış. Günahkâr sayılma ve uhrevi ceza din kurallarının ihlaline bağlanan sonuçtur.","C":"Yanlış. İcra dairesi aracılığıyla zorla ifa hukuki alacaklara mahsus maddi bir yaptırımdır.","D":"Doğru. Görgü ve örf kurallarına aykırılık ayıplanma, kınanma ve sosyal çevreden dışlanma şeklinde manevi ve sosyal tepkiler doğurur.","E":"Yanlış. Müsadere ceza hukukuna özgü maddi bir kamu yaptırımıdır."},"overall_explanation":"Görgü ve örf-âdet kurallarına aykırılığın neticesi hukuki cebir veya uhrevi ceza değil, kınanma ve ayıplanma gibi manevi ve sosyal nitelikli tepkilerdir."},{"id":"W2_Q11","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Din kurallarını diğer toplumsal düzen kurallarından ayıran yaptırım mahiyeti aşağıdakilerden hangisidir?","tooltips":{"toplumsal düzen kurallarından":"Toplum yaşamını tanzim eden din, ahlak, görgü ve hukuk kuralları toplamından.","adli para cezaları":"Ceza kanunlarına aykırı fiil nedeniyle mahkemece hükmedilen para ödeme yaptırımları."},"options":{"A":"Toplumsal alanda kınanma ve sosyal tecrit","B":"Uhrevi nitelikteki inanç alanı ve manevi sorumluluk","C":"Devletin cebir araçlarıyla uyguladığı maddi tazminat","D":"Kişinin bizzat kendi aklıyla koyduğu felsefi sınırlar","E":"Mahkemelerce tesis edilen adli para cezaları"},"correct_option":"B","explanations":{"A":"Yanlış. Kınanma ve sosyal tecrit örf, âdet ve ahlak kurallarının sosyal yaptırımlarıdır.","B":"Doğru. Din kurallarının belirleyici yaptırımı, inanç esasına dayalı olan uhrevi nitelikteki sorumluluk ve günahtır.","C":"Yanlış. Tazminat borcu hukuk kurallarının ihlaline bağlanan maddi bir yaptırımdır.","D":"Yanlış. Kişinin kendi aklıyla koyduğu sınırlar bireysel etik ve ahlak alanına aittir.","E":"Yanlış. Mahkemelerce verilen adli para cezaları hukuk düzeninin maddi müeyyidelerindendir."},"overall_explanation":"Din kurallarının yaptırımı uhrevi ve inanç temellidir; dünyevi ve maddi bir cebir içermez."},{"id":"W2_Q12","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Hukuk düzeninin veya toplumsal yaşam kurallarının kişiye yüklediği, belirli bir davranışı yapma ya da belirli bir davranıştan kaçınma zorunluluğunu ifade eden kavram aşağıdakilerden hangisidir?","tooltips":{"Yetki":"Bir kimseye hukuki işlemler yapabilmesi amacıyla tanınan yasal kudret.","İcazet":"Önceden yetkisiz yapılmış bir hukuki muameleye sonradan geçerlilik kazandıran onay."},"options":{"A":"Hürriyet","B":"Yetki","C":"Ödev","D":"Hak","E":"İcazet"},"correct_option":"C","explanations":{"A":"Yanlış. Hürriyet bir zorunluluğu değil, serbest hareket edebilme kudretini ifade eder.","B":"Yanlış. Yetki kişiye tanınan hukuki gücü belirtir, davranış zorunluluğunu ifade etmez.","C":"Doğru. Hukuk düzeninin kişiye yüklediği belirli bir eylemi sergileme veya eylemden kaçınma zorunluluğu ödevdir.","D":"Yanlış. Hak, korunması istenen menfaat ve tanınan serbestiyi tanımlar.","E":"Yanlış. İcazet, önceden yapılan bir işleme sonradan onay verilmesidir."},"overall_explanation":"Ödev, hak kavramının karşısında yer alan ve kişinin yapması veya kaçınması gereken davranış modelini belirten hukuki yükümlülüktür."},{"id":"W2_Q13","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Kişinin aktif bir eylemde bulunmasını, bir şeyi vermesini veya yapmasını gerektiren hukuki yükümlülüklere ne ad verilir?","tooltips":{"Şahsa sıkı sıkıya bağlı hak":"Başkasına devredilemeyen ve mirasçılara intikal etmeyen kişiye özgü hak.","Yenilik doğuran yetki":"Kullanılmasıyla birlikte yeni bir hukuki ilişki meydana getiren veya mevcut ilişkiyi bozan yetki."},"options":{"A":"Olumlu nitelikteki ödev","B":"Olumsuz nitelikteki ödev","C":"Katlanma niteliğindeki ödev","D":"Şahsa sıkı sıkıya bağlı hak","E":"Yenilik doğuran yetki"},"correct_option":"A","explanations":{"A":"Doğru. Kişinin aktif bir eylem sergilemesini, bir şeyi ifa etmesini veya vermesini gerektiren yükümlülükler olumlu ödevdir.","B":"Yanlış. Olumsuz nitelikteki ödevler bir şeyi yapmamayı veya belirli bir eylemden kaçınmayı gerektirir.","C":"Yanlış. Katlanma ödevi olumsuz ödev kategorisinde değerlendirilir ve pasif kalmayı içerir.","D":"Yanlış. Şahsa sıkı sıkıya bağlı hak bir yükümlülük değil, başkasına devredilemeyen bir haktır.","E":"Yanlış. Yenilik doğuran yetki, tek taraflı irade açıklamasıyla hukuki ilişki kuran veya bozan haktır."},"overall_explanation":"Ödevler icrai bir eylem veya verme edimi gerektiriyorsa olumlu ödev; kaçınma veya yapmama gerektiriyorsa olumsuz ödev olarak sınıflandırılır."},{"id":"W2_Q14","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Aşağıdakilerden hangisi kişinin belirli bir eylemden kaçınmasını veya başkasının eylemine katlanmasını gerektiren olumsuz nitelikteki bir ödeve örnektir?","tooltips":{"Taşınmaz":"Bir yerden bir yere özü bozulmadan nakledilemeyen arazi ve yapı niteliğindeki mal.","malikinin":"Bir eşya üzerinde tam tasarruf ve mülkiyet yetkisine sahip bulunan kimsenin."},"options":{"A":"Satıcının satılan malı alıcıya teslim etmesi","B":"Borçlunun vadesi gelen para borcunu ödemesi","C":"Hizmet sözleşmesinde işçinin mesaiyi tamamlaması","D":"Taşınmaz malikinin komşusunu rahatsız edecek gürültüden kaçınması","E":"Kiracının ay başında kira bedelini ev sahibine yatırması"},"correct_option":"D","explanations":{"A":"Yanlış. Malın teslimi aktif bir verme davranışı gerektirdiğinden olumlu nitelikte bir ödevdir.","B":"Yanlış. Paranın ödenmesi aktif bir verme edimi olduğundan olumlu ödev örneğidir.","C":"Yanlış. Mesainin tamamlanması aktif bir çalışma edimi gerektirdiğinden olumlu ödevdir.","D":"Doğru. Gürültü yapmaktan kaçınma ve hareketsiz kalma yükümlülüğü olumsuz nitelikteki bir ödevdir.","E":"Yanlış. Kira bedelinin yatırılması aktif bir para ödeme fiili olduğundan olumlu ödevdir."},"overall_explanation":"Olumsuz nitelikteki ödevler kişiye yapmama, kaçınma veya katlanma biçiminde pasif bir davranış yükümlülüğü getirir."},{"id":"W2_Q15","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Belirli bir ülkede belirli bir zamanda yetkili makamlar tarafından konulmuş, yürürlükte bulunan yazılı ve yazısız hukuk kurallarının tamamına ne ad verilir?","tooltips":{"Tarihi hukuk":"Geçmişte yürürlükte kalmış ancak günümüzde bağlayıcılığı ve uygulanma imkânı bulunmayan hukuk.","Normatif hukuk":"Pozitif kuralların ötesinde olması hedeflenen kural sistemini araştıran hukuk yaklaşımı."},"options":{"A":"Doğal hukuk","B":"İdeal hukuk","C":"Tarihi hukuk","D":"Normatif hukuk","E":"Pozitif hukuk"},"correct_option":"E","explanations":{"A":"Yanlış. Doğal hukuk, akla ve evrensel adalet ilkelerine dayanan ideal hukuku ifade eder.","B":"Yanlış. İdeal hukuk, yürürlükte olanı değil ulaşılmak istenen adil düzeni ifade eder.","C":"Yanlış. Tarihi hukuk, geçmişte yürürlükte bulunup bugün yürürlükten kalkmış kuralları ifade eder.","D":"Yanlış. Normatif hukuk kavramı genellikle olması gereken ideal hukuk düzenini belirtmek için kullanılır.","E":"Doğru. Belli bir ülkede belli bir dönemde yürürlükte olan yazılı ve yazısız tüm kurallar bütünü pozitif hukuktur."},"overall_explanation":"Pozitif hukuk (yürürlükteki hukuk / dogmatik hukuk), belirli bir zamanda ve ülkede fiilen uygulanan yazılı ve yazısız tüm normları ifade eden olan hukuktur."},{"id":"W2_Q16","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Pozitif hukuk kavramının kapsamı ile ilgili olarak aşağıdakilerden hangisi doğrudur?","tooltips":{"örf ve âdet hukuku":"Toplumda kendiliğinden doğan, süreklilik kazanan ve hukuken bağlayıcı kabul edilen yazısız kurallar bütünü.","mevzuatı":"Bir ülkede yetkili makamlarca yürürlüğe konulmuş tüm yazılı hukuk kuralları toplamını."},"options":{"A":"Yalnızca kanunları değil örf ve âdet hukuku gibi yazısız kuralları da kapsar","B":"Yalnızca yürürlükten tamamen kalkmış tarihi kuralları kapsar","C":"Yalnızca devletler tarafından henüz kabul edilmemiş ahlaki idealleri kapsar","D":"Sadece anayasa metninden ibaret olup diğer mevzuatı dışarıda bırakır","E":"Toplum vicdanında kabul görmüş ancak bağlayıcılığı olmayan adetleri kapsar"},"correct_option":"A","explanations":{"A":"Doğru. Pozitif hukuk sadece yazılı kuralları değil, bağlayıcılığı kabul edilmiş örf ve âdet hukuku gibi yazısız kaynakları da içerir.","B":"Yanlış. Yürürlükten kalkmış kurallar tarihi hukukun konusudur, pozitif hukukun değil.","C":"Yanlış. Henüz kabul edilmemiş ahlaki idealler ideal hukukun konusudur.","D":"Yanlış. Pozitif hukuk kanun, yönetmelik ve örf-âdet gibi tüm yürürlükteki normları kapsar.","E":"Yanlış. Bağlayıcılığı olmayan sıradan adetler pozitif hukukun parçası sayılmaz."},"overall_explanation":"Pozitif hukuk, yürürlükteki yazılı kuralların yanında hukuken bağlayıcılık kazanmış yazısız kuralları da (örf ve âdet hukukunu) bünyesinde barındırır."},{"id":"W2_Q17","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Yürürlükteki hukukun ötesinde; adalete, insan onuruna ve ahlaka en uygun olan, toplumsal gereksinimleri eksiksiz karşılamayı hedefleyen kurgusal ve ulaşılmak istenen hukuk nizamına ne ad verilir?","tooltips":{"Dogmatik hukuk":"Yürürlükteki hukuk normlarını eleştirmeksizin sistemleştiren ve inceleyen hukuk yaklaşımı.","Müspet hukuk":"Yetkili merciler tarafından konulmuş fiilen uygulanmakta olan pozitif hukuk nizamı."},"options":{"A":"Pozitif hukuk","B":"Dogmatik hukuk","C":"Yürürlükteki hukuk","D":"Müspet hukuk","E":"İdeal hukuk"},"correct_option":"E","explanations":{"A":"Yanlış. Pozitif hukuk halihazırda yürürlükte olan olan hukuku ifade eder.","B":"Yanlış. Dogmatik hukuk, pozitif hukukun sistemleştirilmesini ifade eden bir diğer addır.","C":"Yanlış. Yürürlükteki hukuk, pozitif hukukun eş anlamlısıdır.","D":"Yanlış. Müspet hukuk, konulmuş ve yürürlükte olan pozitif hukuku tanımlar.","E":"Doğru. Adalete en uygun olan ve ulaşılması hedeflenen olması gereken hukuk sistemine ideal hukuk denir."},"overall_explanation":"İdeal hukuk (doğal / tabii hukuk), mevcut pozitif normların ötesinde insan aklına, ahlaka ve adalete uygun düşen olması gereken hukuku temsil eder."},{"id":"W2_Q18","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Hukukun geçerliliğini yalnızca yetkili siyasi otoritenin iradesine ve usulüne uygun şekilde konulmuş kurallara bağlayan; adalet ve ahlak gibi soyut değerleri hukukun zorunlu kurucu unsuru saymayan yaklaşım aşağıdakilerden hangisidir?","tooltips":{"Doğal hukuk yaklaşımı":"Hukukun meşruiyetini doğaya, akla ve üstün evrensel ahlaki değerlere dayandıran doktrin.","Tarihçi hukuk ekolü":"Hukukun kaynağının kanun koyucunun iradesi değil milletin tarihi gelişimi olduğunu savunan ekol."},"options":{"A":"Doğal hukuk yaklaşımı","B":"İdeal hukuk doktrini","C":"Hukuk pozitivizmi","D":"Tarihçi hukuk ekolü","E":"Sosyolojik hukuk akımı"},"correct_option":"C","explanations":{"A":"Yanlış. Doğal hukuk yaklaşımı, kuralların geçerliliğini ahlak ve evrensel adalet ilkelerine dayandırır.","B":"Yanlış. İdeal hukuk doktrini, hukukun ahlaki değerler ve insan onuruyla uyumlu olması gerektiğini savunur.","C":"Doğru. Hukuk pozitivizmi, hukuku sadece yetkili merciin usulünce yürürlüğe koyduğu kurallardan ibaret görür ve ahlaki unsurları kurucu saymaz.","D":"Yanlış. Tarihçi hukuk ekolü hukukun milletin ortak vicdanından ve tarihinden doğduğunu kabul eder.","E":"Yanlış. Sosyolojik hukuk akımı normların toplumsal gerçeklik ve olgularla ilişkisini merkeze alır."},"overall_explanation":"Hukuk pozitivizmi, hukuku usulüne uygun olarak konulmuş pozitif kurallarla sınırlandırır ve ahlak ya da adaleti geçerlilik şartı olarak görmez."},{"id":"W2_Q19","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Pozitif hukuk kurallarının meşruiyetini ve bağlayıcılığını, insan aklına dayanan evrensel adalet ilkelerinden ve ahlaki değerlerden aldığını savunan hukuki yaklaşım aşağıdakilerden hangisidir?","tooltips":{"Hukuk pozitivizmi":"Hukukun meşruiyetini adalet veya ahlakta değil yetkili makamın biçimsel norm koyma iradesinde gören kuram.","Dogmatik hukuk ekolü":"Yürürlükte olan pozitif hukuk normlarını tartışmasız kabul ederek analiz eden yaklaşım."},"options":{"A":"Hukuk pozitivizmi","B":"Doğal hukuk anlayışı","C":"Şekilci hukuk kuramı","D":"Dogmatik hukuk ekolü","E":"İradi hukuk yaklaşımı"},"correct_option":"B","explanations":{"A":"Yanlış. Pozitivizm meşruiyeti üstün ahlak ilkelerine değil, konulmuş kuralların biçimsel geçerliliğine bağlar.","B":"Doğru. Doğal hukuk kuramı, kuralların meşruiyetini insan aklından ve evrensel adalet ile ahlak ilkelerinden aldığını savunur.","C":"Yanlış. Şekilci yaklaşım kuralların konulma usulünü ve biçimini esas alır.","D":"Yanlış. Dogmatik hukuk, yürürlükteki kuralları tartışmaksızın sistemleştirmeyi hedefler.","E":"Yanlış. İradi yaklaşım hukuku kanun koyucunun iradesine dayandırır."},"overall_explanation":"Doğal hukuk anlayışı, pozitif kanunların üstünde evrensel adalet ve akıl ilkelerinin bulunduğunu ve kanunların meşruiyetini bu ilkelerden aldığını ileri sürer."},{"id":"W2_Q20","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Hukukun, güçlü olanın güçsüzü ezmesini engellemek, kargaşayı önlemek ve toplumsal barışı tesis etmek şeklinde özetlenen amacı aşağıdakilerden hangisidir?","tooltips":{"toplumsal barışı":"Toplumdaki birey ve grupların çatışmadan uzak, huzur ve güven içinde birlikte yaşamasını.","Hukukun etik amacı":"Hukuk normlarının toplum vicdanı ve adalet ülküsüyle tam bir uyum içinde bulunması gayesi."},"options":{"A":"Hukukun maddi amacı","B":"Hukukun etik amacı","C":"Hukukun nihai amacı","D":"Hukukun şekli amacı","E":"Hukukun ekonomik amacı"},"correct_option":"D","explanations":{"A":"Yanlış. Hukukun maddi amacı toplumun somut ve değişken ihtiyaçlarını karşılamaktır.","B":"Yanlış. Hukukun etik amacı adalet idesini gerçekleştirmek ve toplum vicdanını tatmin etmektir.","C":"Yanlış. Doktrinde temel tasnif şekli, maddi ve etik amaçlar üzerinden yapılmaktadır.","D":"Doğru. Güçlünün güçsüzü ezmesini engellemek ve barış ortamını korumak hukukun şekli amacını teşkil eder.","E":"Yanlış. Ekonomik amaç hukuk felsefesindeki temel üçlü amaç sınıflandırmasında yer almaz."},"overall_explanation":"Hukukun şekli amacı, keyfiliği ve anarşiyi önleyerek toplumsal düzeni, barışı ve genel güvenliği sağlamaktır."},{"id":"W2_Q21","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Değişen ekonomik, teknolojik ve sosyal koşullara uyum sağlayarak bireylerin maddi ve hukuki güvenlik taleplerine cevap vermeyi hedefleyen hukuk amacı aşağıdakilerden hangisidir?","tooltips":{"hukuki güvenlik":"Bireylerin tabi oldukları hukuk kurallarının açık, öngörülebilir ve istikrarlı olması güvencesi.","Hukukun şekli amacı":"Toplumda anarşi ve keyfiliği önleyerek temel kamu düzenini ve barışı tesis etme gayesi."},"options":{"A":"Hukukun şekli amacı","B":"Hukukun maddi amacı","C":"Hukukun ahlaki amacı","D":"Hukukun etik amacı","E":"Hukukun cezai amacı"},"correct_option":"B","explanations":{"A":"Yanlış. Şekli amaç düzenin ve barışın korunmasını ifade eder.","B":"Doğru. Değişen yaşam koşullarına uyum sağlayıp toplumun somut ihtiyaçlarına ve güvenlik taleplerine cevap vermek hukukun maddi amacıdır.","C":"Yanlış. Ahlaki amaç etik amaç kapsamında incelenir ve adaleti hedefler.","D":"Yanlış. Etik amaç kuralların vicdan ve adalet idesiyle örtüşmesini hedefler.","E":"Yanlış. Cezai amaç hukukun genel amaç sınıflandırması içerisinde yer alan bir kategori değildir."},"overall_explanation":"Hukukun maddi amacı, toplumun değişen ekonomik, teknik ve sosyal gereksinimlerini karşılamak ve hukuki güvenliği sağlamaktır."},{"id":"W2_Q22","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Hukuk kurallarının salt birer buyruk olmaktan çıkıp toplum vicdanıyla örtüşmesini ve adalet idesini gerçekleştirmesini ifade eden temel amaç aşağıdakilerden hangisidir?","tooltips":{"toplum vicdanıyla":"Toplumun adalet ve hakkaniyet inancını oluşturan ortak ahlaki ve insani kanaatle.","adalet idesini":"Hukuk düzeninin gerçekleştirmekle yükümlü olduğu en yüksek ahlaki adalet idealini."},"options":{"A":"Hukukun şekli amacı","B":"Hukukun maddi amacı","C":"Hukukun etik amacı","D":"Hukukun teknik amacı","E":"Hukukun idari amacı"},"correct_option":"C","explanations":{"A":"Yanlış. Şekli amaç toplumsal barışı ve kamu düzenini sağlamaya yöneliktir.","B":"Yanlış. Maddi amaç sosyoekonomik gereksinimlerin karşılanmasıyla ilgilidir.","C":"Doğru. Kuralların adalet ülküsüne hizmet etmesi ve toplum vicdanını tatmin etmesi hukukun etik amacını oluşturur.","D":"Yanlış. Teknik amaç hukuki işlemlerin usulüne uygun yürütülmesine dair tali bir boyuttur.","E":"Yanlış. İdari amaç devlet teşkilatının işleyişiyle ilgilidir, hukukun temel felsefi amaçlarından biri değildir."},"overall_explanation":"Hukukun etik amacı, normların toplum vicdanıyla bütünleşerek gerçek anlamda adil bir düzen meydana getirmesini sağlamaktır."},{"id":"W2_Q23","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Hukuk düzenindeki eşitlik ilkesinin anlamı ve kapsamı bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"eşitlik ilkesinin":"Aynı hukuki durumda bulunanlara aynı, farklı durumdakilere durumlarının gerektirdiği kuralların uygulanması prensibinin.","mutlak surette":"Hiçbir istisna, koşul veya farklılık gözetilmeksizin her durumda kesin olarak."},"options":{"A":"Aynı hukuki durumda bulunanlar arasında ayrım gözetilmemesini ifade eder","B":"Farklı kıdem ve vasıftaki herkesin her koşulda aynı muameleye tabi tutulmasıdır","C":"Hiçbir ayrım yapılmaksızın tüm bireylere mutlak surette aynı sonucun verilmesidir","D":"Hukuk kurallarının yalnızca maddi durumu yetersiz olanlara uygulanmasıdır","E":"Bireyler arasındaki kişisel ve hukuki farkların tamamen yok sayılmasıdır"},"correct_option":"A","explanations":{"A":"Doğru. Hukuki veya nispi eşitlik, aynı durumda bulunanlara aynı, farklı durumda bulunanlara durumlarına göre farklı muameleyi yani eşitler arasında eşitliği dikte eder.","B":"Yanlış. Farklı kıdem ve vasıftaki kişilere aynı muamelenin yapılması eşitlik değil adaletsizlik doğurur.","C":"Yanlış. Mutlak eşitlik hukuki eşitlik ilkesiyle bağdaşmaz; hukuk nispi eşitliği esas alır.","D":"Yanlış. Eşitlik ilkesi kuralların genel ve nesnel olarak herkese uygulanmasını gerektirir.","E":"Yanlış. Hukuk farklı durumları gözetir, kişisel ve hukuki durum farklarını yok saymaz."},"overall_explanation":"Hukukta eşitlik mutlak değil nispidir; eşitler arasında eşitlik esastır. Aynı durumdakilere aynı, farklı durumdakilere durumlarının gerektirdiği farklı kural uygulanır."},{"id":"W2_Q24","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Adalet alegorisi olarak kullanılan Themis heykelinde yer alan terazi ve göz bağı simgeleri sırasıyla hangi hukuki ilkeleri temsil eder?","tooltips":{"Themis":"Evrensel hukuk ve adalet ilkelerini temsil eden mitolojik simge figür.","alegorisi":"Soyut bir kavramın veya düşüncenin somut bir varlık ve simgelerle ifade edilmesi."},"options":{"A":"Yaptırım gücü ve mutlak eşitlik","B":"Kanunilik ve maddi ceza kudreti","C":"Masumiyet ve suçun affedilmesi","D":"Hukuki güvenlik ve kamu düzeni","E":"Menfaat dengesi ile tarafsızlık"},"correct_option":"E","explanations":{"A":"Yanlış. Yaptırım gücü teraziyle değil kılıçla simgelenir.","B":"Yanlış. Kanunilik heykelin ayağının altındaki kitapla temsil edilir.","C":"Yanlış. Masumiyet bazen çocuk figürleriyle temsil edilse de terazi ve göz bağı ile temsil edilmez.","D":"Yanlış. Düzen ve güvenlik terazi ve göz bağının doğrudan simgelediği değerler değildir.","E":"Doğru. Terazi kusurun ve menfaatlerin hassas biçimde tartılmasını, göz bağı ise hiçbir ayrıcalık gözetmeyen tarafsızlığı temsil eder."},"overall_explanation":"Themis heykelinde terazi, suç ve menfaat dengesinin objektif tartılmasını; göz bağı ise kimliğe bakılmaksızın uygulanan tarafsızlığı simgeler."},{"id":"W2_Q25","domain_id":2,"domain_name":"Hafta 2: Hak, Ödev ve Toplumsal Düzen Kuralları","question":"Adalet tasvirlerinde yer alan kılıç ve ayak altındaki kitap motifleri sırasıyla hangi hukuki anlamlara karşılık gelir?","tooltips":{"masumiyet karinesi":"Bir suç isnadı altında bulunan kişinin kesin mahkûmiyet kararına kadar suçsuz sayılması ilkesi.","keyfiliğin reddi":"Yargısal ve idari kararların sübjektif kanaatlere değil objektif kanun metinlerine dayanması zorunluluğu."},"options":{"A":"Tarafsız yargılama ve hak ehliyeti","B":"Vicdani kanaat ve masumiyet karinesi","C":"Örf-âdet hukuku ve sosyal düzen","D":"Yaptırımın gücü ve keyfiliğin reddi","E":"İdeal hukuk ve mutlak adalet"},"correct_option":"D","explanations":{"A":"Yanlış. Tarafsızlık göz bağı ile simgelenir.","B":"Yanlış. Masumiyet karinesi kılıç veya kitap simgesiyle ifade edilmez.","C":"Yanlış. Kitap örf-âdeti değil yazılı pozitif kanunları ve kanuniliği simgeler.","D":"Doğru. Kılıç yaptırımın gücünü ve caydırıcılığını; ayak altındaki kitap ise hükümlerin keyfiliğe değil yazılı kanuna dayanması gerektiğini simgeler.","E":"Yanlış. Kitap soyut ideal hukuku değil yürürlükteki pozitif kanunu temsil eder."},"overall_explanation":"Adalet sembolizminde kılıç devletin cebri yaptırım kudretini, kitap ise keyfiliğin dışlanarak hükmün pozitif hukuka dayanması zorunluluğunu ifade eder."}]'))},51203,a=>{a.v(JSON.parse('[{"id":"W3_Q1","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Hukuk mekanizmasının uyuşmazlıkları çözüme kavuşturarak ortaya çıkardığı nihai ürün ve denge durumunu ifade eden kavram aşağıdakilerden hangisidir?","tooltips":{"Hukuk mekanizması":"Toplumsal düzeni kuran, uyuşmazlıkları kurallarla bağlayan ve yargısal yollarla karara bağlayan işleyiş bütünü."},"options":{"A":"Müeyyide","B":"Dava","C":"Adalet","D":"Hak","E":"Ehliyet"},"correct_option":"C","explanations":{"A":"Yanlış. Müeyyide, hukuk kurallarının ihlali hâlinde uygulanan cebri yaptırımı ifade eder.","B":"Yanlış. Dava, hak sahibinin uyuşmazlığın çözümü için yargı organlarına yönelttiği hukuki başvuru vasıtasıdır.","C":"Doğru. Hukuk kurallarının somut uyuşmazlıklara tatbiki sonucunda ulaşılan dengeli ve nihai sonuç adalettir.","D":"Yanlış. Hak, hukuk düzeni tarafından kişilere tanınan ve korunan menfaattir.","E":"Yanlış. Ehliyet, kişilerin haklara sahip olabilme veya bu hakları bizzat kullanabilme kudretidir."},"overall_explanation":"Hukuki süreç menfaatin hak olarak tanınması, uyuşmazlığın doğması, hukuk kuralları ve yargı mekanizmasının işletilmesiyle nihai ürün olan adalete ulaşılması döngüsünden oluşur."},{"id":"W3_Q2","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Gerçek kişiler bakımından hak ehliyetinin başlangıç anı aşağıdakilerden hangisinde doğru gösterilmiştir?","tooltips":{"hak ehliyeti":"Kişilerin haklara ve borçlara ehil olabilme, hukuki ilişkilere taraf olabilme iktidarı."},"options":{"A":"Sağ ve tam doğum","B":"On sekiz yaşın doldurulması","C":"Ayırt etme gücünün kazanılması","D":"Kısıtlılığın sona ermesi","E":"Temyiz kudretinin ispatı"},"correct_option":"A","explanations":{"A":"Doğru. Hak ehliyeti çocuğun sağ ve tam doğumu ile başlar ve ölümle sona erer.","B":"Yanlış. On sekiz yaşın doldurulması hak ehliyetinin değil, fiil ehliyetinin erginlik şartıdır.","C":"Yanlış. Ayırt etme gücü fiil ehliyetinin unsurudur; hak ehliyeti ayırt etme gücüne sahip olmayanlarda da tamdır.","D":"Yanlış. Kısıtlı bulunmama hali fiil ehliyetinin değerlendirilmesinde aranan şartlardandır.","E":"Yanlış. Temyiz kudreti fiil ehliyetiyle ilgilidir; hak ehliyeti için doğum anı yeterlidir."},"overall_explanation":"Hak ehliyeti bütün insanlarda sağ ve tam doğumla eşit şekilde kazanılır. Fiil ehliyetinden farklı olarak yaş, akıl sağlığı veya kısıtlılık gibi şartlara bağlanmamıştır."},{"id":"W3_Q3","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Devletin bireyin özel alanına müdahale etmemesini, bu alanda pasif kalmasını teminat altına alan negatif statü haklarına aşağıdakilerden hangisi örnek gösterilebilir?","tooltips":{"negatif statü hakları":"Bireyin devlet tarafından dokunulamayacak özerk alanını koruyan ve devlete müdahale etmeme ödevi yükleyen haklar."},"options":{"A":"Sosyal güvenlik hakkı","B":"Sağlık hizmeti alma hakkı","C":"Seçilme hakkı","D":"Konut dokunulmazlığı","E":"Dilekçe hakkı"},"correct_option":"D","explanations":{"A":"Yanlış. Sosyal güvenlik hakkı devletten teşkilatlanma ve harcama talep eden pozitif statü hakkıdır.","B":"Yanlış. Sağlık hakkı devletin olumlu edim ve tesis kurmasını gerektiren isteme hakkıdır.","C":"Yanlış. Seçilme hakkı siyasal hayata ve yönetime katılımı sağlayan aktif statü hakkıdır.","D":"Doğru. Konut dokunulmazlığı devletin bireyin özel yaşam alanına keyfi müdahalesini engelleyen koruyucu haklardandır.","E":"Yanlış. Dilekçe hakkı siyasal katılım ve denetim mekanizmasını işleten aktif statü hakkıdır."},"overall_explanation":"Negatif statü hakları devlete negatif bir kaçınma borcu yükler. Konut dokunulmazlığı, haberleşme hürriyeti ve mülkiyet hakkı bu gruptadır."},{"id":"W3_Q4","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Bireyin devletten olumlu bir hizmet, edim ve tesis talep etmesini sağlayan pozitif statü hakları arasında aşağıdakilerden hangisi yer alır?","tooltips":{"pozitif statü hakları":"Kişilerin devletten belirli bir edim, yardım veya hizmet sunmasını talep etme yetkisi veren sosyal ve ekonomik haklar."},"options":{"A":"Özel hayatın gizliliği","B":"Sağlık hizmeti alma hakkı","C":"Haberleşme hürriyeti","D":"Siyasi parti kurma hakkı","E":"Kişi hürriyeti ve güvenliği"},"correct_option":"B","explanations":{"A":"Yanlış. Özel hayatın gizliliği devletin müdahalesini engelleyen negatif statü hakkıdır.","B":"Doğru. Sağlık hakkı devletin hastane, personel ve teşkilat sağlamasını gerektiren pozitif statü hakkıdır.","C":"Yanlış. Haberleşme hürriyeti devletin pasif kalmasını gerektiren koruyucu haktır.","D":"Yanlış. Siyasi parti kurma hakkı siyasal yönetime katılmayı sağlayan aktif statü hakkıdır.","E":"Yanlış. Kişi hürriyeti ve güvenliği bireyin özerk alanını teminat altına alan negatif statü hakkıdır."},"overall_explanation":"Pozitif statü hakları devletin ekonomik ve sosyal alanda müdahalesini, harcama yapmasını ve bireye doğrudan hizmet sunmasını gerektiren haklardır."},{"id":"W3_Q5","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Jellinek sınıflandırmasında aktif statü hakları olarak nitelendirilen yetkilerin temel ayırıcı vasfı aşağıdakilerden hangisidir?","tooltips":{"aktif statü hakları":"Bireylerin devlet yönetimine, siyasal karar süreçlerine ve kamu mekanizmasına katılımını sağlayan siyasi haklar."},"options":{"A":"Toplumdaki herkese karşı ileri sürülebilmesi","B":"Para ile ölçülebilen ekonomik değer taşıması","C":"Devletin mali teşkilat kurmasını zorunlu kılması","D":"Miras yoluyla doğrudan mirasçılara geçmesi","E":"Yalnızca vatandaşlar tarafından kullanılabilmesi"},"correct_option":"E","explanations":{"A":"Yanlış. Herkese karşı ileri sürülebilme mutlak hakların belirleyici özelliğidir.","B":"Yanlış. Parayla ölçülebilirlik mal varlığı haklarının özelliğidir.","C":"Yanlış. Mali teşkilat ve harcama gereksinimi pozitif statü haklarında belirgindir.","D":"Yanlış. Aktif statü hakları siyasi nitelikli olup miras hukuku yoluyla devredilemez.","E":"Doğru. Aktif statü hakları münhasıran vatandaşlara tanınmış olup yabancılar bu haklardan yararlanamaz."},"overall_explanation":"Seçme, seçilme gibi aktif statü hakları devlet yönetimine katılma yetkisi verir ve yabancılara kapalı olup yalnızca vatandaşlık bağı taşıyanlara aittir."},{"id":"W3_Q6","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Özel hakların niteliklerine göre ayrımında mutlak hakları nispi haklardan ayıran temel hukuki özellik aşağıdakilerden hangisidir?","tooltips":{"mutlak haklar":"Hak sahibi tarafından toplumdaki herkese karşı ileri sürülebilen ve herkesin ihlal etmekten kaçınmakla yükümlü olduğu haklar.","nispi haklar":"Yalnızca belirli bir hukuki ilişkinin karşı tarafına karşı ileri sürülebilen haklar."},"options":{"A":"Toplumdaki herkese karşı ileri sürülebilmesi","B":"Yalnızca borç ilişkisinin muhatabına yöneltilmesi","C":"Zamanaşımına tabi olarak süre bitiminde düşmesi","D":"Tek taraflı irade açıklamasıyla hukuk düzenini kurması","E":"Kişinin bizzat iradesiyle başkasına devredilememesi"},"correct_option":"A","explanations":{"A":"Doğru. Mutlak haklar herkese karşı ileri sürülebilir ve toplumdaki herkes bu hakka saygı göstermekle yükümlüdür.","B":"Yanlış. Yalnızca belirli bir borçluya veya tarafa yöneltilmek nispi hakların vasfıdır.","C":"Yanlış. Mülkiyet gibi ayni mutlak haklar kural olarak zamanaşımına tabi değildir.","D":"Yanlış. Tek taraflı iradeyle hukuki sonuç doğurmak yenilik doğuran hakların özelliğidir.","E":"Yanlış. Mutlak haklardan olan mülkiyet ve fikri mülkiyet mali hakları başkalarına devredilebilir."},"overall_explanation":"Mutlak haklar herkese karşı dermeyan edilebilirken, nispi haklar yalnızca belirli bir hukuki ilişkinin tarafı olan şahsa karşı ileri sürülebilir."},{"id":"W3_Q7","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Aşağıdakilerden hangisi nispi hak niteliği taşımaktadır?","tooltips":{"nispi hak":"Sadece belirli bir hukuki muamelenin veya borç ilişkisinin karşı tarafına yöneltilebilen hak."},"options":{"A":"Bir taşınmaz üzerindeki mülkiyet hakkı","B":"Kişinin yaşam ve vücut bütünlüğü hakkı","C":"Bireyin adının korunmasını isteme yetkisi","D":"Alacaklının borçludan borcunu ödemesini isteme hakkı","E":"Fikir ve sanat eserleri üzerindeki manevi hak"},"correct_option":"D","explanations":{"A":"Yanlış. Mülkiyet hakkı ayni hak olup herkese karşı ileri sürülebilen mutlak bir haktır.","B":"Yanlış. Vücut bütünlüğü kişilik hakkı kapsamında olup herkese karşı korunan mutlak haktır.","C":"Yanlış. Adın korunması şahıs varlığına ilişkin mutlak bir haktır.","D":"Doğru. Alacak hakkı sadece borç ilişkisinin borçlusuna karşı ileri sürülebilen tipik bir nispi haktır.","E":"Yanlış. Eser sahibinin manevi hakları herkese karşı korunabilen mutlak haklardandır."},"overall_explanation":"Borç ilişkisinden doğan alacak hakları nispi haktır; alacaklı bu hakkı yalnızca sözleşmenin veya borcun karşı tarafı olan borçludan talep edebilir."},{"id":"W3_Q8","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Şahıs varlığı haklarının hukuki niteliğiyle ilgili olarak aşağıdakilerden hangisi doğrudur?","tooltips":{"Şahıs varlığı hakları":"Kişinin manevi alanına giren, kişiliğini koruyan, para ile ölçülemeyen ve kişiye sıkı sıkıya bağlı bulunan haklar."},"options":{"A":"Ticaret siciline tescil ile aleniyet kazanması","B":"Parayla ölçülememesi ve miras yoluyla intikal etmemesi","C":"Sözleşmeyle üçüncü kişilere devredilebilmesi","D":"Yalnızca kamu makamlarına karşı ileri sürülebilmesi","E":"İflas masasına dahil edilerek haczedilebilmesi"},"correct_option":"B","explanations":{"A":"Yanlış. Şahıs varlığı hakları ticaret sicili kayıtlarına tabi malvarlığı unsuru değildir.","B":"Doğru. Şahıs varlığı hakları ekonomik değer taşımaz, manevidir, kişiye sıkı sıkıya bağlıdır ve mirasla geçmez.","C":"Yanlış. Kişiye sıkı sıkıya bağlı olduklarından sözleşmeyle başkasına devredilemezler.","D":"Yanlış. Şahıs varlığı hakları herkese karşı korunabilen özel mutlak haklar arasındadır.","E":"Yanlış. Ekonomik değeri bulunmayan manevi haklar hacze veya iflas tasfiyesine konu edilemez."},"overall_explanation":"Şahıs varlığı hakları ekonomik bir karşılığı olmayan, devredilemeyen ve mirasçılara intikali mümkün bulunmayan manevi nitelikli haklardır."},{"id":"W3_Q9","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Aşağıdakilerden hangisi mal varlığı hakları kategorisinde yer alır?","tooltips":{"mal varlığı hakları":"Kişinin ekonomik alanına giren, para ile ölçülebilen ve kural olarak devredilebilen maddi haklar."},"options":{"A":"Nişanın bozulmasını talep hakkı","B":"Şeref ve haysiyetin korunması hakkı","C":"Taşınır bir eşya üzerindeki mülkiyet hakkı","D":"Adın değiştirilmesini dava etme yetkisi","E":"Evlilik birliğinin boşanma ile sona erdirilmesi hakkı"},"correct_option":"C","explanations":{"A":"Yanlış. Nişanı bozma hakkı kişiye sıkı sıkıya bağlı bir şahıs varlığı hakkıdır.","B":"Yanlış. Şeref ve haysiyet kişilik hakları kapsamındaki şahıs varlığı hakkıdır.","C":"Doğru. Eşya üzerindeki mülkiyet hakkı ekonomik değeri bulunan ve parayla ölçülen mal varlığı hakkıdır.","D":"Yanlış. Ad üzerindeki hak manevi nitelikte olup şahıs varlığı alanına girer.","E":"Yanlış. Boşanma hakkı aile hukukundan doğan ve kişiye sıkı sıkıya bağlı şahıs varlığı hakkıdır."},"overall_explanation":"Mülkiyet hakkı, alacak hakkı ve miras payı hakkı parayla ölçülebilir ekonomik bir menfaati temsil ettiğinden mal varlığı hakları grubundadır."},{"id":"W3_Q10","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Kişiye sıkı sıkıya bağlı olan ve bu sebeple miras yoluyla intikali ya da başkasına devri mümkün bulunmayan haklara ne ad verilir?","tooltips":{"Devredilemeyen haklar":"Hak sahibinin şahsına ayrılmaz biçimde bağlı olan, hukuki işlemle aktarılamayan ve mirasçılara geçmeyen haklar."},"options":{"A":"Alacak hakları","B":"Ayni haklar","C":"Mali haklar","D":"Fikri haklar","E":"Devredilemeyen haklar"},"correct_option":"E","explanations":{"A":"Yanlış. Alacak hakları kural olarak temlik edilebilir ve mirasçılara intikal eder.","B":"Yanlış. Mülkiyet gibi ayni haklar devredilebilir ve mirasla intikal edebilir.","C":"Yanlış. Mali haklar ekonomik nitelikte olup kural olarak devri kabildir.","D":"Yanlış. Fikri mülkiyetin mali hakları sözleşmeyle devredilebilir ve mirasla geçer.","E":"Doğru. Kişinin şahsına doğrudan bağlı haklar devredilemeyen haklar sınıfına girer."},"overall_explanation":"Devir kabiliyetine göre haklar devredilebilen ve devredilemeyen haklar olarak ikiye ayrılır; kişiye sıkı sıkıya bağlı haklar devredilemez niteliktedir."},{"id":"W3_Q11","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Yenilik doğuran hakların en belirleyici hukuki özelliği aşağıdakilerden hangisidir?","tooltips":{"Yenilik doğuran haklar":"Hak sahibinin tek taraflı irade beyanıyla yeni bir hukuki durum kuran, mevcut durumu değiştiren veya sona erdiren haklar."},"options":{"A":"Tek taraflı irade beyanıyla karşı tarafın onayına ihtiyaç duymaksızın sonuç doğurması","B":"Sadece kamu idaresi tarafından kullanıldığında geçerli sayılması","C":"Toplumdaki herkese karşı ileri sürülebilen ayni bir koruma sağlaması","D":"Kullanılmasıyla mevcut hukuki ilişkide hiçbir değişiklik meydana getirmemesi","E":"Mirasçılara intikal eden parasal bir malvarlığı talebi barındırması"},"correct_option":"A","explanations":{"A":"Doğru. Yenilik doğuran haklar tek taraflı irade beyanıyla karşı tarafın rızasına gerek olmaksızın sonuç yaratır.","B":"Yanlış. Yenilik doğuran haklar özel hukuk ilişkilerinde bireylerce de kullanılır.","C":"Yanlış. Herkese karşı ileri sürülebilirlik mutlak hakların özelliğidir; inşai haklar nispi ilişkilerde de doğar.","D":"Yanlış. Hukuki durumda değişiklik yaratmamak alelade hakların özelliğidir.","E":"Yanlış. Yenilik doğuran hakların tamamı parasal nitelikte veya mirasla devredilebilir değildir."},"overall_explanation":"İnşai haklar hak sahibinin tek taraflı irade açıklamasıyla muhatabın hukuk alanında doğrudan hukuki sonuç meydana getirir."},{"id":"W3_Q12","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Hak sahibinin tek taraflı irade açıklamasıyla daha önce mevcut olmayan yeni bir hukuki ilişki kurmasını sağlayan hak aşağıdakilerden hangisidir?","tooltips":{"Kurucu yenilik doğuran haklar":"Kullanılmasıyla yeni bir hukuki ilişki veya hak tesis eden inşai haklar."},"options":{"A":"Bozucu yenilik doğuran hak","B":"Kurucu yenilik doğuran hak","C":"Değiştirici yenilik doğuran hak","D":"Yenilik doğurmayan alelade hak","E":"Kamu hukuku katılım hakkı"},"correct_option":"B","explanations":{"A":"Yanlış. Bozucu inşai hak mevcut ilişkiyi tamamen ortadan kaldırır.","B":"Doğru. Tek taraflı beyanla yeni bir hukuki durum vücuda getiren hak kurucu inşai haktır.","C":"Yanlış. Değiştirici inşai hak var olan ilişkinin şartlarını değiştirir.","D":"Yanlış. Alelade haklar yeni bir hukuki durum oluşturmaz, mevcut durumun icrasını sağlar.","E":"Yanlış. Kamu katılım hakları siyasi haklar kapsamında yer alır."},"overall_explanation":"Yenilik doğuran haklar etkilerine göre kurucu, değiştirici ve bozucu olarak üçe ayrılır. Yeni bir ilişki kuran haklar kurucu niteliktedir."},{"id":"W3_Q13","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Satın aldığı televizyonun ayıplı çıkması üzerine alıcının sözleşmeyi feshetmeksizin satış bedelinden indirim talep etmesi hangi hak türünün kullanımına örnektir?","tooltips":{"satış bedelinden indirim":"Ayıplı ifa karşısında sözleşmeyi ayakta tutarak ödeme borcunun miktarını tek taraflı iradeyle azaltma yetkisi."},"options":{"A":"Kurucu yenilik doğuran hak","B":"Bozucu yenilik doğuran hak","C":"Yenilik doğurmayan alelade hak","D":"Mutlak ayni hak","E":"Değiştirici yenilik doğuran hak"},"correct_option":"E","explanations":{"A":"Yanlış. Burada yeni bir sözleşme kurulmamakta, mevcut sözleşme sürdürülmektedir.","B":"Yanlış. Sözleşme ortadan kaldırılmadığından bozucu nitelik taşımaz.","C":"Yanlış. Bedel miktarında değişiklik yaratıldığından alelade hak değildir.","D":"Yanlış. Ayıp karşısında bedel indirimi ayni mutlak hak değil, nispi borç ilişkisinde inşai bir haktır.","E":"Doğru. Sözleşme sona erdirilmeden içeriği ve edim miktarı tek taraflı değiştirildiğinden değiştirici yenilik doğuran haktır."},"overall_explanation":"Mevcut hukuki bağı ortadan kaldırmadan yalnızca edimin şartlarını ve içeriğini değiştiren yetkiler değiştirici yenilik doğuran haklardır."},{"id":"W3_Q14","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Aşağıdakilerden hangisi bozucu yenilik doğuran bir hakkın kullanımına örnek teşkil eder?","tooltips":{"bozucu yenilik doğuran hak":"Tek taraflı irade bildirimiyle mevcut hukuki ilişkiyi tamamen sona erdiren inşai hak."},"options":{"A":"Alım hakkının kullanılarak satış akdinin yapılması","B":"Ayıplı eşya için ücretsiz tamir talep edilmesi","C":"İşverenin iş sözleşmesini haklı nedenle feshetmesi","D":"Kiracının konutta oturmaya devam etmesi","E":"Önalım hakkı bildirimi ile payın talep edilmesi"},"correct_option":"C","explanations":{"A":"Yanlış. Alım hakkının kullanılması yeni bir satış ilişkisi kurduğundan kurucu inşai haktır.","B":"Yanlış. Ücretsiz tamir talebi sözleşmeyi sonlandırmayıp içeriğini değiştiren değiştirici haktır.","C":"Doğru. Fesih bildirimi mevcut hukuki ilişkiyi tek taraflı iradeyle tamamen sona erdiren bozucu inşai haktır.","D":"Yanlış. Kiracının konutta oturması var olan hukuki durumu sürdüren yenilik doğurmayan haktır.","E":"Yanlış. Önalım hakkı yeni bir hukuki satın alma ilişkisi tesis eden kurucu inşai haktır."},"overall_explanation":"İş sözleşmesinin feshi, kira sözleşmesinin feshi veya nişanın bozulması mevcut bağı tek taraflı olarak sona erdirdiğinden bozucu yenilik doğuran haktır."},{"id":"W3_Q15","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Kullanılmasıyla mevcut hukuki durumu değiştirmeyen, var olan yetkinin olağan şekilde icrasını sağlayan haklara ne ad verilir?","tooltips":{"Alelade haklar":"Kullanıldığında mevcut hukuki yapıyı değiştirmeyip sadece var olan ilişkinin olağan seyrini sağlayan yenilik doğurmayan haklar."},"options":{"A":"Kurucu haklar","B":"Bozucu haklar","C":"Değiştirici haklar","D":"Yenilik doğurmayan haklar","E":"Mutlak inşai haklar"},"correct_option":"D","explanations":{"A":"Yanlış. Kurucu haklar yeni hukuki durum vücuda getiren inşai haklardır.","B":"Yanlış. Bozucu haklar hukuki ilişkiyi ortadan kaldıran inşai haklardır.","C":"Yanlış. Değiştirici haklar mevcut durumu farklılaştıran inşai haklardır.","D":"Doğru. Hukuki durumda bir yenilik meydana getirmeyen haklar yenilik doğurmayan diğer adıyla alelade haklardır.","E":"Yanlış. İnşai haklar doğası gereği hukuki durumu kurar, değiştirir ya da bozar."},"overall_explanation":"Yenilik doğurmayan haklar kullanılırken hukuki ilişkide herhangi bir yapısal değişiklik meydana gelmez; mevcut hakkın olağan kullanımı gerçekleşir."},{"id":"W3_Q16","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Hak ehliyeti ile fiil ehliyeti arasındaki ilişki bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"Fiil ehliyeti":"Kişinin bizzat kendi fiil ve işlemleriyle hak kazanabilme ve borç altına girebilme kudreti."},"options":{"A":"Hak ehliyeti erginlikle başlarken fiil ehliyeti doğumla kazanılır","B":"Tüm insanlar hak ehliyetine eşit sahipken fiil ehliyeti belirli koşullara bağlıdır","C":"Fiil ehliyeti mirasla intikal ederken hak ehliyeti devredilemez niteliktedir","D":"Hak ehliyeti yalnızca tüzel kişilere, fiil ehliyeti gerçek kişilere tanınmıştır","E":"Fiil ehliyeti bulunmayan kişilerin hiçbir şekilde hak ehliyeti de bulunmaz"},"correct_option":"B","explanations":{"A":"Yanlış. Hak ehliyeti doğumla başlar, fiil ehliyeti erginlik ve diğer şartlara bağlıdır.","B":"Doğru. Hak ehliyeti bakımından bütün insanlar doğuştan eşittir; fiil ehliyeti ise ayırt etme gücü, yaş ve kısıtlı olmama gibi şartlara tabidir.","C":"Yanlış. Fiil ehliyeti şahsa sıkı sıkıya bağlı olup miras yoluyla intikal etmez.","D":"Yanlış. Gerçek kişiler de hak ehliyetine tam olarak sahiptir.","E":"Yanlış. Küçüklerin veya akıl hastalarının fiil ehliyeti olmasa da hak ehliyetleri tam ve mevcuttur."},"overall_explanation":"Hak ehliyeti hak sahibi olabilme yeteneğidir ve tüm insanlarda eşittir. Fiil ehliyeti ise hakları bizzat kullanabilme iktidarı olup belirli şartlara bağlıdır."},{"id":"W3_Q17","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Kişinin bizzat kendi irade beyanıyla hak edinebilmesi ve borç altına girebilmesi için gereken fiil ehliyetinin şartları aşağıdakilerden hangisinde birlikte verilmiştir?","tooltips":{"Erginlik":"Hukuken reşit olma, kural olarak on sekiz yaşın tamamlanmasıyla elde edilen hukuki statü.","Ayırt etme gücü":"Kişinin eylem ve işlemlerinin sebep ve sonuçlarını makul şekilde kavrayabilme yeteneği."},"options":{"A":"Ergin olmak, ayırt etme gücüne sahip olmak ve kısıtlı bulunmamak","B":"Sağ doğmak, vatandaş olmak ve kamu haklarından mahrum olmamak","C":"Reşit olmak, askerliğini yapmak ve malvarlığı sahibi bulunmak","D":"Sabıkasız olmak, medeni hakları taşımak ve yükseköğrenim görmek","E":"Ticaret siciline kayıtlı olmak, borçsuz olmak ve ergin bulunmak"},"correct_option":"A","explanations":{"A":"Doğru. Fiil ehliyetinin üç temel şartı ergin olmak, ayırt etme gücüne sahip olmak ve kısıtlı olmamaktır.","B":"Yanlış. Vatandaşlık veya kamu hakları fiil ehliyetinin medeni hukuktaki genel şartları arasında sayılmaz.","C":"Yanlış. Askerlik ve malvarlığı varlığı ehliyet şartı değildir.","D":"Yanlış. Sabıka durumu veya eğitim düzeyi fiil ehliyeti şartlarından değildir.","E":"Yanlış. Ticaret sicili kaydı veya borçsuzluk fiil ehliyetinin genel unsuru değildir."},"overall_explanation":"Türk Medeni Kanunu uyarınca fiil ehliyetine sahip olabilmek için ayırt etme gücünün bulunması, ergin olunması ve kısıtlı olunmaması gerekir."},{"id":"W3_Q18","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Tüzel kişilerin yapısına göre tasnifinde aşağıdakilerden hangisi mal topluluğu niteliğindeki tüzel kişilere örnektir?","tooltips":{"Mal topluluğu":"Belirli ve sürekli bir gayeye tahsis edilmiş bağımsız mal varlığının tüzel kişilik kazanmasıyla oluşan yapı."},"options":{"A":"Dernek","B":"Sendika","C":"Siyasi parti","D":"Meslek odası","E":"Vakıf"},"correct_option":"E","explanations":{"A":"Yanlış. Dernekler kişi topluluğu niteliğinde tüzel kişilerdir.","B":"Yanlış. Sendikalar çalışanların bir araya gelmesiyle kurulan kişi topluluğudur.","C":"Yanlış. Siyasi partiler siyasal gayeli kişi topluluklarıdır.","D":"Yanlış. Meslek odaları kamu kurumu niteliğinde kişi topluluklarıdır.","E":"Doğru. Vakıflar belirli bir amaca tahsis edilmiş bağımsız mal topluluğu tüzel kişileridir."},"overall_explanation":"Tüzel kişiler kişi toplulukları ve mal toplulukları olarak ayrılır. Vakıflar bağımsız mal varlığı esasına dayanan tipik mal topluluğudur."},{"id":"W3_Q19","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Kişi topluluğu niteliğindeki tüzel kişilerden olan derneklerin temel kuruluş amacı ve mali rejimiyle ilgili olarak aşağıdakilerden hangisi doğrudur?","tooltips":{"Dernekler":"Kazanç paylaşma amacı gütmeksizin belirli ve ortak bir amacı gerçekleştirmek üzere kurulan kişi toplulukları."},"options":{"A":"Kurulabilmeleri için yetkili bakanlıktan önceden izin alınması şarttır","B":"Sadece ticaret siciline tescil edilmek suretiyle tüzel kişilik kazanırlar","C":"Kazanç paylaşma amacı güdemez ve üyelerine kâr payı dağıtamazlar","D":"Yalnızca kamu görevlileri ve memurlar tarafından teşkil edilebilirler","E":"Mal topluluğu sayıldıklarından asgari sermaye koyma mecburiyeti vardır"},"correct_option":"C","explanations":{"A":"Yanlış. Dernekler önceden izin almaksızın serbestçe kurulurlar.","B":"Yanlış. Ticaret siciline tescil ticari şirketler içindir; dernekler kuruluş bildirimiyle tüzel kişilik kazanır.","C":"Doğru. Dernekler kazanç paylaşma amacı güdemez ve üyelerine kâr payı dağıtamaz.","D":"Yanlış. Fiil ehliyetine sahip gerçek veya tüzel kişiler dernek kurabilir.","E":"Yanlış. Dernekler mal topluluğu değil kişi topluluğudur."},"overall_explanation":"Dernekler kazanç paylaşma amacı gütmeyen kişi topluluklarıdır; iktisadi işletme açabilseler dahi elde edilen kârı üyelerine dağıtamazlar."},{"id":"W3_Q20","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Sendikalar Kanunu uyarınca sendika kurabilme hakkına ilişkin sübjektif sınırlama bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"Sendikalar":"İşçilerin veya kamu görevlilerinin mesleki hak ve menfaatlerini korumak amacıyla kurdukları kişi toplulukları."},"options":{"A":"Mahkeme kararıyla izin alınmadıkça hiçbir şekilde teşkilat kurulamaz","B":"Yalnızca bağımsız mal varlığı tahsis edilerek mal topluluğu şeklinde oluşturulur","C":"On sekiz yaşını bitirmiş her Türkiye Cumhuriyeti vatandaşı tarafından kurulabilir","D":"Yalnızca kanunun belirlediği işçiler ve kamu görevlileri tarafından kurulabilir","E":"Kurulabilmeleri için üyelerinin tamamının yükseköğrenim mezunu olması zorunludur"},"correct_option":"D","explanations":{"A":"Yanlış. Sendika kuruluşu önceden mahkeme iznine tabi değildir.","B":"Yanlış. Sendikalar mal topluluğu değil, mesleki kişi topluluğudur.","C":"Yanlış. Çalışan sıfatı taşımayanlar vatandaş olsalar dahi sendika kuramaz.","D":"Doğru. Sendikalar münhasıran işçi ve kamu görevlileri memurlar tarafından kurulabilen örgütlenmelerdir.","E":"Yanlış. Sendika üyeliği veya kuruculuğu için yükseköğrenim şartı bulunmaz."},"overall_explanation":"Sendikalar Kanunu kapsamında sendika tüzel kişiliği yalnızca çalışan statüsündeki işçiler ve memurlar tarafından kazanılabilir."},{"id":"W3_Q21","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Bir grup üniversite öğrencisi haklarını korumak amacıyla öğrenci sendikası kurmak üzere idareye başvurmuştur. Bu hukuki girişimin neticesi aşağıdakilerden hangisidir?","tooltips":{"sendika tüzel kişiliği":"Çalışanların hak ve menfaatlerini koruma amacıyla mevzuata uygun şekilde kazanılan tüzel kişilik."},"options":{"A":"Doğrudan siyasi parti tüzel kişiliği statüsünde tescil edilir","B":"Sendika tüzel kişiliği kazanamaz, şartları varsa dernek statüsünde kalır","C":"Mal topluluğu kabul edilerek doğrudan vakıf siciline kaydedilir","D":"Öğrencilerin fiil ehliyeti bulunmadığından girişim hukuken yok sayılır","E":"Ticaret mahkemesi tarafından ticari işletme olarak tescil olunur"},"correct_option":"B","explanations":{"A":"Yanlış. Siyasi partiler genel siyasete katılım amaçlı kurulur, öğrenci örgütlenmesi doğrudan siyasi parti sayılmaz.","B":"Doğru. İşçi veya kamu görevlisi statüsünde bulunmayan öğrencilerin örgütlenmesi sendika olamaz, Dernekler Kanunu hükümlerine tabi dernek statüsünde kalır.","C":"Yanlış. Öğrenci kuruluşu mal topluluğu değildir ve vakıf niteliği taşımaz.","D":"Yanlış. Ergin üniversite öğrencilerinin fiil ehliyeti mevcuttur.","E":"Yanlış. Kâr ve kazanç amacı bulunmayan faaliyetler ticari işletme olarak kaydedilmez."},"overall_explanation":"Kanunun belirlediği çalışan statüsünde olmayan öğrencilerin örgütlenmesi Sendikalar Kanunu kapsamında sendika tüzel kişiliği kazanamaz, dernek statüsünde değerlendirilir."},{"id":"W3_Q22","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Temel bir hakkın kamu menfaati gereğince sınırlandırılmasında ölçülülük ilkesinin sağlanabilmesi için aranan üç anayasal alt ölçüt aşağıdakilerden hangisinde doğru sıralanmıştır?","tooltips":{"ölçülülük ilkesi":"Temel hakların sınırlandırılmasında kullanılan araç ile ulaşılmak istenen amaç arasındaki dengeyi denetleyen ilke."},"options":{"A":"Eşitlik, adalet ve hakkaniyet","B":"Yasallık, belirlilik ve geriye yürümezlik","C":"Kusurluluk, şahsilik ve aleniyet","D":"Dürüstlük, iyiniyet ve ahde vefa","E":"Elverişlilik, gereklilik ve orantılılık"},"correct_option":"E","explanations":{"A":"Yanlış. Eşitlik ve adalet genel hukuk ilkeleridir, ölçülülüğün alt unsurları değildir.","B":"Yanlış. Bu ilkeler ceza hukuku ve hukuki güvenlik ilkeleridir.","C":"Yanlış. Kusurluluk ve şahsilik ceza sorumluluğuna ilişkindir.","D":"Yanlış. İyiniyet ve dürüstlük medeni hukukun temel ilkelerindendir.","E":"Doğru. Ölçülülük ilkesi elverişlilik, gereklilik ve orantılılık olmak üzere üç alt unsurdan teşekkül eder."},"overall_explanation":"Anayasa m. 13 bağlamında temel hak ve hürriyetlerin sınırlandırılmasında ölçülülük denetimi elverişlilik, gereklilik ve orantılılık unsurları üzerinden yürütülür."},{"id":"W3_Q23","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Ölçülülük ilkesinin alt unsurlarından biri olan elverişlilik kavramı aşağıdakilerden hangisini ifade eder?","tooltips":{"elverişlilik":"Sınırlandırma için seçilen aracın meşru kamu amacını gerçekleştirmeye fiilen uygun olması şartı."},"options":{"A":"Başvurulan sınırlandırma aracının ulaşılmak istenen meşru amacı gerçekleştirmeye uygun olması","B":"Hedefe ulaştıracak vasıtalar arasından bireye en az zarar veren hafif aracın seçilmesi","C":"Kamu menfaati ile sınırlandırılan temel hak arasında adil ve makul bir dengenin kurulması","D":"Sınırlandırmanın yalnızca yargı makamlarınca verilen kesinleşmiş hükümlere dayanması","E":"Müdahale sonucunda temel hakkın özüne hiçbir surette dokunulmamış bulunması"},"correct_option":"A","explanations":{"A":"Doğru. Elverişlilik, seçilen aracın öngörülen amaca ulaşmaya uygun ve elverişli olmasını ifade eder.","B":"Yanlış. En hafif ve en az zedeleyen aracın seçilmesi gereklilik unsurudur.","C":"Yanlış. Menfaatler arasında makul denge bulunması orantılılık unsurudur.","D":"Yanlış. Elverişlilik müdahalenin idari veya yargısal kaynağıyla değil, aracın niteliğiyle ilgilidir.","E":"Yanlış. Hakkın özüne dokunmama ölçülülükten ayrı bir anayasal sınırlama sınırıdır."},"overall_explanation":"Elverişlilik ilkesi, kamu gücünün başvurduğu tedbirin hedeflenen meşru gayeyi gerçekleştirmeye elverişli ve amaca hizmet eder nitelikte bulunmasını gerektirir."},{"id":"W3_Q24","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Ulaşılmak istenen kamu yararı bakımından hedefe ulaştıracak en hafif ve bireyin hakkını en az zedeleyen aracın seçilmesini emreden ölçülülük unsuru aşağıdakilerden hangisidir?","tooltips":{"gereklilik":"Aynı hedefe daha hafif bir tedbirle ulaşma imkânı varken daha ağır sınırlamaya başvurulmamasını gerektiren ölçüt."},"options":{"A":"Kanunilik","B":"Elverişlilik","C":"Gereklilik","D":"Hakkaniyet","E":"Belirlilik"},"correct_option":"C","explanations":{"A":"Yanlış. Kanunilik sınırlamanın mutlaka kanunla yapılmasını ifade eder.","B":"Yanlış. Elverişlilik aracın amacı sağlamaya uygun olup olmadığını inceler.","C":"Doğru. Amaca ulaştıracak en hafif ve en az sınırlandırıcı tedbirin seçilmesini gereklilik ilkesi denetler.","D":"Yanlış. Hakkaniyet somut olay adaletiyle ilgili genel ilkedir.","E":"Yanlış. Belirlilik kuralın açık ve öngörülebilir olmasını ifade eder."},"overall_explanation":"Gereklilik unsuru uyarınca eğer amaca daha hafif bir müdahaleyle ulaşmak mümkünse, temel hakkı daha ağır şekilde zedeleyen aracın seçilmesi hukuka aykırıdır."},{"id":"W3_Q25","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Temel hakkın sınırlandırılmasında elde edilmek istenen kamu menfaati ile kısıtlanan hakkın ağırlığı arasında makul bir dengenin gözetilmesini denetleyen ölçüt hangisidir?","tooltips":{"orantılılık":"Müdahaleyle elde edilen kamu yararı ile bireyin katlanmak zorunda kaldığı külfet arasındaki makul denge."},"options":{"A":"Belirlilik","B":"Elverişlilik","C":"Gereklilik","D":"Orantılılık","E":"Genellik"},"correct_option":"D","explanations":{"A":"Yanlış. Belirlilik düzenlemenin anlaşılır ve net olması zorunluluğudur.","B":"Yanlış. Elverişlilik tedbirin amaca uygunluğu ile ilgilidir.","C":"Yanlış. Gereklilik en hafif tedbirin tercih edilip edilmediğini araştırır.","D":"Doğru. Kamu yararı ile bireyin hakkına getirilen külfet arasında adil bir dengenin kurulması orantılılık ilkesinin gereğidir.","E":"Yanlış. Genellik kuralların herkese uygulanabilir olmasını ifade eder."},"overall_explanation":"Orantılılık dar anlamda ölçülülük olup sınırlamayla sağlanan kamusal yarar ile bireye yüklenen fedakarlık arasında ölçüsüz bir dengesizlik bulunmamasını zorunlu kılar."},{"id":"W3_Q26","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Bir taşınmaz maliki ile o taşınmazda kira sözleşmesiyle ikamet eden kiracının hakları karşılaştırıldığında aşağıdakilerden hangisi hukuken doğrudur?","tooltips":{"Mülkiyet hakkı":"Bir eşya üzerinde sahibine kullanma, yararlanma ve tasarrufta bulunma yetkisi veren ayni hak.","kira sözleşmesi":"Kiraya verenin bir şeyin kullanılmasını kiracıya bırakmayı, kiracının da kira bedelini ödemeyi üstlendiği sözleşme."},"options":{"A":"Kiracının hakkı ayni hak iken malikin hakkı nispi niteliktedir","B":"Kiracının hakkı herkese karşı, malikin hakkı yalnızca kiracıya karşı ileri sürülür","C":"Her iki hak da zamanaşımına uğrayarak kendiliğinden ortadan kalkar","D":"Malik hakkını velisi aracılığıyla kullanırken kiracı bizzat kullanmak zorundadır","E":"Malikin hakkı mutlak hak iken kiracının hakkı nispi hak niteliği taşır"},"correct_option":"E","explanations":{"A":"Yanlış. Mülkiyet hakkı ayni haktır, kira ilişkisi ise şahsi borç ilişkisidir.","B":"Yanlış. Mülkiyet herkese karşı, kira hakkı ise kural olarak sadece sözleşmenin tarafına karşı ileri sürülür.","C":"Yanlış. Mülkiyet hakkı zamanaşımına tabi değildir.","D":"Yanlış. Fiil ehliyetine sahip olan her malik hakkını bizzat kendisi kullanır.","E":"Doğru. Mülkiyet hakkı herkese karşı ileri sürülebilen mutlak haktır; kira sözleşmesinden doğan hak ise nispi bir haktır."},"overall_explanation":"Mülkiyet hakkı mutlak nitelikte ayni bir hak olup herkese karşı korunurken, kira hakkı sözleşmeden doğan nispi bir hak olup sadece kiralayana karşı ileri sürülebilir."},{"id":"W3_Q27","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Hukuk düzeni tarafından korunan ve sahibine bu korunmadan yararlanma yetkisi tanınan menfaate ne ad verilir?","tooltips":{"menfaat":"Kişinin maddi veya manevi alanda elde etmeyi amaçladığı, korunmaya değer yarar."},"options":{"A":"Ödev","B":"Hak","C":"Borç","D":"Kural","E":"Adalet"},"correct_option":"B","explanations":{"A":"Yanlış. Ödev, bireye hukuk düzeni tarafından yüklenen yükümlülüktür.","B":"Doğru. Hukuk düzenince korunan ve sahibine korunmadan yararlanma iktidarı verilen menfaat hak olarak tanımlanır.","C":"Yanlış. Borç, borçlunun alacaklıya karşı yerine getirmekle yükümlü olduğu edimdir.","D":"Yanlış. Kural, toplumsal davranışı düzenleyen soyut normdur.","E":"Yanlış. Adalet, hukuki uyuşmazlığın çözümüyle varılan nihai dengedir."},"overall_explanation":"Menfaat teorisi ve irade teorisinin birleşimiyle modern hukukta hak, hukuken korunan ve sahibine bu himayeden yararlanma yetkisi bahşedilen menfaat şeklinde tanımlanır."},{"id":"W3_Q28","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Önalım hakkı sahibinin bu hakkını tek taraflı irade beyanıyla kullanarak taşınmazın kendi adına devredilmesini talep etmesi hangi hak türüne örnektir?","tooltips":{"Önalım hakkı":"Bir taşınmazın üçüncü kişiye satılması hâlinde hak sahibine öncelikle satın alma yetkisi veren inşai hak."},"options":{"A":"Bozucu yenilik doğuran hak","B":"Değiştirici yenilik doğuran hak","C":"Kurucu yenilik doğuran hak","D":"Yenilik doğurmayan alelade hak","E":"Nispi borç ilişkisi hakkı"},"correct_option":"C","explanations":{"A":"Yanlış. Bozucu haklar hukuki ilişkiyi ortadan kaldırır; önalım hakkı ise yeni bir alım ilişkisi kurar.","B":"Yanlış. Değiştirici haklar mevcut bir ilişkinin bedelini veya şartını değiştirir.","C":"Doğru. Önalım hakkı tek taraflı irade beyanıyla alıcı ile satıcı arasında doğrudan satış ilişkisi tesis ettiğinden kurucudur.","D":"Yanlış. Alelade haklar yeni bir hukuki bağ kurmaz, mevcut bağın olağan kullanımını sağlar.","E":"Yanlış. Önalım hakkı borç ilişkisinden doğsa da etkisi bakımından kurucu inşai bir haktır."},"overall_explanation":"Alım, önalım ve geri alım hakları tek taraflı beyanla önceden var olmayan bir satış ilişkisini kurdukları için kurucu yenilik doğuran haklardandır."},{"id":"W3_Q29","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Aşağıdaki tüzel kişilerden hangisi kişi topluluğu niteliğindedir?","tooltips":{"kişi topluluğu":"Birden çok kişinin ortak bir gayeyi gerçekleştirmek üzere iradelerini birleştirmesiyle kurulan tüzel kişi."},"options":{"A":"Siyasi parti","B":"Vakıf","C":"Anonim şirket","D":"Limited şirket","E":"Bağımsız mal varlığı fonu"},"correct_option":"A","explanations":{"A":"Doğru. Siyasi partiler ortak siyasi amaç doğrultusunda teşkilatlanan bağımsız kişi topluluklarıdır.","B":"Yanlış. Vakıflar amaca tahsis edilen mal varlığından teşekkül eden mal topluluklarıdır.","C":"Yanlış. Ticari şirketler sermaye esasına dayalı iktisadi mal topluluklarıdır.","D":"Yanlış. Limited şirketler sermayenin bir araya getirilmesiyle kurulan mal ortaklığı tüzel kişileridir.","E":"Yanlış. Fon yapıları kişi değil bağımsız mal topluluğu tüzel kişileridir."},"overall_explanation":"Dernekler, siyasi partiler ve sendikalar kişi topluluğu statüsünde tüzel kişiler iken; vakıflar ve şirketler mal ve sermaye topluluğu niteliğindedir."},{"id":"W3_Q30","domain_id":3,"domain_name":"Hafta 3: Hakların Türleri, Kişilik ve Ehliyet","question":"Ayırt etme gücüne sahip olmayan yedi yaşındaki bir çocuğun hukuki statüsü ve hak sahipliği bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"küçük":"Henüz on sekiz yaşını doldurmamış ve ergin kılınmamış gerçek kişi."},"options":{"A":"Hak ehliyeti de bulunmadığından hiçbir hak ve borca taraf olamaz","B":"Bütün hukuki muameleleri tek başına geçerli olarak gerçekleştirebilir","C":"Kamu haklarından ömür boyu mutlak şekilde mahrum bırakılır","D":"Hak ehliyeti tamdır ancak haklarını kanuni temsilcisi aracılığıyla kullanır","E":"Cezai sorumluluğu ergin kişilerle tamamen aynı kurallara tabidir"},"correct_option":"D","explanations":{"A":"Yanlış. Doğumla birlikte hak ehliyeti tam olarak kazanılır.","B":"Yanlış. Ayırt etme gücü ve erginliği bulunmayan küçüğün tek başına işlem yapma iktidarı yoktur.","C":"Yanlış. Yaş küçüklüğü kamu haklarından süresiz mahrumiyet sebebi değildir.","D":"Doğru. Çocuk sağ doğmakla hak ehliyetine sahiptir; fakat fiil ehliyeti olmadığından hakları kanuni temsilcisi velisi vasıtasıyla kullanılır.","E":"Yanlış. Ayırt etme gücü olmayan küçüklerin cezai sorumluluğu bulunmaz."},"overall_explanation":"Hak ehliyetine tüm insanlar doğuştan eşit şekilde sahiptir. Fiil ehliyeti bulunmayanlar hak edinebilir ve borç altına girebilir ancak işlemleri kanuni temsilcileri yerine getirir."}]'))},19698,a=>{a.v(JSON.parse('[{"id":"W4_Q1","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Suç ile hukuka aykırılık arasındaki kapsam ilişkisine ilişkin aşağıdaki ifadelerden hangisi doğrudur?","tooltips":{"hukuka aykırılık":"Hukuk düzeninin emir veya yasaklarına aykırı düşen her türlü eylem veya durum.","suç":"Ceza kanunlarında açıkça tanımlanmış ve karşılığında hapis veya adli para cezası yaptırımı öngörülmüş eylem."},"options":{"A":"Her hukuka aykırı fiil zorunlu olarak bir ceza hukuku suçu teşkil eder","B":"Suç kavramı hukuka aykırılığı da içine alan daha geniş kapsamlı bir üst çatı kavramdır","C":"Her suç hukuka aykırılık barındırır ancak her hukuka aykırı fiil suç teşkil etmez","D":"Suç ile hukuka aykırılık tamamen bağımsız olup ortak hiçbir ortak kesişim kümesi barındırmaz","E":"Hukuka aykırılık yalnızca ceza hukuku alanında ortaya çıkabilen özel bir kavramdır"},"correct_option":"C","explanations":{"A":"Yanlış. Hukuka aykırılık genel çatı kavram olup tazminat veya iptal gibi farklı yaptırımlara da bağlanabilir; her hukuka aykırılık suç değildir.","B":"Yanlış. Hukuka aykırılık üst kavram, suç ise bu alanın ceza yaptırımına bağlanmış daha dar kapsamlı özel bir parçasıdır.","C":"Doğru. Suç teşkil eden her eylem zorunlu olarak hukuka aykırıdır; fakat özel hukuk veya idare hukukundaki her hukuka aykırılık suç vasfı taşımaz.","D":"Yanlış. Suç ve hukuka aykırılık bağımsız değildir; suç, hukuka aykırılığın bir alt kümesini oluşturur.","E":"Yanlış. Hukuka aykırılık medeni hukuk, borçlar hukuku ve idare hukuku gibi hukukun bütün dallarında ortaya çıkabilir."},"overall_explanation":"Hukuka aykırılık hukuk düzeniyle çelişen tüm eylemleri kapsayan genel bir üst kavramdır. Suç ise ceza kanunlarında hürriyeti bağlayıcı veya adli para cezasına bağlanmış özel bir hukuka aykırılık türüdür."},{"id":"W4_Q2","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Ceza yargılamasında şüpheli sıfatının sanık sıfatına dönüştüğü yargısal eşik aşağıdakilerden hangisidir?","tooltips":{"şüpheli":"Soruşturma evresinde suç şüphesi altında bulunan kişi.","sanık":"Kovuşturmanın başlamasından hükmün kesinleşmesine kadar suç isnadı altında bulunan kişi.","iddianame":"Cumhuriyet savcısının soruşturma sonucunda elde ettiği delillere dayanarak kamu davası açmak için mahkemeye sunduğu belge."},"options":{"A":"Cumhuriyet savcılığı tarafından düzenlenen iddianamenin yetkili mahkemece kabulü","B":"Kolluk görevlileri tarafından ilk ifade alma işleminin tamamlanması","C":"Yetkili mahkeme tarafından sanık hakkında mahkûmiyet kararının tefhim edilmesi","D":"İlk derece mahkemesi kararının istinaf incelemesinden geçerek kesinleşmesi","E":"Cumhuriyet savcılığı tarafından suç ihbarının kayıtlara geçirilmesi"},"correct_option":"A","explanations":{"A":"Doğru. İddianamenin mahkemece kabulü ile soruşturma evresi sona erip kovuşturma başlar; birey şüpheli sıfatından sanık sıfatına geçer.","B":"Yanlış. İfade alma işlemi soruşturma evresinin bir parçasıdır ve bireyin şüpheli sıfatını sanığa dönüştürmez.","C":"Yanlış. Mahkûmiyet kararının tefhimi yargılamanın sonuna ilişkindir; kişi bu andan önce de zaten sanık sıfatını taşımaktadır.","D":"Yanlış. Kararın kesinleşmesiyle sanık sıfatı sona erer ve kişi hükümlü sıfatını alır.","E":"Yanlış. Suç ihbarının yapılması soruşturma evresini başlatan ilk adımdır ve kişiye ancak şüpheli sıfatı kazandırabilir."},"overall_explanation":"İddianamenin mahkemece kabul edilmesi, ceza yargılamasını soruşturmadan kovuşturmaya taşıyan ve suç isnadı altındaki kişinin sıfatını şüpheliden sanığa dönüştüren temel yargısal andır."},{"id":"W4_Q3","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Aşağıdakilerden hangisi doğrudan kamu hukukunun alt dalları arasında yer alır?","tooltips":{"kamu hukuku":"Devlet ile bireyler arasındaki astlık üstlük ilişkilerini ve kamu gücünün kullanımını düzenleyen kurallar bütünü."},"options":{"A":"Miras Hukuku","B":"Ticaret Hukuku","C":"Borçlar Hukuku","D":"İdare Hukuku","E":"Eşya Hukuku"},"correct_option":"D","explanations":{"A":"Yanlış. Miras Hukuku, Medeni Hukukun bir alt dalı olup özel hukuk kapsamındadır.","B":"Yanlış. Ticaret Hukuku eşit süjeler arasındaki ticari ilişkileri tanzim eden bir özel hukuk dalıdır.","C":"Yanlış. Borçlar Hukuku irade serbestisi zemininde alacak-borç ilişkilerini düzenleyen bir özel hukuk dalıdır.","D":"Doğru. İdare Hukuku devletin idari teşkilatını, kamu personeli rejimini ve kamu gücü işlemlerini düzenleyen temel bir kamu hukuku dalıdır.","E":"Yanlış. Eşya Hukuku, Medeni Hukukun bir alt kolu olup özel hukuk tasnifine girer."},"overall_explanation":"İdare Hukuku, Anayasa Hukuku ve Ceza Hukuku ile birlikte kamu gücünün ve kamusal düzenin tanzim edildiği kamu hukuku ana çatısı altında bulunur."},{"id":"W4_Q4","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Suç teşkil eden fiiller ile bu fiillere uygulanacak cezaların yalnızca yasama organı tarafından çıkarılan kanunla belirlenebilmesini zorunlu kılan ceza hukuku ilkesi aşağıdakilerden hangisidir?","tooltips":{"kanunilik ilkesi":"Suçların ve cezaların ancak yetkili yasama organınca yürürlüğe konulmuş yazılı kanunla ihdas edilebileceğini belirten ilke."},"options":{"A":"Kusur ilkesi","B":"Kanunilik ilkesi","C":"Masumiyet karinesi","D":"Cezaların şahsiliği ilkesi","E":"Hakkaniyet ilkesi"},"correct_option":"B","explanations":{"A":"Yanlış. Kusur ilkesi kişinin eylemi bilerek veya özen yükümlülüğüne aykırı olarak gerçekleştirmesi durumunda cezalandırılabileceğini ifade eder.","B":"Doğru. Kanunsuz suç ve ceza olmaz kuralı olarak da bilinen kanunilik ilkesi, suç ve cezaların ancak yasama organınca kanunla konulmasını şart koşar.","C":"Yanlış. Masumiyet karinesi kesin bir mahkûmiyet kararı tesis edilene dek kişinin suçsuz sayılmasını öngörür.","D":"Yanlış. Cezaların şahsiliği ilkesi faillerin yalnızca kendi eylemlerinden sorumlu tutulabileceğini açıklar.","E":"Yanlış. Hakkaniyet ilkesi somut olayın adaletli çözümüne yönelik genel bir ilke olup ceza koyma yetkisiyle doğrudan ilgili değildir."},"overall_explanation":"Kanunsuz suç ve ceza olmaz ilkesi uyarınca, hangi davranışların suç sayılacağı ve bunlara hangi yaptırımların uygulanacağı yürütme veya yargı tarafından değil, doğrudan kanun koyucu tarafından belirlenir."},{"id":"W4_Q5","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Aşağıdakilerden hangisi Türk Medeni Kanunu bünyesinde yer alan temel kitaplardan biri değildir?","tooltips":{"Türk Medeni Kanunu":"Kişilerin hak ehliyetini, aile bağlarını, mülkiyet ilişkilerini ve miras intikallerini düzenleyen 4721 sayılı temel kanun."},"options":{"A":"Kişiler Hukuku","B":"Aile Hukuku","C":"Eşya Hukuku","D":"Miras Hukuku","E":"İcra Hukuku"},"correct_option":"E","explanations":{"A":"Yanlış. Kişiler Hukuku Medeni Kanunun birinci kitabıdır.","B":"Yanlış. Aile Hukuku Medeni Kanunun ikinci kitabıdır.","C":"Yanlış. Eşya Hukuku Medeni Kanunun dördüncü kitabıdır.","D":"Yanlış. Miras Hukuku Medeni Kanunun üçüncü kitabıdır.","E":"Doğru. İcra Hukuku Medeni Kanunun bir parçası olmayıp cebri icra faaliyetini düzenleyen bağımsız ve karma nitelikli bir usul dalıdır."},"overall_explanation":"4721 sayılı Türk Medeni Kanunu sistematiği dört ana kitaptan oluşur: Kişiler Hukuku, Aile Hukuku, Miras Hukuku ve Eşya Hukuku. İcra hukuku ise 2004 sayılı İcra ve İflas Kanunu ile tanzim edilen karma bir alandır."},{"id":"W4_Q6","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Bir kimsenin komşusunun manzarasını kapatmak ve yalnızca ona zarar vermek amacıyla kendi arsa sınırına yüksek bir duvar inşa etmesi durumunun hukuki niteliği aşağıdakilerden hangisinde doğru açıklanmıştır?","tooltips":{"hakkın kötüye kullanılması":"Bir hakkın dürüstlük kurallarına açıkça aykırı ve başkasına zarar verme amacıyla kullanılması durumu."},"options":{"A":"Kamu düzenini bozduğu gerekçesiyle hürriyeti bağlayıcı ceza gerektiren bir suç oluşturur","B":"Medeni hukuk bakımından hukuka aykırılık oluşturur ancak ceza hukuku anlamında suç teşkil etmez","C":"Mülkiyet hakkı mutlak olduğundan hukuk düzenince tamamen korunan hukuka uygun bir eylemdir","D":"İdari yargının görev alanına giren ve idari para cezası yaptırımına bağlanan bir idari suçtur","E":"Uluslararası kamu hukuku normlarının doğrudan ihlali sonucunu doğurur"},"correct_option":"B","explanations":{"A":"Yanlış. Eylem komşuluk hukukuna ve dürüstlük kuralına aykırı olsa da ceza kanunlarında suç olarak tanımlanmamıştır.","B":"Doğru. Arsa sınırına salt zarar amacıyla duvar örmek hakkın kötüye kullanılması yasağını çiğneyerek hukuka aykırılık oluşturur; ancak bu eylem bir suç değildir ve medeni hukuk yaptırımlarına tabidir.","C":"Yanlış. Mülkiyet hakkı sınırsız değildir; TMK m. 2 uyarınca hakkın açıkça kötüye kullanılmasını hukuk düzeni korumaz.","D":"Yanlış. Özel mülk sahipleri arasındaki bu uyuşmazlık idare hukukunun veya idari para cezalarının konusu değildir.","E":"Yanlış. Komşuluk ilişkisinden doğan yerel bir özel hukuk uyuşmazlığının uluslararası kamu hukuku ile ilgisi yoktur."},"overall_explanation":"Dürüstlük kuralına aykırı ve salt zarar verme saikli eylemler özel hukukta hakkın kötüye kullanılması sebebiyle hukuka aykırılık oluşturur; fakat ceza kanunlarında tanımlanmadıkça suç oluşturmaz."},{"id":"W4_Q7","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Ceza yargılamasında hakkında yürütülen yargılama sonucunda verilen mahkûmiyet hükmü kesinleşen kişi hangi sıfatı alır?","tooltips":{"hükümlü":"Hakkında mahkemece verilen mahkûmiyet kararı kanun yollarından geçerek veya sürelerin dolmasıyla kesinleşmiş kişi.","mahkûmiyet":"Yargılama sonunda failin suçu işlediğinin sabit görülmesiyle ceza veya güvenlik tedbirine hükmedilmesi."},"options":{"A":"Müşteki","B":"Şüpheli","C":"Sanık","D":"Hükümlü","E":"Müdahil"},"correct_option":"D","explanations":{"A":"Yanlış. Müşteki suçtan zarar gören veya şikâyette bulunan kişiyi ifade eder.","B":"Yanlış. Şüpheli, soruşturma evresindeki isnat altındaki kişidir.","C":"Yanlış. Sanık, kovuşturma evresinde duruşması devam eden kişidir.","D":"Doğru. Hakkındaki mahkûmiyet kararı kesinleşen kişi artık ceza infaz hukuku bağlamında hükümlü sıfatını taşır.","E":"Yanlış. Müdahil, kamu davasına katılan suçtan zarar görmüş üçüncü kişileri ifade eder."},"overall_explanation":"Kişi soruşturma evresinde şüpheli, kovuşturma evresinde sanık, hakkındaki mahkûmiyet hükmünün kesinleşmesinden sonra ise hükümlü sıfatını kazanır."},{"id":"W4_Q8","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"İçerisinde yabancılık unsuru barındıran özel hukuk uyuşmazlıklarında uygulanacak yetkili hukuku belirleyen bağlama kurallarını içeren hukuk dalı aşağıdakilerden hangisidir?","tooltips":{"yabancılık unsuru":"Bir hukuki ilişkide tarafların vatandaşlığı, yerleşim yeri veya işlem konusunun yabancı bir ülkeyle bağlantılı olması hali.","bağlama kuralları":"Yabancılık unsuru taşıyan hukuki uyuşmazlıklarda hangi devlet hukukunun uygulanacağını gösteren kanunlar ihtilafı normları."},"options":{"A":"Milletlerarası Özel Hukuk","B":"Uluslararası Kamu Hukuku","C":"Medenî Usul Hukuku","D":"İdare Hukuku","E":"Ticaret Hukuku"},"correct_option":"A","explanations":{"A":"Doğru. Milletlerarası Özel Hukuk, yabancılık unsuru içeren özel hukuk ilişkilerinde yetkili hukuku tespit eden bağlama kurallarını ve yabancı mahkeme kararlarının tanınmasını düzenler.","B":"Yanlış. Uluslararası Kamu Hukuku egemen devletler ve uluslararası örgütler arasındaki ilişkileri inceler.","C":"Yanlış. Medenî Usul Hukuku Türk mahkemelerindeki dava açma, ispat ve hüküm süreçlerini düzenleyen şeklî hukuktur.","D":"Yanlış. İdare Hukuku devlet idaresinin kamu gücü işlemlerini düzenler.","E":"Yanlış. Ticaret Hukuku tacirlerin ve ticari işletmelerin faaliyetlerini düzenleyen maddi özel hukuk dalıdır."},"overall_explanation":"Milletlerarası Özel Hukuk, yabancılık unsuru taşıyan uyuşmazlıklarda uyuşmazlığın esasına doğrudan girmek yerine hangi devletin hukukunun uygulanacağını tespit eden bağlama kuralları üretir."},{"id":"W4_Q9","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"İşçi ile işveren arasındaki iş sözleşmesine, zayıf tarafı korumak amacıyla devletin asgari ücret veya iş güvencesi gibi emredici kurallarla müdahale etmesi İş Hukukuna hangi niteliği kazandırır?","tooltips":{"iş güvencesi":"İşverenin iş sözleşmesini keyfî olarak feshetmesini engelleyen ve geçerli sebebe bağlayan koruyucu yasal düzenleme."},"options":{"A":"Saf kamu hukuku niteliği","B":"Klasik özel hukuk niteliği","C":"Milletlerarası hukuk niteliği","D":"Mali hukuk niteliği","E":"Karma hukuk niteliği"},"correct_option":"E","explanations":{"A":"Yanlış. İş ilişkisi tarafların iradesiyle sözleşme zemininde kurulduğu için saf kamu hukuku olarak nitelendirilemez.","B":"Yanlış. Devlet emredici normlarla sözleşme özgürlüğünü sınırlandırdığı için saf özel hukuk karakterini aşar.","C":"Yanlış. Yabancılık unsuru taşımayan yerel iş ilişkileri milletlerarası hukukun kapsamına girmez.","D":"Yanlış. Mali hukuk devletin vergi ve bütçe gelir-giderlerini tanzim eder.","E":"Doğru. Özel hukuk sözleşmesi ile başlayıp zayıf olan işçiyi korumak üzere kamusal müdahalelere tabi kılınan disiplinler karma hukuk dalı olarak kabul edilir."},"overall_explanation":"İş Hukuku, temeli özel hukuka dayanan sözleşme ilişkisine devletin kamusal menfaat ve işçiyi koruma saikiyle emredici şekilde müdahale etmesi sebebiyle karma hukuk dalı olarak sınıflandırılır."},{"id":"W4_Q10","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Yargılama makamları huzurunda kesin bir mahkûmiyet kararı tesis edilinceye kadar suç isnadı altındaki her bireyin suçsuz sayılmasını güvence altına alan evrensel ilke aşağıdakilerden hangisidir?","tooltips":{"masumiyet karinesi":"Hakkında kesinleşmiş mahkeme hükmü bulunmayan bir kimsenin suçlu muamelesi görmesini engelleyen temel anayasal ilke."},"options":{"A":"Kanunilik ilkesi","B":"Kusur ilkesi","C":"Masumiyet karinesi","D":"Cezaların şahsiliği ilkesi","E":"Kanunu bilmeme mazeret sayılmaz kuralı"},"correct_option":"C","explanations":{"A":"Yanlış. Kanunilik ilkesi suç ve cezaların mutlaka yazılı kanunla ihdas edilmesini şart koşar.","B":"Yanlış. Kusur ilkesi faile ceza verilebilmesi için kınanabilir bir kast veya taksirinin aranmasıdır.","C":"Doğru. Masumiyet karinesi gereğince mahkeme hükmü kesinleşinceye kadar hiç kimse suçlu kabul edilemez.","D":"Yanlış. Cezaların şahsiliği ilkesi cezanın sadece fiili işleyene uygulanabileceğini ve başkasına sirayet etmeyeceğini anlatır.","E":"Yanlış. Kanunu bilmeme mazeret sayılmaz kuralı bireylerin kanunu bilmediği iddiasıyla cezadan kurtulamayacağını ifade eder."},"overall_explanation":"Masumiyet karinesi, adil yargılanma hakkının temel bir unsuru olup nihai ve kesin bir mahkûmiyet kararı çıkana kadar bireyin lekelenmeme ve suçsuz sayılma hakkını korur."},{"id":"W4_Q11","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Maddî hukukun kişilere tanıdığı hakların ihlali durumunda bu uyuşmazlıkların mahkemeler huzurunda çözümlenme usulünü, dilekçelerin sunulmasını, ispat faaliyetini ve yargılama adımlarını düzenleyen hukuk dalı aşağıdakilerden hangisidir?","tooltips":{"maddî hukuk":"Hakların özünü, doğumunu, sınırlarını ve süjelerini düzenleyen hukuk kurallarının tamamı.","usul hukuku":"Hakların yargı organları önünde talep edilme ve uyuşmazlığın çözülme yöntemlerini düzenleyen şeklî kurallar bütünü."},"options":{"A":"Medenî Usul Hukuku","B":"Ticaret Hukuku","C":"Ceza Hukuku","D":"Borçlar Hukuku","E":"Miras Hukuku"},"correct_option":"A","explanations":{"A":"Doğru. Medenî Usul Hukuku Hukuk Muhakemeleri Kanununa dayanan ve özel hukuk uyuşmazlıklarının mahkemede nasıl görüleceğini düzenleyen şeklî hukuk dalıdır.","B":"Yanlış. Ticaret Hukuku tacirleri ve şirketleri düzenleyen bir maddi hukuk disiplinidir.","C":"Yanlış. Ceza Hukuku suçları ve cezaları düzenleyen kamu hukuku dalıdır.","D":"Yanlış. Borçlar Hukuku alacak ve borç ilişkilerinin doğumunu düzenleyen maddi hukuk dalıdır.","E":"Yanlış. Miras Hukuku ölen kişinin terekesinin intikalini düzenleyen maddi özel hukuk dalıdır."},"overall_explanation":"Medenî Usul Hukuku hakkın özünü tespit eden maddi hukuk kurallarından farklı olarak davanın açılması, yürütülmesi, delillerin sunulması ve hükmün kurulması gibi şeklî yargılama aşamalarını tanzim eder."},{"id":"W4_Q12","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Devletin kamu harcamalarını finanse etmek için ihtiyaç duyduğu gelirlerin toplanması, vergilerin tarh, tebliğ, tahakkuk ve tahsil süreçlerini düzenleyen kamu hukuku dalı aşağıdakilerden hangisidir?","tooltips":{"tarh":"Vergi alacağının kanunlarında gösterilen matrah ve nispetler üzerinden vergi dairesi tarafından hesaplanması işlemi.","tahakkuk":"Tarh ve tebliğ edilen verginin ödenebilir aşamaya gelmesi hali."},"options":{"A":"Ticaret Hukuku","B":"Borçlar Hukuku","C":"Medenî Usul Hukuku","D":"İş Hukuku","E":"Mâlî Hukuk ve Vergi Hukuku"},"correct_option":"E","explanations":{"A":"Yanlış. Ticaret Hukuku özel hukuka ait olup tacir ve şirket ilişkilerini düzenler.","B":"Yanlış. Borçlar Hukuku eşit taraflar arasındaki sözleşme ve tazminat borçlarını ele alır.","C":"Yanlış. Medenî Usul Hukuku yargılama usullerini konu alan karma bir disiplindir.","D":"Yanlış. İş Hukuku işçi ve işveren arasındaki çalışma şartlarını tanzim eder.","E":"Doğru. Kamu gelirlerinin ve vergilerin tarhından tahsiline kadar kamusal bütçe faaliyetlerini Mâlî Hukuk ve Vergi Hukuku düzenler."},"overall_explanation":"Kamu gücüne dayanılarak toplanan vergi, harç ve resimlerin tahsil ve harcama süreçleri kamu hukuku ana dalı altındaki Mâlî Hukuk ve Vergi Hukukunun konusunu teşkil eder."},{"id":"W4_Q13","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Araç kullanırken cep telefonuyla konuşması nedeniyle trafik cezası kesilen bir sürücünün, bu eylemin yasak olduğunu bilmediğini beyan ederek cezadan kurtulmaya çalışması aşağıdaki temel ceza hukuku ilkelerinden hangisi karşısında geçersiz kalır?","tooltips":{"karine":"Bilinen bir olgudan bilinmeyen bir hukuki sonucun çıkarılması ve aksinin iddia edilememesi durumu."},"options":{"A":"Masumiyet karinesi","B":"Kanunu bilmemek mazeret sayılmaz kuralı","C":"Cezaların şahsiliği ilkesi","D":"Kusur yeteneği ilkesi","E":"İdarenin kanuniliği ilkesi"},"correct_option":"B","explanations":{"A":"Yanlış. Masumiyet karinesi suçluluğu kanıtlanana kadar kişinin masum sayılmasını ifade eder.","B":"Doğru. Kanunu bilmemek mazeret sayılmaz kuralı uyarınca usulüne göre yürürlüğe konulmuş kanunların herkesçe bilindiği varsayılır ve bilgisizlik hukuki sorumluluğu ortadan kaldırmaz.","C":"Yanlış. Cezaların şahsiliği cezanın yalnızca suçu işleyen faile verilmesini ifade eder.","D":"Yanlış. Kusur yeteneği kişinin hareketinin bilincinde olup iradesini yönlendirebilme ehliyetidir.","E":"Yanlış. İdarenin kanuniliği idari işlemlerin kanuna dayanması zorunluluğudur."},"overall_explanation":"Yürürlükteki hukuk düzeninde kanunların bilindiği hukuki bir karine olarak kabul edilir ve kuralı bilmediğini iddia etmek ceza sorumluluğundan kurtulma gerekçesi yapılamaz."},{"id":"W4_Q14","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Mahkeme tarafından verilen bir para alacağına ilişkin ilamın borçlu tarafından rızaen yerine getirilmemesi durumunda, devlet gücü marifetiyle borçlunun malvarlığına el konularak alacaklının tatmin edilmesini sağlayan hukuk dalı aşağıdakilerden hangisidir?","tooltips":{"cebri icra":"Mahkeme kararlarının veya yasal alacakların borçlunun rızasına bırakılmaksızın devlet gücüyle zorla yerine getirilmesi."},"options":{"A":"Medeni Hukuk","B":"Anayasa Hukuku","C":"İcra ve İflas Hukuku","D":"Milletlerarası Özel Hukuk","E":"Uluslararası Kamu Hukuku"},"correct_option":"C","explanations":{"A":"Yanlış. Medeni Hukuk maddi hakları belirler; cebren yerine getirme usulünü tanzim etmez.","B":"Yanlış. Anayasa Hukuku devletin temel organlarını ve bireysel özgürlükleri düzenler.","C":"Doğru. Borcun ifa edilmemesi halinde alacağın devletin cebri icra tekeli ve haciz yoluyla tahsilini İcra ve İflas Hukuku sağlar.","D":"Yanlış. Milletlerarası Özel Hukuk yabancılık unsurlu davalarda yetkili hukuku belirler.","E":"Yanlış. Uluslararası Kamu Hukuku devletler arasındaki siyasi ve kamusal ilişkileri inceler."},"overall_explanation":"Borçlunun rızaen ödemediği alacakların kamu gücü ve haciz yoluyla tahsil edilmesi, devletin cebri icra tekelini düzenleyen İcra ve İflas Hukukunun konusudur."},{"id":"W4_Q15","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Failin gerçekleştirdiği haksız eylem nedeniyle kınanabilmesi ve hakkında ceza verilebilmesi için isnat yeteneği zemininde kasti veya taksirli bir iradesinin aranmasını zorunlu kılan ilke aşağıdakilerden hangisidir?","tooltips":{"kast":"Suçun kanuni tanımındaki unsurların bilerek ve istenerek gerçekleştirilmesi hali.","taksir":"Dikkat ve özen yükümlülüğüne aykırılık dolayısıyla bir neticenin öngörülemeyerek veya istenmeyerek gerçekleştirilmesi."},"options":{"A":"Kanunilik ilkesi","B":"Masumiyet karinesi","C":"Eşitlik ilkesi","D":"Kusur ilkesi","E":"Aleniyet ilkesi"},"correct_option":"D","explanations":{"A":"Yanlış. Kanunilik ilkesi suç ve cezaların yasayla düzenlenmesini öngörür.","B":"Yanlış. Masumiyet karinesi kesin hükme kadar bireyin masum sayılmasıdır.","C":"Yanlış. Eşitlik ilkesi kanun önünde herkesin aynı muameleye tabi tutulmasıdır.","D":"Doğru. Kusur ilkesi gereğince bireye ceza sorumluluğu yüklenebilmesi için isnat yeteneği bulunmalı ve eylem kast veya taksirle işlenmiş olmalıdır.","E":"Yanlış. Aleniyet ilkesi duruşmaların topluma açık olarak yürütülmesini ifade eder."},"overall_explanation":"Ceza sorumluluğu kusursuz ceza olmaz esasına dayanır; failin eyleminden sorumlu tutulması isnat yeteneğine ve iradi kusuruna (kast veya taksir) bağlıdır."},{"id":"W4_Q16","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Aşağıdakilerden hangisi Ticaret Hukukunun doğrudan bünyesinde yer alan alt çalışma alanlarından biri değildir?","tooltips":{"kıymetli evrak":"İçerdiği hak senetten ayrı ileri sürülemeyen çek, bono ve poliçe gibi ticari senetler."},"options":{"A":"Kıymetli Evrak Hukuku","B":"Deniz Ticareti Hukuku","C":"Şirketler Hukuku","D":"Sigorta Hukuku","E":"Ceza Muhakemesi Hukuku"},"correct_option":"E","explanations":{"A":"Yanlış. Kıymetli Evrak Hukuku Ticaret Kanununda düzenlenen bir alt daldır.","B":"Yanlış. Deniz Ticareti Hukuku Ticaret Hukukunun temel kısımlarından biridir.","C":"Yanlış. Şirketler Hukuku Ticaret Hukukunun önemli bir alt disiplinidir.","D":"Yanlış. Sigorta Hukuku Türk Ticaret Kanununda düzenlenen özel sigortacılık alanıdır.","E":"Doğru. Ceza Muhakemesi Hukuku suç yargılamasını tanzim eden bir kamu hukuku usul dalıdır; ticaret hukukuyla doğrudan ilgisi yoktur."},"overall_explanation":"Ticaret Hukuku; ticari işletme, ticaret şirketleri, kıymetli evrak, taşıma, deniz ticareti ve özel sigorta alt dallarından oluşur; ceza usulü bu alana dahil değildir."},{"id":"W4_Q17","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Ceza yargılamasında suç şüphesinin yetkili mercilerce öğrenilmesinden başlayarak iddianamenin mahkemece kabulüne kadar devam eden evre aşağıdakilerden hangisidir?","tooltips":{"soruşturma":"Suç şüphesinin öğrenilmesinden iddianamenin kabulüne kadar savcılık ve kolluk makamlarınca yürütülen ilk yargılama evresi."},"options":{"A":"Soruşturma evresi","B":"Kovuşturma evresi","C":"İnfaz evresi","D":"İstinaf incelemesi","E":"Temyiz incelemesi"},"correct_option":"A","explanations":{"A":"Doğru. Suç şüphesinin öğrenilmesiyle başlayıp iddianamenin kabulüyle sona eren adli süreç soruşturma evresidir.","B":"Yanlış. Kovuşturma evresi iddianamenin kabulünden sonra mahkeme huzurunda başlayan süreçtir.","C":"Yanlış. İnfaz evresi kesinleşen mahkûmiyet kararının yerine getirilmesi aşamasıdır.","D":"Yanlış. İstinaf incelemesi ilk derece mahkemesi kararlarına karşı başvurulan bir kanun yoludur.","E":"Yanlış. Temyiz incelemesi Yargıtay tarafından yapılan hukuki denetim aşamasıdır."},"overall_explanation":"Ceza muhakemesi süreci suç şüphesinin öğrenilmesiyle soruşturma olarak başlar ve iddianamenin mahkemece kabulü ile kovuşturma evresine geçer."},{"id":"W4_Q18","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Egemen devletlerin ve uluslararası örgütlerin birbirleriyle kurdukları ilişkileri, sınır protokollerini ve uluslararası antlaşmaları düzenleyen kamu hukuku dalı aşağıdakilerden hangisidir?","tooltips":{"uluslararası antlaşma":"Uluslararası hukuk kişileri arasında yazılı olarak yapılan ve bağlayıcı hak ve borçlar doğuran hukuki işlem."},"options":{"A":"Milletlerarası Özel Hukuk","B":"Medeni Usul Hukuku","C":"Uluslararası Kamu Hukuku","D":"İdare Hukuku","E":"Anayasa Hukuku"},"correct_option":"C","explanations":{"A":"Yanlış. Milletlerarası Özel Hukuk bireyler arasındaki yabancılık unsurlu özel ilişkileri tanzim eder.","B":"Yanlış. Medeni Usul Hukuku özel hukuk mahkemelerindeki yargılama kurallarını kapsar.","C":"Doğru. Egemen devletler ve uluslararası örgütler arasındaki kamusal ilişkileri Uluslararası Kamu Hukuku düzenler.","D":"Yanlış. İdare Hukuku devletin kendi iç kamu hizmetlerini ve idari teşkilatını ele alır.","E":"Yanlış. Anayasa Hukuku bir devletin temel teşkilatını ve vatandaşların anayasal haklarını inceler."},"overall_explanation":"Uluslararası Kamu Hukuku, egemen süjelerin kendi aralarındaki antlaşma ve diplomatik ilişkilerini düzenleyen kamu hukuku disiplinidir."},{"id":"W4_Q19","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Taraflar arasında sözleşmelerden, haksız fiillerden veya sebepsiz zenginleşmeden doğan alacak ve borç ilişkilerini inceleyen temel özel hukuk disiplini aşağıdakilerden hangisidir?","tooltips":{"haksız fiil":"Kusurlu ve hukuka aykırı bir fiille başkasına zarar verilmesi durumu.","sebepsiz zenginleşme":"Haklı bir sebep olmaksızın bir kimsenin malvarlığının başkası aleyhine çoğalması."},"options":{"A":"İcra ve İflas Hukuku","B":"Ceza Hukuku","C":"İdare Hukuku","D":"Borçlar Hukuku","E":"Mali Hukuk"},"correct_option":"D","explanations":{"A":"Yanlış. İcra ve İflas Hukuku alacağın tahsiline yönelik zorlayıcı usul kurallarını içerir.","B":"Yanlış. Ceza Hukuku suç oluşturan fiilleri ve kamu yaptırımlarını inceler.","C":"Yanlış. İdare Hukuku kamu kurumlarının işleyişini tanzim eder.","D":"Doğru. Borçlar Hukuku sözleşme, haksız fiil ve sebepsiz zenginleşmeden doğan borç ilişkilerini düzenleyen özel hukuk dalıdır.","E":"Yanlış. Mali Hukuk kamu gelir ve giderlerini ele alan kamu hukuku dalıdır."},"overall_explanation":"Borçlar Hukuku, eşit taraflar arasındaki borç ilişkilerinin doğumunu, ifasını ve sona ermesini düzenleyen temel özel hukuk dalıdır."},{"id":"W4_Q20","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Suç işleyen failin yerine ailesinin veya yakın akrabalarının cezalandırılmasını yasaklayan ve her bireyin yalnızca kendi eyleminden mesul olacağını öngören ilke aşağıdakilerden hangisidir?","tooltips":{"cezaların şahsiliği":"Ceza yaptırımının yalnızca suçu bizzat işleyen fail hakkında uygulanabileceğini belirten anayasal ilke."},"options":{"A":"Kanunilik ilkesi","B":"Cezaların şahsiliği ilkesi","C":"Masumiyet karinesi","D":"Kusursuz sorumluluk ilkesi","E":"Aleniyet ilkesi"},"correct_option":"B","explanations":{"A":"Yanlış. Kanunilik ilkesi suç ve cezaların kanunla yazılı olarak konulmasını zorunlu kılar.","B":"Doğru. Cezaların şahsiliği ilkesi uyarınca hiç kimse başkasının işlediği suç sebebiyle cezalandırılamaz.","C":"Yanlış. Masumiyet karinesi suçsuzluk varsayımını ifade eder.","D":"Yanlış. Kusursuz sorumluluk ceza hukukunda reddedilen, bazı özel hukuk hallerinde görülen bir sorumluluk tipidir.","E":"Yanlış. Aleniyet ilkesi yargılamanın kamuya açık yapılmasını gerektirir."},"overall_explanation":"Cezaların şahsiliği ilkesi toplu cezalandırmayı yasaklar ve ceza sorumluluğunu yalnızca suçu bizzat işleyen kişiyle sınırlar."},{"id":"W4_Q21","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"I. Eşya Hukuku\\nII. İdare Hukuku\\nIII. Milletlerarası Özel Hukuk\\n\\nYukarıda verilen hukuk dallarından hangileri özel hukuk ana başlığı altında yer alır?","tooltips":{"özel hukuk":"Eşit haklara sahip kişilerin kendi aralarında kurdukları irade serbestisine dayalı ilişkileri düzenleyen hukuk alanı."},"options":{"A":"I ve III","B":"Yalnız II","C":"I ve II","D":"II ve III","E":"Yalnız I"},"correct_option":"A","explanations":{"A":"Doğru. Eşya Hukuku (Medeni Hukukun alt dalı olarak) ve Milletlerarası Özel Hukuk özel hukuk alanına aittir; İdare Hukuku ise kamu hukukudur.","B":"Yanlış. İdare Hukuku kamu hukuku dalıdır.","C":"Yanlış. İdare Hukuku özel hukukta yer almaz.","D":"Yanlış. İdare Hukuku kamu hukuku dalıdır.","E":"Yanlış. Yalnızca Eşya Hukuku değil, Milletlerarası Özel Hukuk da özel hukuk kapsamındadır."},"overall_explanation":"Eşya Hukuku Medeni Hukukun ayrılmaz bir parçası olarak, Milletlerarası Özel Hukuk ise yabancılık unsurlu özel ilişkileri tanzim etmesi bakımından özel hukuk sınıfına girer."},{"id":"W4_Q22","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Hakkın özünü, kimlerin hak sahibi veya borçlu olduğunu ve alacağın doğum şartlarını belirleyen hukuk kuralları ile bu hakların mahkemede talep edilme usulünü gösteren kurallar arasındaki ayrım aşağıdakilerden hangisidir?","tooltips":{"şeklî hukuk":"Uyuşmazlıkların yargı organlarında dava açılması, yürütülmesi ve ispatı gibi yargısal usulleri tanzim eden hukuk kuralları."},"options":{"A":"İç hukuk ile dış hukuk ayrımı","B":"Maddi hukuk ile usul hukuku ayrımı","C":"Kamu hukuku ile karma hukuk ayrımı","D":"Pozitif hukuk ile tabii hukuk ayrımı","E":"Yazılı hukuk ile yazısız hukuk ayrımı"},"correct_option":"B","explanations":{"A":"Yanlış. İç hukuk ve dış hukuk devletin egemenlik sınırları ile uluslararası alan arasındaki ayrımdır.","B":"Doğru. Hakkın özünü ve şartlarını belirleyen kurallar maddi hukuk, uyuşmazlığın mahkemede nasıl talep edileceğini gösteren kurallar ise usul hukukudur.","C":"Yanlış. Kamu hukuku ve karma hukuk devlet otoritesinin niteliğine göre yapılan dal tasnifidir.","D":"Yanlış. Pozitif ve tabii hukuk yürürlükte olan ile olması gereken adalet ideali arasındaki ayrımdır.","E":"Yanlış. Yazılı ve yazısız hukuk kaynağın mevzuatta yer alış biçimine ilişkindir."},"overall_explanation":"Maddi hukuk hakkın içeriğini ve şartlarını tanzim ederken; usul hukuku bu hakkın dava edilmesi, ispatı ve yargılanma biçimini belirler."},{"id":"W4_Q23","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Devletin temel yapısını, yasama, yürütme ve yargı organlarının görev ve yetkilerini, organlar arasındaki dengeyi ve bireylerin temel hak ve özgürlüklerini en üst norm düzeyinde tanzim eden kamu hukuku disiplini aşağıdakilerden hangisidir?","tooltips":{"anayasa":"Devletin temel teşkilat yapısını ve bireylerin temel haklarını düzenleyen normlar hiyerarşisinin en üstündeki temel kanun."},"options":{"A":"İdare Hukuku","B":"Ceza Hukuku","C":"Anayasa Hukuku","D":"Medeni Usul Hukuku","E":"Mali Hukuk"},"correct_option":"C","explanations":{"A":"Yanlış. İdare Hukuku kamu kurumlarının yürütme fonksiyonu içindeki gündelik işleyişini ele alır.","B":"Yanlış. Ceza Hukuku suç ve yaptırımları inceler.","C":"Doğru. Devlet organlarının işleyişini ve vatandaşların anayasal haklarını düzenleyen en üst kamu hukuku dalı Anayasa Hukukudur.","D":"Yanlış. Medeni Usul Hukuku mahkemelerdeki yargılama usulünü düzenleyen şeklî daldır.","E":"Yanlış. Mali Hukuk kamu gelir ve giderlerini inceler."},"overall_explanation":"Anayasa Hukuku, normlar hiyerarşisinin zirvesinde yer alarak devletin temel organlarını ve bireylerin kamusal temel haklarını düzenleyen ana kamu hukuku dalıdır."},{"id":"W4_Q24","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Ceza yargılamasında toplanan delillerin mahkeme huzurunda tartışılması, kamuya açık duruşmaların yürütülmesi ve nihai hükmün verilmesine kadar devam eden aşama aşağıdakilerden hangisidir?","tooltips":{"kovuşturma":"İddianamenin mahkemece kabul edilmesiyle başlayıp hükmün kesinleşmesine kadar süren mahkeme aşaması."},"options":{"A":"Soruşturma evresi","B":"Hazırlık tahkikatı","C":"İnfaz evresi","D":"Kovuşturma evresi","E":"Gözaltı evresi"},"correct_option":"D","explanations":{"A":"Yanlış. Soruşturma evresi mahkeme aşamasından önce savcılık tarafından delillerin toplandığı ilk dönemdir.","B":"Yanlış. Hazırlık tahkikatı eski mevzuatta soruşturma evresine verilen isimdir.","C":"Yanlış. İnfaz evresi kesin hükmün cezaevinde yerine getirilmesi sürecidir.","D":"Doğru. İddianamenin kabulüyle başlayıp hükmün kesinleşmesine kadar süren mahkeme ve duruşma aşaması kovuşturma evresidir.","E":"Yanlış. Gözaltı soruşturma evresinde uygulanan geçici bir koruma tedbiridir."},"overall_explanation":"Duruşmaların yapıldığı, delillerin değerlendirildiği ve mahkemece kararın oluşturulduğu yargılama safhası kovuşturma evresidir."},{"id":"W4_Q25","domain_id":4,"domain_name":"Hafta 4: Kamu Hukuku ve Özel Hukuk Dalları","question":"Aşağıdaki eşleştirmelerden hangisi hukuk dalı ile ait olduğu ana kategori bakımından yanlıştır?","tooltips":{"karma hukuk":"Özel hukuk ilişkilerine kamu gücünün ve emredici kuralların yoğun olarak karıştığı hukuk dallarını kapsayan grup."},"options":{"A":"Anayasa Hukuku - Kamu Hukuku","B":"Ticaret Hukuku - Özel Hukuk","C":"İş Hukuku - Karma Hukuk","D":"Borçlar Hukuku - Özel Hukuk","E":"İdare Hukuku - Özel Hukuk"},"correct_option":"E","explanations":{"A":"Yanlış (Eşleştirme doğrudur). Anayasa Hukuku bir kamu hukuku disiplinidir.","B":"Yanlış (Eşleştirme doğrudur). Ticaret Hukuku irade özerkliğine dayalı bir özel hukuk dalıdır.","C":"Yanlış (Eşleştirme doğrudur). İş Hukuku kamu müdahalesi içeren bir karma hukuk dalıdır.","D":"Yanlış (Eşleştirme doğrudur). Borçlar Hukuku eşit süjeleri düzenleyen özel hukuk dalıdır.","E":"Doğru (Eşleştirme hatalıdır). İdare Hukuku kamu gücü ve üstünlüğü ilkelerine dayandığı için özel hukuk değil, kamu hukuku dalıdır."},"overall_explanation":"İdare Hukuku, devletin kamu gücü kullanarak kamu hizmetlerini yürütmesini ve bireyler üzerindeki üstün iradesini tanzim ettiği için kamu hukuku kategorisinde yer alır."}]'))},71836,a=>{a.v(JSON.parse('[{"id":"W5_Q1","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Kökeni Roma Hukukuna dayanan ve kamu hukuku ile özel hukuk ayrımını temel alan hukuk sistemi aşağıdakilerden hangisidir?","tooltips":{"kamu hukuku":"Devletin egemenlik yetkisini kullanarak taraf olduğu ve kamu yararını gözeten hukuk kurallarının bütünüdür.","özel hukuk":"Eşit haklara sahip kişilerin kendi aralarındaki hukuki ilişkileri düzenleyen kuralların bütünüdür."},"options":{"A":"İslam Hukuku","B":"Sosyalist Hukuk","C":"Kara Avrupası Hukuk Sistemi","D":"Anglo-Amerikan Hukuk Sistemi","E":"Geleneksel Hukuk Sistemi"},"correct_option":"C","explanations":{"A":"Yanlış. İslam hukuku Roma hukukuna değil, ilahi vahiy ve sünnet temeline dayanır.","B":"Yanlış. Sosyalist hukuk Marksist-Leninist ideolojiye dayanır ve klasik özel hukuk ayrımını reddeder.","C":"Doğru. Kara Avrupası hukuk sistemi Roma geleneğine dayanır ve kamu-özel hukuk ikili ayrımını temel omurga kabul eder.","D":"Yanlış. Anglo-Amerikan hukuk sistemi İngiliz örf-âdet ve yargıç kararlarına dayanır, bu ayrımı benimsemez.","E":"Yanlış. Geleneksel hukuk sistemleri Roma hukuku kodifikasyonuna dayanan modern bir tasnif oluşturmaz."},"overall_explanation":"Kara Avrupası hukuk sistemi, köklerini Roma Hukukundan alır ve en belirgin ayırt edici özelliği kamu hukuku ile özel hukuk arasındaki ikili ayrımdır."},{"id":"W5_Q2","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Anglo-Amerikan hukuk sisteminde alt mahkemelerin benzer olaylarda üst mahkemelerce verilmiş önceki kararlara bağlı kalmasını zorunlu kılan ilke aşağıdakilerden hangisidir?","tooltips":{"emsal karar":"Daha önce aynı veya benzer hukuki konuda üst mahkemelerce verilmiş ve yol gösterici nitelikteki yargı kararıdır."},"options":{"A":"Stare decisis","B":"Corpus iuris civilis","C":"Opinio juris","D":"Inter partes","E":"Lex superior"},"correct_option":"A","explanations":{"A":"Doğru. Stare decisis ilkesi, yargıcın üst mahkemelerce verilmiş emsal kararlarla bağlı olduğunu ifade eden temel Common Law doktrinidir.","B":"Yanlış. Corpus iuris civilis, Doğu Roma İmparatoru Justinianus tarafından hazırlatılan Roma hukuku derlemesidir.","C":"Yanlış. Opinio juris, örf ve âdet kuralına uyulmasının hukuken zorunlu olduğuna dair genel toplumsal inançtır.","D":"Yanlış. Inter partes, tesis edilen bir hükmün yalnızca davanın tarafları arasında bağlayıcı olması demektir.","E":"Yanlış. Lex superior, üst normun alt normdan önce uygulanması ve ona üstün gelmesi ilkesidir."},"overall_explanation":"Common Law sisteminin omurgasını oluşturan stare decisis doktrini, mahkemelerin emsal yargı kararlarına doğrudan bağlılığını ifade eder."},{"id":"W5_Q3","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Belirli bir ülkede belirli bir dönemde yürürlükte bulunan, yetkili organlarca konulmuş yazılı ve yazılı olmayan bütün hukuk kurallarını ifade eden kavram aşağıdakilerden hangisidir?","tooltips":{"hukuk kuralları":"Yetkili mercilerce konulan ve kamu gücüyle desteklenen genel ve soyut davranış kurallarıdır."},"options":{"A":"Tarihi hukuk","B":"İdeal hukuk","C":"Mevzu hukuk","D":"Pozitif hukuk","E":"Doğal hukuk"},"correct_option":"D","explanations":{"A":"Yanlış. Tarihi hukuk, geçmişte yürürlükte kalmış ancak günümüzde bağlayıcılığını yitirmiş hukuk düzenini tanımlar.","B":"Yanlış. İdeal hukuk, yürürlükteki kuralları değil, adalet anlayışına göre olması arzulanan hukuku belirtir.","C":"Yanlış. Mevzu hukuk yalnızca yetkili makamlarca yürürlüğe konulmuş yazılı kuralları kapsar; yazısız kuralları içermez.","D":"Doğru. Pozitif hukuk, belirli bir ülkede belirli bir zamanda geçerli olan yazılı ve yazılı olmayan tüm kuralların toplamıdır.","E":"Yanlış. Doğal hukuk, insan aklına ve evrensel ahlaki değerlere dayanan ideal nitelikli hukuktur."},"overall_explanation":"Pozitif hukuk, yürürlükteki yazılı kurallar ile yazılı olmayan örf ve âdet hukuku kurallarının tamamını kapsayan üst kavramdır."},{"id":"W5_Q4","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Aşağıdakilerden hangisi pozitif hukukun tali yani yardımcı kaynakları arasında yer alır?","tooltips":{"tali":"Asli nitelik taşımayan, hâkime karar verme sürecinde yalnızca yol gösteren veya rehberlik eden kaynak türüdür."},"options":{"A":"Örf ve âdet hukuku kuralları","B":"Bilimsel görüşler","C":"Cumhurbaşkanlığı kararnameleri","D":"İçtihadı birleştirme kararları","E":"Milletlerarası andlaşmalar"},"correct_option":"B","explanations":{"A":"Yanlış. Örf ve âdet hukuku, yazılı kaynak bulunmadığında başvurulması gereken bağlayıcı asli kaynaktır.","B":"Doğru. Doktrin yani bilimsel görüşler, hâkim açısından bağlayıcılığı bulunmayan yardımcı ve ihtiyari bir kaynaktır.","C":"Yanlış. Cumhurbaşkanlığı kararnameleri yazılı ve bağlayıcı birincil asli hukuk kaynağıdır.","D":"Yanlış. İçtihadı birleştirme kararları benzer uyuşmazlıklarda mahkemeleri bağlayan yazılı asli kaynaktır.","E":"Yanlış. Usulüne göre yürürlüğe konmuş milletlerarası andlaşmalar kanun düzeyinde bağlayıcı asli kaynaktır."},"overall_explanation":"Pozitif hukukun kaynakları bağlayıcılık güçlerine göre asli ve yardımcı kaynaklar olarak ayrılır. Doktrin ve yargı kararları yardımcı kaynaktır."},{"id":"W5_Q5","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Temel hak ve özgürlüklere ilişkin milletlerarası andlaşmalar ile ulusal kanunların aynı konuda farklı hükümler içermesi durumunda uygulanacak kural aşağıdakilerden hangisidir?","tooltips":{"milletlerarası andlaşmalar":"İki veya daha fazla devlet ile uluslararası kuruluş arasında uluslararası hukuka uygun olarak akdedilen yazılı bağlayıcı metinlerdir."},"options":{"A":"Öncelikle yürürlüğe giren metin tercih edilir","B":"Cumhurbaşkanlığı kararnamesi esas alınır","C":"Hâkim kendi takdiriyle örf ve âdete göre hüküm kurar","D":"Ulusal kanun hükümleri öncelikle tatbik edilir","E":"Milletlerarası andlaşma hükümlerine öncelik tanınır"},"correct_option":"E","explanations":{"A":"Yanlış. Yürürlük tarihi önceliği kuralı burada doğrudan işletilmez; anayasal özel çatışma normu uygulanır.","B":"Yanlış. Cumhurbaşkanlığı kararnamesi kanunun altında yer alır ve bu tür bir çatışmayı çözemez.","C":"Yanlış. Yazılı iki norm mevcutken örf ve âdet hukukuna başvurulması hukuken mümkün değildir.","D":"Yanlış. Anayasa\'nın 90. maddesi temel haklar alanında ulusal kanuna değil andlaşmaya öncelik vermiştir.","E":"Doğru. Anayasa m. 90/son gereğince temel hak ve özgürlüklere ilişkin andlaşmalar ile kanunlar çatıştığında andlaşma esas alınır."},"overall_explanation":"Anayasa m. 90/son fıkra uyarınca usulüne göre yürürlüğe konulmuş temel hak ve özgürlüklere ilişkin andlaşmalar ile kanunların çatışması hâlinde andlaşma hükümleri uygulanır."},{"id":"W5_Q6","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Normlar hiyerarşisinde kanun ile Cumhurbaşkanlığı kararnamesi arasındaki ilişki bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"normlar hiyerarşisi":"Hukuk kurallarının altlık-üstlük esasına göre derecelendirilmesini ve alt normun üst norma aykırı olamayacağını belirten sistemdir."},"options":{"A":"Kanunda açıkça düzenlenen konularda Cumhurbaşkanlığı kararnamesi çıkarılamaz","B":"Aynı konuyu düzenleyen Cumhurbaşkanlığı kararnamesi kanun hükmünü ilga eder","C":"Cumhurbaşkanlığı kararnameleri kanunlardan üstün basamakta yer alır","D":"Kanun ile kararname çatıştığında her durumda yürütmenin iradesi esas alınır","E":"Cumhurbaşkanlığı kararnamesi yalnızca Anayasa Mahkemesi kararlarına bağlıdır"},"correct_option":"A","explanations":{"A":"Doğru. Anayasa uyarınca kanunda açıkça düzenlenen alanlarda CBK çıkarılamaz ve kanunla çatışan CBK hükümleri uygulanamaz.","B":"Yanlış. CBK alt norm olduğu için üst norm olan kanunu ilga edemez; kanun hükümleri önceliklidir.","C":"Yanlış. Normlar hiyerarşisinde kanunlar Cumhurbaşkanlığı kararnamelerinden üstün bir basamakta bulunur.","D":"Yanlış. Yasama organının iradesini yansıtan kanun hükümleri CBK ile çatıştığında daima üstündür.","E":"Yanlış. CBK çıkarılırken yalnızca Anayasa değil, normlar hiyerarşisinde üstte yer alan kanunlar da bağlayıcıdır."},"overall_explanation":"Normlar piramidinde kanun CBK\'nin üstündedir. Kanunda açıkça düzenlenen konularda CBK çıkarılamaz; aynı konuda çatışma çıkarsa kanun hükümleri uygulanır."},{"id":"W5_Q7","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Bir toplumsal davranış biçiminin örf ve âdet hukuku kuralı haline gelebilmesi için aranan manevi unsur aşağıdakilerden hangisidir?","tooltips":{"örf ve âdet hukuku":"Toplumda kendiliğinden oluşup uzun süre uygulanan ve devlet yaptırımıyla desteklenen yazılı olmayan hukuk kuralıdır."},"options":{"A":"Yazılı bir metne dönüştürülmüş olması","B":"Davranışın çok uzun süredir kesintisiz uygulanması","C":"Kurala uymanın hukuken zorunlu olduğuna inanılması","D":"Hâkim tarafından kıyasen genişletilmesi","E":"Yasama organınca resmi olarak oylanması"},"correct_option":"C","explanations":{"A":"Yanlış. Örf ve âdet hukuku kuralı yazılı bir metne dönüştüğünde artık yazısız kaynak niteliğini kaybeder.","B":"Yanlış. Davranışın uzun süre kesintisiz uygulanması maddi unsurdur, manevi unsur değildir.","C":"Doğru. Toplumun bu davranışa uymayı hukuki bir yükümlülük sayması genel inanış yani manevi unsurdur.","D":"Yanlış. Kıyas hâkimin uyguladığı bir akıl yürütme yöntemidir, örfün kurucu manevi unsuru olamaz.","E":"Yanlış. Yasama organınca oylanıp yürürlüğe konan kurallar örf değil, doğrudan kanun niteliği kazanır."},"overall_explanation":"Örf ve âdet kuralının hukuki nitelik kazanması için maddi unsur olan kadimlik ile manevi unsur olan genel inanış bir arada gerçekleşmelidir."},{"id":"W5_Q8","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Yargıtay ve Danıştay içtihatları arasındaki çelişkileri gidermek amacıyla alınan ve benzer davalarda tüm yargıçları bağlayan kaynak aşağıdakilerden hangisidir?","tooltips":{"içtihat":"Mahkemelerin benzer uyuşmazlıklarda hukuk kurallarını yorumlayarak oluşturdukları yerleşik yargı kararlarıdır."},"options":{"A":"Doktrin","B":"Bakanlık genelgesi","C":"Cumhurbaşkanlığı kararnamesi","D":"İdari tebliğ","E":"İçtihadı birleştirme kararı"},"correct_option":"E","explanations":{"A":"Yanlış. Doktrin bilim insanlarının görüşleridir ve mahkemeler açısından bağlayıcılığı bulunmaz.","B":"Yanlış. Genelgeler idare içi işleyişe yönelik düzenleyici işlemlerdir, yargıyı bağlayıcı yargısal içtihat değildir.","C":"Yanlış. Cumhurbaşkanlığı kararnamesi yürütme organının çıkardığı bir asli normdur, yüksek mahkeme kararı değildir.","D":"Yanlış. Tebliğler idarenin mevzuatı açıklamak için yayımladığı alt düzenleyici işlemlerdir.","E":"Doğru. İçtihadı birleştirme kararları, yargı içtihatları arasındaki ayrılıkları gideren ve hâkimleri bağlayan yazılı kaynaktır."},"overall_explanation":"Normal yargı kararları yardımcı kaynak iken yüksek mahkemelerin Genel Kurullarınca alınan İçtihadı Birleştirme Kararları benzer davalarda bağlayıcı asli kaynak niteliğindedir."},{"id":"W5_Q9","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Asıl şey yok edilmedikçe, zarara uğratılmadıkça veya yapısı değiştirilmedikçe ondan ayrılması mümkün olmayan parça aşağıdakilerden hangisidir?","tooltips":{"mütemmim cüz":"Asıl şeyin temel unsuru olan ve o şey tahrip edilmeden veya bozulmadan ayrılamayan parçadır."},"options":{"A":"Eklenti","B":"Mütemmim cüz","C":"Taşınır eşya","D":"Misli eşya","E":"Tüketilebilen eşya"},"correct_option":"B","explanations":{"A":"Yanlış. Eklenti asıl şeyden ayrıldığında her iki şey de bağımsız varlığını ve yapısını koruyabilir.","B":"Doğru. Ayrılmaz parça olarak da adlandırılan mütemmim cüz, asıl şey bozulmadan veya parçalanmadan ayrılamaz.","C":"Yanlış. Taşınır eşya bir mekândan diğerine özüne zarar verilmeden taşınabilen eşyayı ifade eder.","D":"Yanlış. Misli eşya piyasada adedi, tartısı veya ölçüsüyle belirlenebilen eşya türünü anlatır.","E":"Yanlış. Tüketilebilen eşya kullanılmakla yok olan ya da elden çıkan eşyayı kapsar."},"overall_explanation":"Mütemmim cüz, yerel âdetlere göre asıl şeyin zorunlu unsuru olan ve asıl şeyden ayrılması tahribat veya yapı değişikliği doğuran ayrılmaz parçadır."},{"id":"W5_Q10","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Bir gözlük ile onu korumak amacıyla tahsis edilen gözlük kılıfı arasındaki hukuki bağlantı türü aşağıdakilerden hangisidir?","tooltips":{"eklenti":"Asıl şeyin işletilmesi veya korunması amacıyla sürekli olarak ona tahsis edilen bağımsız taşınır eşyadır."},"options":{"A":"Mütemmim cüz bağı","B":"Bölünemez eşya bağı","C":"Hukuki semere bağı","D":"Eklenti bağı","E":"Taşınmaz yükü bağı"},"correct_option":"D","explanations":{"A":"Yanlış. Kılıf gözlükten ayrıldığında gözlük de kılıf da yapısal zarar görmez, dolayısıyla mütemmim cüz değildir.","B":"Yanlış. Bölünemez eşya maddi veya iktisadi değeri bozulmadan paylaştırılamayan eşyadır.","C":"Yanlış. Hukuki semere kira veya faiz gibi bir eşyadan elde edilen hukuki gelirleri anlatır.","D":"Doğru. Gözlük kılıfı, asıl şeyin korunması ve yararlanılması amacıyla tahsis edilmiş bağımsız bir eklentidir.","E":"Yanlış. Taşınmaz yükü bir taşınmaz malikinin diğer kişi lehine bir edim borcu altına girmesini düzenler."},"overall_explanation":"Asıl şeyin işletilmesi veya korunması için sürekli tahsis edilen ancak ayrıldığında eşyanın yapısını bozmayan bağımsız nesneler eklenti niteliğindedir."},{"id":"W5_Q11","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Hâkimin önüne gelen somut bir uyuşmazlıkta olaya uygulanabilecek hiçbir yazılı kuralın bulunmaması durumu aşağıdakilerden hangisidir?","tooltips":{"kanun boşluğu":"Yazılı hukuk kurallarında somut bir uyuşmazlığa uygulanacak açık bir hükmün bulunmaması halidir."},"options":{"A":"Hukuk boşluğu","B":"Kanun boşluğu","C":"Örtülü boşluk","D":"Kural içi boşluk","E":"Yargısal bağışıklık"},"correct_option":"B","explanations":{"A":"Yanlış. Hukuk boşluğu, hem yazılı hem de yazılı olmayan hiçbir normun bulunmaması hâlidir.","B":"Doğru. Yalnızca yazılı kaynaklarda somut olaya uygulanacak hükmün yer almaması durumu kanun boşluğudur.","C":"Yanlış. Örtülü boşluk, kanunda hüküm bulunmasına rağmen hükmün amacına göre istisna getirilmemesi durumudur.","D":"Yanlış. Kural içi boşluk, kanun koyucunun bilerek ve isteyerek hâkime takdir yetkisi bıraktığı alandır.","E":"Yanlış. Yargısal bağışıklık mahkemelerin belirli kişiler veya devletler üzerinde yargı yetkisi kullanamamasıdır."},"overall_explanation":"Yazılı metinlerde uyuşmazlığı çözecek normun bulunmaması kanun boşluğudur. Yazılı olmayan örf ve âdet hukuku kuralları da yoksa o takdirde hukuk boşluğu doğar."},{"id":"W5_Q12","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Türk Medeni Kanunu m. 1 uyarınca bir davada hem yazılı hukukta hem de örf ve âdet hukukunda uygulanabilir hüküm bulunmadığında hâkim nasıl hareket eder?","tooltips":{"hukuk boşluğu":"Uyuşmazlığın çözümüne yönelik ne yazılı hukuk kaynaklarında ne de örf ve âdet hukukunda uygulanabilir bir kuralın bulunmaması halidir."},"options":{"A":"Kanun koyucu olsaydı nasıl bir kural koyacak idiyse ona göre karar verir","B":"Kanun hükmünün yokluğunu gerekçe göstererek davayı derhal reddeder","C":"Uyuşmazlığı çözmek üzere yasama organına resmi başvuruda bulunur","D":"Tarafların anlaşması için dosyayı resen arabuluculuk kuruluna devreder","E":"Önceki hükümet döneminde yürürlükten kalkan kanun hükmünü uygular"},"correct_option":"A","explanations":{"A":"Doğru. TMK m. 1 uyarınca hukuk boşluğu halinde hâkim, kendisi kanun koyucu olsaydı koyacağı kurala göre karar verir.","B":"Yanlış. Hâkim hukuk kuralı bulunmadığı gerekçesiyle adaleti yerine getirmekten kaçınamaz ve davayı sonuçsuz bırakamaz.","C":"Yanlış. Hâkimin yargılama sürecini durdurup yasama organından kural çıkarmasını talep etme yetkisi yoktur.","D":"Yanlış. Hukuk boşluğunu gidermek hâkimin yargısal görevidir; dosya zorunlu olarak arabulucuya gönderilemez.","E":"Yanlış. Yürürlükten kaldırılmış ilga normlar pozitif hukuk niteliğini kaybettiğinden doğrudan uygulanamaz."},"overall_explanation":"TMK 1. madde gereğince kanunda ve örf-âdet hukukunda hüküm bulunmadığında ortaya çıkan hukuk boşluğunda hâkim kanun koyucu gibi hareket ederek hukuk yaratır."},{"id":"W5_Q13","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Hâkimin somut bir davada hukuk yaratırken oluşturduğu kararın hukuki niteliği ve etkisi bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"inter partes":"Hukuki işlemin veya mahkeme kararının yalnızca o ilişkinin ya da davanın tarafları üzerinde sonuç doğurmasıdır."},"options":{"A":"Tüm vatandaşları bağlayan genel ve soyut bir kanun niteliği kazanır","B":"Resmi Gazete\'de yayımlandığı anda tüm mahkemeler için bağlayıcı olur","C":"Üst mahkemelerin denetiminden muaf kesin bir hüküm oluşturur","D":"Hüküm yalnızca görülmekte olan davanın tarafları açısından bağlayıcıdır","E":"Alt derece mahkemelerinin benzer tüm davalarda uygulamasını zorunlu kılar"},"correct_option":"D","explanations":{"A":"Yanlış. Yargıcın yarattığı kural yasama organı tasarrufu olmadığından genel ve soyut bir kanun niteliği taşımaz.","B":"Yanlış. Yerel mahkeme kararları Resmi Gazete\'de yayımlanarak genel bağlayıcılık kazanan normlara dönüşmez.","C":"Yanlış. Hâkimin yarattığı çözümler istinaf ve temyiz gibi üst yargı denetimine ve bozulmasına açıktır.","D":"Doğru. Hâkimin hukuk yaratması sonucunda verilen karar sadece o somut davanın tarafları bakımından bağlayıcıdır.","E":"Yanlış. Kara Avrupası sisteminde hâkim kararları diğer mahkemeleri bağlayıcı zorunlu emsal sayılmaz."},"overall_explanation":"Hâkimin yarattığı hukuk yasama işlemi gibi genel ve soyut bir kural değildir. Karar yalnızca taraflar arasında geçerlidir ve üst yargı denetimine tâbidir."},{"id":"W5_Q14","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Babanın ölümü halinde torununu görmek isteyen babaanneye velayet hükümlerinin benzetilerek uygulanması hâkimin hangi yönteme başvurduğunu gösterir?","tooltips":{"kıyas":"Kanunda belirli bir durum için öngörülmüş kuralın benzer nitelikteki ancak düzenlenmemiş bir duruma uygulanması işlemidir."},"options":{"A":"Genişletici kanun koyma","B":"Tarihsel yorumlama","C":"Kıyas yoluyla boşluk doldurma","D":"Örf ve âdet ikamesi","E":"Yargısal bağışıklık tanıma"},"correct_option":"C","explanations":{"A":"Yanlış. Hâkim yeni kanun koyamaz; yalnızca mevcut kuralları benzetme yöntemiyle uygular.","B":"Yanlış. Tarihsel yorumlama kanun koyucunun o kanunu yaparken taşıdığı sübjektif iradeyi araştırmaktır.","C":"Doğru. Kanunun velayet sahibi baba için öngördüğü kuralın benzer nitelikteki babaanneye uygulanması kıyastır.","D":"Yanlış. Olayda yerel bir gelenek uygulanmamakta, doğrudan kanundaki benzer bir hüküm genişletilmektedir.","E":"Yanlış. Yargısal bağışıklık yargı yetkisinin bulunmamasıyla ilgilidir, uyuşmazlığın esasıyla ilgili değildir."},"overall_explanation":"Kanun koyucunun benzer nitelikteki bir ilişki için öngördüğü hükmün düzenlenmemiş uyuşmazlığa tatbik edilmesi kıyas işlemidir."},{"id":"W5_Q15","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Marksist-Leninist ideolojiye dayanan ve üretim araçları üzerindeki bireysel mülkiyet ile klasik özel hukuk ayrımını reddeden hukuk sistemi aşağıdakilerden hangisidir?","tooltips":{"üretim araçları":"Mal ve hizmet üretmek için kullanılan fabrika, arazi, makine ve tesis gibi maddi varlıkların bütünüdür."},"options":{"A":"Kara Avrupası Hukuk Sistemi","B":"Anglo-Amerikan Hukuk Sistemi","C":"İslam Hukuku","D":"Roma Hukuku","E":"Sosyalist Hukuk Sistemi"},"correct_option":"E","explanations":{"A":"Yanlış. Kara Avrupası hukuk sistemi özel mülkiyet hakkını ve özel hukuk ayrımını temel kabul eder.","B":"Yanlış. Anglo-Amerikan hukuk sistemi piyasa ekonomisini ve bireysel mülkiyet haklarını korur.","C":"Yanlış. İslam hukuku meşru yollardan elde edilen bireysel mülkiyet hakkını koruma altına alır.","D":"Yanlış. Roma hukuku bireysel mülkiyeti mülkiyet hakkının merkezine yerleştirmiştir.","E":"Doğru. Sosyalist hukuk sistemi kolektif mülkiyeti benimser, özel hukuk ve bireysel mülkiyet ayrımını reddeder."},"overall_explanation":"Sosyalist hukuk sistemi devlet planlamasını, kamu mülkiyetini ve kolektif iradeyi esas alarak klasik burjuva özel hukuk ayrımını tasfiye etmiştir."},{"id":"W5_Q16","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Aşağıdakilerden hangisi İslam hukukunun ikincil kaynakları arasında yer alır?","tooltips":{"icmâ":"İslam hukuk bilginlerinin belirli bir döneme veya konuya ilişkin verdikleri ortak hüküm veya fikir birliğidir."},"options":{"A":"İcmâ ve kıyas","B":"Kur\'an ve sünnet","C":"Kanun ve yönetmelik","D":"Mecelle ve tüzük","E":"İçtihat ve ferman"},"correct_option":"A","explanations":{"A":"Doğru. İslam hukukunda Kur\'an ve sünnet asli birincil kaynak iken icmâ ve kıyas ikincil kaynaklar arasındadır.","B":"Yanlış. Kur\'an ve sünnet ikincil değil, ilahi vahye dayanan temel asli kaynaklardır.","C":"Yanlış. Kanun ve yönetmelik modern pozitif hukuk kuralları olup klasik fıkıh kaynakları tasnifine girmez.","D":"Yanlış. Mecelle 19. yüzyılda Ahmet Cevdet Paşa başkanlığında hazırlanmış bir kanunlaştırma çalışmasıdır.","E":"Yanlış. Ferman padişahın örfi yetkisine dayanan idari yazılı emir niteliğindedir."},"overall_explanation":"İslam hukukunda vahiy kaynaklı Kur\'an ve sünnet birincil, akıl yürütme ve uzlaşıya dayalı icmâ ve kıyas ise ikincil kaynak kategorisindedir."},{"id":"W5_Q17","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"19. yüzyılda Ahmet Cevdet Paşa başkanlığında hazırlanan ve İslam borçlar ile eşya hukukunu kanun formunda derleyen eser aşağıdakilerden hangisidir?","tooltips":{"kodifikasyon":"Dağınık haldeki hukuk kurallarının sistemli, mantıklı ve bütünsel bir kanun metni haline getirilmesidir."},"options":{"A":"Kanunname-i Âl-i Osman","B":"Fatih Kanunnamesi","C":"Corpus Iuris Civilis","D":"Hukuk-ı Aile Kararnamesi","E":"Mecelle-i Ahkâm-ı Adliye"},"correct_option":"E","explanations":{"A":"Yanlış. Kanunname-i Âl-i Osman Osmanlı devlet teşkilatını ve kamu idaresini düzenleyen padişah kanunnameleridir.","B":"Yanlış. Fatih Kanunnamesi Osmanlı devlet nizamı ve idaresine ilişkin klasik dönem metnidir.","C":"Yanlış. Corpus Iuris Civilis Roma İmparatoru Justinianus döneminde derlenen Roma hukuku külliyatıdır.","D":"Yanlış. Hukuk-ı Aile Kararnamesi 1917 yılında aile hukukunu modernleştirmek üzere çıkarılmış düzenlemedir.","E":"Doğru. Mecelle-i Ahkâm-ı Adliye, Ahmet Cevdet Paşa başkanlığında hazırlanan ilk İslami medeni kanun kodifikasyonudur."},"overall_explanation":"Mecelle, İslam borçlar ve eşya hukukunun medeni kanun biçiminde sistemleştirilip kodifiye edildiği temel tarihsel mevzuattır."},{"id":"W5_Q18","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Aşağıdakilerden hangisi normlar hiyerarşisinde en alt basamakta yer alan idari düzenleyici işlemlerden biridir?","tooltips":{"genelge":"Kamu kurumlarının kanun ve yönetmeliklerin uygulanmasını alt birimlere iletmek üzere yayımladığı yazılı emirlerdir."},"options":{"A":"Anayasa","B":"Genelge","C":"Kanun","D":"Yönetmelik","E":"Cumhurbaşkanlığı kararnamesi"},"correct_option":"B","explanations":{"A":"Yanlış. Anayasa normlar piramidinin en tepesinde yer alan en üstün bağlayıcı kaynaktır.","B":"Doğru. Genelgeler ve tebliğler idarenin operasyonel işleyişini belirleyen alt düzenleyici işlemler basamağında yer alır.","C":"Yanlış. Kanunlar anayasanın hemen altında bulunan yasama organı metinleridir.","D":"Yanlış. Yönetmelikler genelge ve tebliğlerin üstünde yer alan düzenleyici işlemlerdir.","E":"Yanlış. Cumhurbaşkanlığı kararnamesi yönetmeliklerin üzerinde yer alan bir yürütme normudur."},"overall_explanation":"Normlar hiyerarşisi Anayasa, Kanun/Andlaşma, CBK, Yönetmelik ve alt basamakta Genelge/Tebliğ şeklinde sıralanır."},{"id":"W5_Q19","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"I. Yazılı hukuk kuralları\\nII. Örf ve âdet hukuku\\nIII. Hâkimin hukuk yaratması\\n\\nTürk Medeni Kanunu m. 1 uyarınca bir davada uyuşmazlığı çözerken hâkimin başvuracağı normatif sıra aşağıdakilerden hangisidir?","tooltips":{"hukuk kuralları":"Kişilerin birbirleriyle ve toplumla olan ilişkilerini düzenleyen kamu yaptırımlı emir ve yasaklardır."},"options":{"A":"II - I - III","B":"III - I - II","C":"I - III - II","D":"I - II - III","E":"II - III - I"},"correct_option":"D","explanations":{"A":"Yanlış. Örf ve âdet hukuku yazılı kaynak varken uygulanamaz; önce yazılı hukuk kuralları tüketilir.","B":"Yanlış. Hâkimin hukuk yaratması en son başvurulacak aşamadır, ilk sıraya konulamaz.","C":"Yanlış. Hukuk yaratmadan önce mutlaka örf ve âdet hukukunun araştırılması gerekir.","D":"Doğru. Hâkim sırasıyla yazılı kuralları inceler, kanun boşluğunda örf-âdete bakar, onda da kural yoksa hukuk yaratır.","E":"Yanlış. Yazılı hukuk tüketilmeden diğer basamaklara geçilmesi hukuken mümkün değildir."},"overall_explanation":"TMK 1. madde başvuru hiyerarşisini sırasıyla yazılı kaynaklar, örf ve âdet hukuku ve son olarak hâkimin hukuk yaratması olarak belirlemiştir."},{"id":"W5_Q20","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Bir otomobilin satışı sırasında aksine bir anlaşma yoksa otomobilin stepnesi ve bijon anahtarının da hukuken devredilmiş sayılmasının sebebi aşağıdakilerden hangisidir?","tooltips":{"eklenti":"Asıl şeyin işletilmesi veya korunması amacıyla sürekli olarak ona tahsis edilen bağımsız taşınır eşyadır."},"options":{"A":"Otomobilin ayrılmaz bir parçası niteliği taşıması","B":"Birbirinden ayrılması durumunda aracın tahrip olması","C":"Asıl şeye yapılan tasarrufun eklentiyi de kapsaması","D":"Taşınmaz mülkiyetinin zorunlu bir uzantısı sayılması","E":"Hukuki semere niteliğinde bağımsız gelir getirmesi"},"correct_option":"C","explanations":{"A":"Yanlış. Stepne ve aletler aracın ayrılmaz parçası yani mütemmim cüzü değil, eklentisidir.","B":"Yanlış. Stepne araçtan ayrıldığında aracın veya aletin yapısında maddi bozulma veya yok olma meydana gelmez.","C":"Doğru. Eklenti asıl şeyin işletilmesine tahsis edilen bağımsız eşyadır ve aksi kararlaştırılmadıkça asıl şeye yapılan işlem onu da kapsar.","D":"Yanlış. Otomobil ve stepne taşınmaz değil, taşınır eşya niteliğindedir.","E":"Yanlış. Stepne bir gelir ya da semere değil, asıl eşyanın korunmasına yardımcı bir tamamlayıcı parçadır."},"overall_explanation":"Aksi yönde sözleşme bulunmadığı sürece asıl eşya üzerindeki tasarruf ve devir işlemleri o eşyanın eklentilerini de kendiliğinden kapsar."},{"id":"W5_Q21","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Aşağıdakilerden hangisi Kara Avrupası hukuk sistemini benimsemiş ülkeler arasında yer almaz?","tooltips":{"kodifikasyon":"Hukuk kurallarının kanun koyucu tarafından derlenip sistemli ve kapsamlı kanunlar haline getirilmesidir."},"options":{"A":"Türkiye","B":"Almanya","C":"Fransa","D":"İsviçre","E":"İngiltere"},"correct_option":"E","explanations":{"A":"Yanlış. Türkiye İsviçre Medeni Kanunu\'nu mehaz alarak Kara Avrupası hukuk ailesine katılmıştır.","B":"Yanlış. Almanya Kara Avrupası hukuk sisteminin en temel temsilcilerinden biridir.","C":"Yanlış. Fransa Napolyon Kanunları ile Kara Avrupası kodifikasyon hareketinin öncüsüdür.","D":"Yanlış. İsviçre Kara Avrupası hukuk çevresine mensuptur.","E":"Doğru. İngiltere yazılı kanunlar yerine içtihadi yargıç hukukuna dayanan Common Law sisteminin doğduğu ülkedir."},"overall_explanation":"İngiltere, ABD ve Avustralya gibi ülkeler Anglo-Amerikan Common Law sistemine dâhildir; Kara Avrupası ailesinde yer almazlar."},{"id":"W5_Q22","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Bir binanın kapı ve pencerelerinin asıl binadan sökülüp ayrı bir mülkiyete konu edilememesinin temel hukuki gerekçesi aşağıdakilerden hangisidir?","tooltips":{"mütemmim cüz":"Asıl şeyin temel unsuru olan ve o şey tahrip edilmeden veya bozulmadan ayrılamayan parçadır."},"options":{"A":"Asıl taşınmazın eklentisi niteliğinde kalması","B":"Asıl şeyin mütemmim cüzü olması ve bağımsız mülkiyetinin bulunmaması","C":"Yalnızca taşınır eşyalar üzerinde mülkiyet kurulabilmesi","D":"Kanun koyucunun bina için örf ve âdet hukukunu zorunlu kılması","E":"Sözleşmeyle bağımsız mülkiyete elverişli tüketim malı sayılması"},"correct_option":"B","explanations":{"A":"Yanlış. Kapı ve pencere ayrıldığında binanın yapısı bozulacağından eklenti değil, mütemmim cüzdür.","B":"Doğru. Mütemmim cüz ayrıldığında asıl şey zarara uğrar; asıl şeyden bağımsız olarak satılamaz ve mülkiyete konu olamaz.","C":"Yanlış. Mülkiyet hakkı hem taşınır hem de taşınmaz mallar üzerinde geçerli ayni bir haktır.","D":"Yanlış. Durum kanunun emredici eşya hukuku tanımıyla ilgilidir, örf hukuku uygulamasından kaynaklanmaz.","E":"Yanlış. Mütemmim cüz niteliğindeki parçalar sözleşmeyle tüketim malı sayılarak asıldan ayrı satılamaz."},"overall_explanation":"Mütemmim cüz asıl eşyanın ayrılmaz bir parçasıdır. Asıl şeyden bağımsız olarak haczedilemez, satılamaz ve ayrı bir mülkiyete konu edilemez."},{"id":"W5_Q23","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Aşağıdakilerden hangisi örf ve âdet kurallarının maddi yani nesnel unsurunu ifade eder?","tooltips":{"örf ve âdet hukuku":"Toplumda kendiliğinden oluşup uzun süre uygulanan ve devlet yaptırımıyla desteklenen yazılı olmayan hukuk kuralıdır."},"options":{"A":"Kurala uymanın hukuki zorunluluk olduğu inancı","B":"Davranışın anayasa metinlerinde zikredilmesi","C":"Davranış biçiminin uzun süredir kesintisiz tekrarlanması","D":"Hâkimin kuralı kıyas yoluyla yaratmış olması","E":"Yüksek mahkemenin emsal kararına dayanması"},"correct_option":"C","explanations":{"A":"Yanlış. Kurala uymanın zorunlu olduğuna inanılması manevi unsurdur.","B":"Yanlış. Anayasada yer alan normlar yazılı hukukun birincil parçasıdır, örf niteliği taşımaz.","C":"Doğru. Bir davranışın kesintisiz biçimde çok uzun süre tekrarlanması örf ve âdetin maddi unsurudur.","D":"Yanlış. Hâkimin hukuk yaratması hukuk boşluğu durumunda başvurulan bir faaliyettir.","E":"Yanlış. Emsal mahkeme kararlarına dayanılması yargısal içtihat ile ilgilidir."},"overall_explanation":"Örf ve âdetin maddi unsuru davranışın eskiden beri kesintisiz tatbik edilmesi iken manevi unsuru buna uyulmasının hukuken zorunlu sayılmasıdır."},{"id":"W5_Q24","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Aşağıdakilerden hangisi pozitif hukukun yazılı asli kaynakları arasında yer almaz?","tooltips":{"yazılı kaynaklar":"Yetkili devlet organları tarafından metin haline getirilip yayımlanan ve hâkimi bağlayan kurallardır."},"options":{"A":"Örf ve âdet hukuku","B":"Milletlerarası andlaşmalar","C":"Cumhurbaşkanlığı kararnameleri","D":"Yönetmelikler","E":"İçtihadı birleştirme kararları"},"correct_option":"A","explanations":{"A":"Doğru. Örf ve âdet hukuku asli bir kaynaktır ancak yazılı kaynak değil, yazılı olmayan hukuk kaynağıdır.","B":"Yanlış. Usulüne göre onaylanan milletlerarası andlaşmalar yazılı ve asli kaynaktır.","C":"Yanlış. Cumhurbaşkanlığı kararnamesi yürütmenin çıkardığı yazılı ve asli bir kaynaktır.","D":"Yanlış. Yönetmelikler idarenin yayımladığı yazılı ve bağlayıcı birincil normlardır.","E":"Yanlış. İçtihadı birleştirme kararları Resmi Gazete\'de yayımlanan yazılı ve bağlayıcı asli kaynaklardandır."},"overall_explanation":"Pozitif hukukun asli kaynakları yazılı ve yazısız olarak ikiye ayrılır. Örf ve âdet hukuku yazısız asli kaynaktır."},{"id":"W5_Q25","domain_id":5,"domain_name":"Hafta 5: Hukuk Sistemleri ve Hukukun Kaynakları","question":"Common Law sisteminde yeni bir kuralın oluşmasında en belirleyici yetkiye sahip olan merci aşağıdakilerden hangisidir?","tooltips":{"emsal karar":"Alt mahkemeleri ve sonraki yargıçları benzer davalarda bağlayan yol gösterici mahkeme kararıdır."},"options":{"A":"Parlamento komisyonu","B":"Bakanlar kurulu","C":"Devlet planlama teşkilatı","D":"Somut uyuşmazlığı çözen yargıç","E":"Hukuk fakültesi akademisyenleri"},"correct_option":"D","explanations":{"A":"Yanlış. Common Law sisteminin temel kural koyucu omurgasını meclis komisyonları değil, yargıç kararları oluşturur.","B":"Yanlış. Yürütme organı olan bakanlar kurulu yargıç hukuku sisteminin ana üreticisi değildir.","C":"Yanlış. Devlet planlama teşkilatı sosyalist hukuk sistemlerinde merkezi rol oynar.","D":"Doğru. Common Law yargıç hukuku olarak anılır ve kural somut olayı karara bağlayan yargıcın içtihadıyla gelişir.","E":"Yanlış. Akademisyenler doktrin üretir ancak sistem emsal yargıç kararları üzerinden yürür."},"overall_explanation":"Common Law sisteminde yargıç yalnızca kanun uygulayıcısı değil, verdiği emsal kararlarla kural koyan yapıcı konumundadır."}]'))},63915,a=>{a.v(JSON.parse('[{"id":"W6_Q1","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"2547 sayılı Yükseköğretim Kanunu uyarınca, bir yükseköğretim kurumunda yapılan sınavda kopyaya teşebbüs eden bir öğrenciye hangi disiplin cezası verilir?","tooltips":{"kopyaya teşebbüs":"Sınavda haksız sonuç elde etmeye yönelik hazırlık fiillerine başlayıp eylemi tamamlayamama durumudur.","disiplin cezası":"Öğrencinin mevzuata aykırı eylemleri neticesinde yetkili kurullar tarafından uygulanan idari yaptırımdır."},"options":{"A":"Bir hafta uzaklaştırma","B":"Uyarma","C":"Kınama","D":"Bir yarıyıl uzaklaştırma","E":"İki yarıyıl uzaklaştırma"},"correct_option":"C","explanations":{"A":"Yanlış. Bir haftadan bir aya kadar uzaklaştırma cezası kurum personeline yönelik tehdit veya huzuru bozma gibi fiiller için öngörülmüştür.","B":"Yanlış. 2547 sayılı Kanun\'un 54. maddesinde uyarma cezası müstakil bir ceza türü olarak sayılmamıştır.","C":"Doğru. 2547 sayılı Kanun m. 54/1-a bendinin 5 numaralı alt bendi uyarınca sınavlarda kopyaya teşebbüs etmek kınama cezasını gerektirir.","D":"Yanlış. Bir yarıyıl uzaklaştırma cezası kopyaya teşebbüs için değil, fiilen kopya çekmek veya çektirmek eylemi için uygulanır.","E":"Yanlış. İki yarıyıl uzaklaştırma cezası başkasının yerine sınava girmek gibi nitelikli eylemler için düzenlenmiştir."},"overall_explanation":"2547 sayılı Kanun m. 54 uyarınca kopyaya teşebbüs fiili kınama cezası kapsamına alınmış; fiilen kopya çekmek ise bir yarıyıl uzaklaştırma cezasına bağlanmıştır."},{"id":"W6_Q2","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"2547 sayılı Yükseköğretim Kanunu\'nun 54. maddesine göre, ders veya sınavların düzenini bozan bir öğrenciye aşağıdaki disiplin cezalarından hangisi uygulanır?","tooltips":{"sınavların düzenini bozan":"Sınav ortamının huzurlu, güvenli ve sağlıklı işleyişini sekteye uğratan davranışlardır."},"options":{"A":"Kınama","B":"Bir ay uzaklaştırma","C":"Bir yarıyıl uzaklaştırma","D":"İki yarıyıl uzaklaştırma","E":"Kurumdan çıkarma"},"correct_option":"A","explanations":{"A":"Doğru. 2547 sayılı Kanun m. 54/1-a bendi uyarınca ders, seminer, sınav ve laboratuvar gibi çalışmaların düzenini bozmak kınama cezasını gerektirir.","B":"Yanlış. Bir haftadan bir aya kadar uzaklaştırma cezası kurum huzurunu daha ağır biçimde ihlal eden eylemler için uygulanır.","C":"Yanlış. Bir yarıyıl uzaklaştırma cezası sınavda fiilen kopya çekmek gibi ağır ihlaller için öngörülmüştür.","D":"Yanlış. İki yarıyıl uzaklaştırma cezası cebir, tehdit veya başkasının yerine sınava girme fiillerinde verilir.","E":"Yanlış. Yükseköğretim kurumundan çıkarma cezası kanunda katalog olarak sayılan ağır suç niteliğindeki fiiller için düzenlenmiştir."},"overall_explanation":"2547 sayılı Kanun, sınav düzenini ve akademik çalışmaların huzurunu bozan fiilleri kınama cezası ile yaptırıma bağlamıştır."},{"id":"W6_Q3","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Bir üniversite öğrencisinin ara sınav sırasında fiilen kopya çektiğinin tutanakla tespit edilmesi halinde, 2547 sayılı Yükseköğretim Kanunu uyarınca verilecek disiplin cezası aşağıdakilerden hangisidir?","tooltips":{"kopya çektiğinin":"Sınav esnasında yetkisiz kaynaklardan veya kişilerden haksız şekilde bilgi temin etme eylemidir."},"options":{"A":"Kınama","B":"Bir ay uzaklaştırma","C":"İki yarıyıl uzaklaştırma","D":"Bir yarıyıl uzaklaştırma","E":"Kurumdan çıkarma"},"correct_option":"D","explanations":{"A":"Yanlış. Kınama cezası kopyaya teşebbüs aşamasında kalan veya sınav düzenini bozan davranışlar için uygulanır.","B":"Yanlış. Bir haftadan bir aya kadar uzaklaştırma yaptırımı gerektiren eylemler arasında kopya çekmek yer almaz.","C":"Yanlış. İki yarıyıl uzaklaştırma cezası kendi yerine başkasını sınava sokmak veya tehditle kopya çekmek hallerinde tatbik edilir.","D":"Doğru. 2547 sayılı Kanun m. 54/1-c bendi uyarınca sınavlarda kopya çekmek veya çektirmek bir yarıyıl için uzaklaştırma cezasını gerektirir.","E":"Yanlış. Kurumdan çıkarma cezası uyuşturucu ticareti veya silah taşımak gibi son derece ağır fiiller için geçerlidir."},"overall_explanation":"2547 sayılı Kanun m. 54 kapsamında fiilen kopya çekme veya çektirme eylemi bir yarıyıl yükseköğretim kurumundan uzaklaştırma cezasına tabidir."},{"id":"W6_Q4","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"2547 sayılı Yükseköğretim Kanunu kapsamında, kendi yerine başka bir kişiyi sınava soktuğu belirlenen bir öğrenci hakkında hangi disiplin cezasına hükmolunur?","tooltips":{"disiplin cezasına":"Mevzuatça yasaklanan fiilleri işleyen kişilere yönelik idari nitelikteki yaptırımlardır."},"options":{"A":"Bir yarıyıl uzaklaştırma","B":"İki yarıyıl uzaklaştırma","C":"Bir ay uzaklaştırma","D":"Kınama","E":"Kurumdan çıkarma"},"correct_option":"B","explanations":{"A":"Yanlış. Bir yarıyıl uzaklaştırma cezası öğrencinin bizzat kendisinin kopya çekmesi durumunda verilir.","B":"Doğru. 2547 sayılı Kanun m. 54/1-ç bendi uyarınca kendi yerine başkasını sınava sokmak veya başkasının yerine sınava girmek iki yarıyıl uzaklaştırma gerektirir.","C":"Yanlış. Bir haftadan bir aya kadar uzaklaştırma cezası daha hafif disiplin ihlalleri için düzenlenmiştir.","D":"Yanlış. Kınama cezası kopyaya teşebbüs veya sınav düzenini bozma fiillerine tatbik edilir.","E":"Yanlış. Yükseköğretim kurumundan çıkarma cezası kanunda sınırlı olarak sayılan ağır suç niteliğindeki haller için verilir."},"overall_explanation":"Kendi yerine başkasını sınava sokmak veya başkasının yerine sınava girmek, 2547 sayılı Kanun m. 54/1-ç uyarınca iki yarıyıl uzaklaştırma yaptırımı doğurur."},{"id":"W6_Q5","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"2547 sayılı Yükseköğretim Kanunu\'nun 54. maddesinde düzenlenen disiplin suçları ve cezaları eşleştirmelerinden hangisi yanlıştır?","tooltips":{"disiplin suçları":"Kurum düzenini bozan ve kanunda karşılığında yaptırım öngörülen hukuka aykırı eylemlerdir."},"options":{"A":"Sınavlarda kopyaya teşebbüs etmek cezası kınamadır","B":"Sınavların düzenini bozmak cezası kınamadır","C":"Sınavlarda kopya çekmek cezası bir yarıyıl uzaklaştırmadır","D":"Başkasının yerine sınava girmek cezası iki yarıyıl uzaklaştırmadır","E":"Tehditle kopya çekmek cezası kurumdan çıkarmadır"},"correct_option":"E","explanations":{"A":"Yanlış. Bu eşleştirme kanuna uygundur; teşebbüs fiili kınama yaptırımına bağlanmıştır.","B":"Yanlış. Bu eşleştirme kanuna uygundur; sınav düzenini bozmak kınama gerektirir.","C":"Yanlış. Bu eşleştirme kanuna uygundur; kopya çekmek bir yarıyıl uzaklaştırma gerektirir.","D":"Yanlış. Bu eşleştirme kanuna uygundur; başkasının yerine sınava girmek iki yarıyıl uzaklaştırma yaptırımı taşır.","E":"Doğru. 2547 sayılı Kanun m. 54/1-ç bendi uyarınca sınavlarda tehditle kopya çekmek kurumdan çıkarma değil, iki yarıyıl uzaklaştırma cezasını gerektirir."},"overall_explanation":"Sınavlarda tehditle kopya çekmek fiili kurumdan çıkarma değil, 2547 sayılı Kanun\'un 54. maddesi uyarınca iki yarıyıl uzaklaştırma cezası kapsamındadır."},{"id":"W6_Q6","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"2547 sayılı Yükseköğretim Kanunu\'na göre, sınavda kopyaya teşebbüs fiili ile fiilen kopya çekme fiilinin yaptırımları sırasıyla aşağıdakilerden hangisinde doğru verilmiştir?","tooltips":{"yaptırımları":"Hukuk kurallarına aykırı hareket edilmesi durumunda uygulanan zorlayıcı hukuki sonuçlardır."},"options":{"A":"Kınama ve bir yarıyıl uzaklaştırma","B":"Kınama ve iki yarıyıl uzaklaştırma","C":"Bir ay uzaklaştırma ve bir yarıyıl uzaklaştırma","D":"Bir yarıyıl uzaklaştırma ve iki yarıyıl uzaklaştırma","E":"Kınama ve kurumdan çıkarma"},"correct_option":"A","explanations":{"A":"Doğru. 2547 sayılı Kanun m. 54 uyarınca kopyaya teşebbüs kınama cezası, fiilen kopya çekmek ise bir yarıyıl uzaklaştırma cezası gerektirir.","B":"Yanlış. Kopya çekme eylemi iki yarıyıl değil, bir yarıyıl uzaklaştırma cezasına tabidir.","C":"Yanlış. Kopyaya teşebbüs için bir ay uzaklaştırma cezası öngörülmemiştir.","D":"Yanlış. Kopyaya teşebbüsün yaptırımı bir yarıyıl uzaklaştırma değil, kınamadır.","E":"Yanlış. Fiilen kopya çekmek kurumdan çıkarma yaptırımını doğurmaz."},"overall_explanation":"Kanun koyucu kopyaya teşebbüsü kınama cezasıyla karşılarken, tamamlanan kopya çekme eylemini bir yarıyıl uzaklaştırma yaptırımına bağlamıştır."},{"id":"W6_Q7","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk hukukunda normlar hiyerarşisinin en üst basamağında yer alan ve diğer tüm normların geçerlilik temelini oluşturan yazılı kaynak aşağıdakilerden hangisidir?","tooltips":{"normlar hiyerarşisinin":"Hukuk kurallarının üstünlük derecelerine göre sıralandığı piramidal basamaklar düzenidir."},"options":{"A":"Kanun","B":"Milletlerarası andlaşma","C":"Cumhurbaşkanlığı kararnamesi","D":"Anayasa","E":"İçtihadı birleştirme kararı"},"correct_option":"D","explanations":{"A":"Yanlış. Kanunlar Anayasa\'nın altında yer alır ve Anayasa\'ya uygun olmak zorundadır.","B":"Yanlış. Milletlerarası andlaşmalar kural olarak kanun düzeyindedir ve Anayasa\'nın üstünde yer almaz.","C":"Yanlış. Cumhurbaşkanlığı kararnameleri Anayasa ve kanunların altında bir basamaktadır.","D":"Doğru. Anayasa devletin temel yapısını kuran ve tüm alt kademedeki normlara meşruiyet veren en üstün temel kanun metnidir.","E":"Yanlış. İçtihadı birleştirme kararları yargısal bir yazılı kaynak olup Anayasa\'nın altındadır."},"overall_explanation":"Normlar hiyerarşisinin zirvesinde Anayasa yer alır; hiçbir kanun, kararname veya alt düzenleme Anayasa\'ya aykırı olamaz."},{"id":"W6_Q8","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Usulüne göre yürürlüğe konulmuş temel hak ve özgürlüklere ilişkin bir milletlerarası andlaşma ile bir kanun hükmünün aynı konuda farklı düzenleme içermesi halinde Anayasa madde 90 uyarınca nasıl bir hukuki sonuca varılır?","tooltips":{"milletlerarası andlaşma":"Uluslararası hukuk kişileri arasında karşılıklı hak ve borçlar doğuran yazılı mutabakat metnidir.","temel hak ve özgürlüklere":"Kişinin doğuştan sahip olduğu vazgeçilmez ve devredilmez anayasal koruma altındaki haklarıdır."},"options":{"A":"Kanun hükmü öncelikle uygulanır","B":"Milletlerarası andlaşma hükümleri esas alınır","C":"Hükümler çatıştığı için uyuşmazlıkta örf ve âdet uygulanır","D":"Hâkim kendi takdir yetkisiyle serbestçe seçim yapar","E":"Uyuşmazlık çözümsüz sayılarak dava reddedilir"},"correct_option":"B","explanations":{"A":"Yanlış. Temel hak ve özgürlüklere ilişkin andlaşmalarda kanun hükmü değil, andlaşma hükmü üstün kabul edilir.","B":"Doğru. Anayasa m. 90/son uyarınca temel hak ve özgürlüklere ilişkin andlaşmalar ile kanunlar çatıştığında andlaşma hükümleri esas alınır.","C":"Yanlış. Çatışma çözme kuralı varken örf ve âdet hukukuna başvurulamaz.","D":"Yanlış. Hâkimin serbest seçim yetkisi bulunmayıp anayasal kural gereği andlaşmayı tatbik etmesi zorunludur.","E":"Yanlış. Hukuk düzeni açık bir çatışma kuralı getirdiği için dava reddedilemez."},"overall_explanation":"Anayasa m. 90 gereğince temel hak ve özgürlüklere dair milletlerarası andlaşmalar ile kanunların çatışması halinde milletlerarası andlaşma hükümleri uygulanır."},{"id":"W6_Q9","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Milletlerarası andlaşmaların Türk normlar hiyerarşisindeki konumu ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","tooltips":{"normlar hiyerarşisindeki":"Hukuk kurallarının astlık ve üstlük ilişkilerini belirleyen derece düzenidir."},"options":{"A":"Tüm andlaşmalar istisnasız olarak Anayasa\'nın dahi üstünde yer alır","B":"Andlaşmaların tamamı kanunların daima altında kabul edilir","C":"Yalnızca ticari andlaşmalar kanunların üstünde bağlayıcılığa sahiptir","D":"Hiçbir milletlerarası andlaşma Türk mahkemelerinde doğrudan uygulanamaz","E":"Temel haklara ilişkin andlaşmalar çatışma halinde kanunların üstünde tutulurken diğer andlaşmalar kural olarak kanunla eşit düzeydedir"},"correct_option":"E","explanations":{"A":"Yanlış. Milletlerarası andlaşmalar hiçbir surette Anayasa\'nın üstünde yer almaz.","B":"Yanlış. Temel hak ve özgürlüklere ilişkin andlaşmalar kanunla çatıştığında kanunun üstünde kabul edilir.","C":"Yanlış. Ticari ve teknik andlaşmalar kanunların üstünde değil, kanun düzeyindedir.","D":"Yanlış. Usulüne göre onaylanan andlaşmalar iç hukukun doğrudan bir parçası haline gelir.","E":"Doğru. Anayasa m. 90 gereğince temel hak andlaşmaları kanunla çatışmada üstün gelirken, diğer andlaşmalar kanun basamağındadır."},"overall_explanation":"Milletlerarası andlaşmalar kural olarak kanun değerindedir; ancak temel hak ve özgürlüklere ilişkin olanlar kanunlarla çatışma halinde öncelikle uygulanır."},{"id":"W6_Q10","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Yürütme organı tarafından çıkarılan olağan Cumhurbaşkanlığı kararnamelerinin düzenleme sınırları bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"Cumhurbaşkanlığı kararnamelerinin":"Yürütme organının başı tarafından anayasal sınırlar dahilinde yürürlüğe konulan düzenleyici işlemlerdir."},"options":{"A":"Kanunlarda açıkça düzenlenen her konuda kararname çıkarılabilir","B":"Ceza hukukundaki suç ve cezalar kararname ile belirlenebilir","C":"Anayasa\'da münhasıran kanunla düzenlenmesi öngörülen konularda kararname çıkarılamaz","D":"Kişi hak ve ödevleri olağan kararnamelerle sınırlandırılabilir","E":"Kararname ile kanun çatıştığında Cumhurbaşkanlığı kararnamesi üstün gelir"},"correct_option":"C","explanations":{"A":"Yanlış. Kanunda açıkça düzenlenen konularda Cumhurbaşkanlığı kararnamesi çıkarılamaz.","B":"Yanlış. Suç ve ceza ihdası münhasıran kanunla düzenlenmesi gereken alanlardandır.","C":"Doğru. Anayasa\'da münhasıran kanunla düzenlenmesi öngörülen konularda ve kanunda açıkça düzenlenen alanlarda CBK çıkarılamaz.","D":"Yanlış. Kişisel haklar ve siyasi haklar olağan kararnamelerle düzenlenemez.","E":"Yanlış. Kanun ile kararname farklı hükümler içerirse kanun hükümleri uygulanır."},"overall_explanation":"Anayasa uyarınca yasama yetkisinin tekelinde olan, münhasıran kanunla düzenlenmesi gereken ve kanunda açıkça düzenlenen konularda olağan CBK çıkarılamaz."},{"id":"W6_Q11","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Olağanüstü hâl Cumhurbaşkanlığı kararnamelerini, olağan Cumhurbaşkanlığı kararnamelerinden ayıran en temel özellik aşağıdakilerden hangisidir?","tooltips":{"Olağanüstü hâl":"Doğal afet, tehlikeli salgın veya ağır kriz dönemlerinde başvurulan istisnai anayasal yönetim rejimidir."},"options":{"A":"Kanun hükmünde olması ve temel hakları düzenleyebilmesi","B":"Yalnızca adli yargı hâkimlerince denetlenebilmesi","C":"Yürürlüğe girmesi için Resmi Gazete yayımının gerekmemesi","D":"Sadece idarenin iç işleyişine ilişkin kurallar koyabilmesi","E":"Normlar hiyerarşisinde yönetmeliklerin altında yer alması"},"correct_option":"A","explanations":{"A":"Doğru. Olağanüstü hâl kararnameleri kanun hükmündedir ve olağan kararnamelerden farklı olarak temel hak ve özgürlükleri sınırlandırabilir.","B":"Yanlış. Kararnamelerin yargısal denetimi adli yargı hâkimlerine ait değildir.","C":"Yanlış. Tüm kararnameler Resmi Gazete\'de yayımlanmak zorundadır.","D":"Yanlış. Olağanüstü halin gerektirdiği her türlü kamusal tedbiri düzenleyebilir.","E":"Yanlış. Olağanüstü hâl kararnameleri yönetmeliklerin çok üstünde, kanun gücündedir."},"overall_explanation":"Olağan CBK\'lar temel hakları düzenleyemez ve kanunların altındayken; OHAL CBK\'ları doğrudan kanun hükmünde olup temel hakları düzenleyebilir."},{"id":"W6_Q12","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Yönetmeliklerin normlar hiyerarşisindeki yeri ve hukuki niteliği ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","tooltips":{"Yönetmeliklerin":"Cumhurbaşkanı, bakanlıklar ve kamu tüzel kişilerinin görev alanlarını düzenlemek üzere çıkardıkları alt normlardır."},"options":{"A":"Kanunlardan üstün bağlayıcılık gücüne sahiptir","B":"Doğrudan Anayasa Mahkemesi tarafından iptal edilir","C":"Dayandığı kanundan bağımsız olarak ilk elden suç ihdas edebilir","D":"Yalnızca özel hukuk tüzel kişileri tarafından çıkarılabilir","E":"Kanunların ve Cumhurbaşkanlığı kararnamelerinin uygulanmasını sağlamak üzere çıkarılır"},"correct_option":"E","explanations":{"A":"Yanlış. Yönetmelikler hiyerarşide kanun ve kararnamelerin altında yer alır.","B":"Yanlış. Yönetmeliklerin yargısal denetimi idari yargı yerlerince yapılır.","C":"Yanlış. Suç ve ceza ihdası yalnızca kanunla yapılabilir, yönetmelikle suç oluşturulamaz.","D":"Yanlış. Yönetmelik çıkarma yetkisi kamu tüzel kişilerine, bakanlıklara ve Cumhurbaşkanına aittir.","E":"Doğru. Yönetmelikler kendi görev alanlarını ilgilendiren kanun ve CBK\'ların uygulanmasını sağlamak amacıyla ve bunlara uygun olarak çıkarılır."},"overall_explanation":"Yönetmelikler, kanun ve Cumhurbaşkanlığı kararnamelerinin uygulanışını göstermek amacıyla kamu otoritelerince çıkarılan alt normatif işlemlerdir."},{"id":"W6_Q13","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Yargıtay Büyük Genel Kurulu tarafından verilen İçtihadı Birleştirme Kararları hakkında aşağıdaki değerlendirmelerden hangisi doğrudur?","tooltips":{"İçtihadı Birleştirme Kararları":"Yüksek mahkemenin benzer hukuki konularda ortaya çıkan içtihat farklılıklarını gidermek için verdiği ilkesel kararlardır."},"options":{"A":"Yalnızca davanın tarafları için bağlayıcıdır","B":"Tüm adli yargı hâkimleri ile Yargıtay daireleri için kanun gibi bağlayıcıdır","C":"Diğer mahkemeler açısından sadece tavsiye niteliğindedir","D":"Sadece idari yargı organlarını bağlayan kurallardır","E":"Yazılı olmayan örf ve âdet hukuku kaynağı sayılır"},"correct_option":"B","explanations":{"A":"Yanlış. Sadece davanın taraflarını bağlayan kararlar münferit ilk derece mahkemesi ilamlarıdır.","B":"Doğru. İçtihadı birleştirme kararları adli yargı hâkimlerini ve Yargıtay dairelerini kanun kuvvetinde bağlar.","C":"Yanlış. Emsal nitelikteki genel içtihatlar tavsiye niteliğindeyken İBK mutlak bağlayıcıdır.","D":"Yanlış. Yargıtay adli yargının zirvesidir, kararları idari mahkemeleri değil adli yargıyı bağlar.","E":"Yanlış. İçtihadı birleştirme kararları pozitif hukukun yazılı kaynakları arasındadır."},"overall_explanation":"İçtihadı Birleştirme Kararları, yargıdaki içtihat uyuşmazlıklarını gidermek üzere verilen ve tüm adli hâkimleri kanun gibi bağlayan yazılı kaynaklardandır."},{"id":"W6_Q14","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Kanunlar kural olarak genel, soyut, objektif ve süreklidir. Aşağıdakilerden hangisi kanunların objektiflik ve genellik niteliğinin istisnasını oluşturan durumlardandır?","tooltips":{"objektiflik":"Hukuk kuralının belirli bir kişiye veya münferit bir olaya özgü olmaksızın herkese eşit uygulanmasıdır."},"options":{"A":"Türk Medeni Kanunu hükümleri","B":"Türk Ceza Kanunu hükümleri","C":"Türk Borçlar Kanunu hükümleri","D":"Belirli bir şahsın vatandaşlığa alınmasına ilişkin kanun","E":"Ticaret Kanunu hükümleri"},"correct_option":"D","explanations":{"A":"Yanlış. Türk Medeni Kanunu genel, soyut ve objektif kurallardan oluşur.","B":"Yanlış. Türk Ceza Kanunu tüm toplumu kapsayan genel kurallar içerir.","C":"Yanlış. Türk Borçlar Kanunu tüm borç ilişkileri için soyut düzenlemeler getirir.","D":"Doğru. Belirli bir şahsın vatandaşlığa alınması veya çıkarılmasına dair kanunlar objektiflik ve genellik niteliğinin istisnasıdır.","E":"Yanlış. Ticaret Kanunu ticari işletmeler için objektif kurallar ihtiva eder."},"overall_explanation":"Kanunlar kural olarak genel ve objektiftir; ancak belirli bir kimseye özgü vatandaşlığa kabul veya çıkarma gibi tasarrufi kanunlar bu kuralın istisnasıdır."},{"id":"W6_Q15","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Bir toplumsal uygulamanın örf ve âdet hukuku kuralı haline gelebilmesi için gerekli olan üç temel unsur aşağıdakilerden hangisinde birlikte verilmiştir?","tooltips":{"örf ve âdet hukuku":"Toplumda kendiliğinden doğan, süreklilik taşıyan ve devlet yaptırımıyla desteklenen yazılı olmayan kurallardır.","Süreklilik":"Bir toplumsal davranışın geçmişten günümüze kesintisiz tekrarlanmasını ifade eden maddi unsurdur."},"options":{"A":"Yazılı metin, kanunlaşma ve parlamento onayı","B":"Yargı kararı, doktrin desteği ve ahlaki uygunluk","C":"Süreklilik, genel inanış ve hukukilik","D":"İdari tasarruf, tebliğ ve resmi yayım","E":"Tarafların mutabakatı, vade ve ifa"},"correct_option":"C","explanations":{"A":"Yanlış. Örf ve âdet hukuku yazılı olmayan bir kaynaktır, parlamento işlemine dayanmaz.","B":"Yanlış. Yargı kararı ve doktrin yardımcı kaynaklardır; kurucu unsur değildir.","C":"Doğru. Örf ve âdet hukukunun üç kurucu unsuru maddi unsur olan süreklilik, manevi unsur olan genel inanış ve devlet yaptırımını ifade eden hukukiliktir.","D":"Yanlış. Bu unsurlar idari işlemlerin yürürlüğe girmesine ilişkindir.","E":"Yanlış. Bu unsurlar sözleşmelerin kurulması ve ifası ile ilgilidir."},"overall_explanation":"Örf ve âdetin bağlayıcı bir hukuk kaynağı olabilmesi için maddi unsur olan süreklilik, manevi unsur olan genel inanış ve devlet müeyyidesini belirten hukukilik gereklidir."},{"id":"W6_Q16","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Toplumda çok uzun süredir uygulanmasına ve yöre halkınca benimsenmesine rağmen kan davası gibi fiillerin örf ve âdet hukuku kuralı olarak kabul edilmemesinin temel gerekçesi nedir?","tooltips":{"Hukukilik unsurundan":"Toplumsal uygulamanın devletin genel hukuk nizamına, anayasal ilkelere ve kamu düzenine aykırı olmamasını ifade eden şarttır."},"options":{"A":"Hukukilik unsurundan yoksun olması ve kamu düzenine aykırılık taşıması","B":"Uygulamanın yeterli süreklilik taşımaması","C":"Toplum vicdanında genel inanış doğurmamış olması","D":"Resmî Gazete\'de yayımlanmamış olması","E":"Kanun koyucu tarafından çıkarılan bir kararnameye dayanmaması"},"correct_option":"A","explanations":{"A":"Doğru. Kan davası süreklilik ve genel inanış unsurlarına sahip olsa dahi kamu düzenine, hukuka ve insan haklarına aykırı olduğundan hukukilik unsurunu taşımaz.","B":"Yanlış. Kan davası asırlardır süregelen bir maddi sürekliliğe sahip olabilmektedir.","C":"Yanlış. Belirli bir zümre içinde bu yönde manevi bir inanç mevcut bulunabilir.","D":"Yanlış. Örf ve âdet hukuku yazısız kaynaktır, Resmi Gazete yayımı aranmaz.","E":"Yanlış. Örf ve âdet kuralları kararnameye dayanma zorunluluğu taşımaz."},"overall_explanation":"Bir geleneğin hukuk kuralı sayılabilmesi için devletin hukuk düzenine ve kamu nizamına aykırı olmaması, yani hukukilik unsurunu taşıması şarttır."},{"id":"W6_Q17","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk Medeni Kanunu\'nun 1. maddesi uyarınca, somut bir uyuşmazlığı karara bağlayacak olan hâkimin başvuracağı kaynakların zorunlu sıralaması aşağıdakilerden hangisidir?","tooltips":{"uyuşmazlığı":"Kişiler arasında hukuki hak ve yükümlülüklerin uygulanmasında ortaya çıkan uyuşmazlık veya dava konusudur."},"options":{"A":"Örf ve âdet hukuku, yazılı normlar, hâkimin hukuk yaratması","B":"Hâkimin hukuk yaratması, örf ve âdet hukuku, yazılı normlar","C":"Yazılı normlar, bilimsel görüşler, örf ve âdet hukuku","D":"Örf ve âdet hukuku, bilimsel görüşler, kanun koyucu iradesi","E":"Yazılı normlar, örf ve âdet hukuku, hâkimin hukuk yaratması"},"correct_option":"E","explanations":{"A":"Yanlış. Hâkim ilk olarak yazılı normları tüketmekle yükümlüdür.","B":"Yanlış. Hâkimin hukuk yaratması başvurulacak en son aşamadır.","C":"Yanlış. Bilimsel görüşler bağlayıcı bir basamak değil, yardımcı kaynaktır.","D":"Yanlış. Sıralama mutlaka yazılı hukuk kurallarıyla başlamalıdır.","E":"Doğru. TMK m. 1 uyarınca hâkim önce yazılı kanun hükmüne, yoksa örf ve âdet hukukuna, o da yoksa kendisi kanun koyucu olsaydı nasıl kural koyacak idiyse ona göre karar verir."},"overall_explanation":"TMK m. 1 gereğince hâkim sırasıyla önce yazılı normlara, ardından örf ve âdete bakar; her ikisinde de kural yoksa bizzat hukuk yaratır."},{"id":"W6_Q18","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Hukuk metodolojisinde uyuşmazlığa uygulanacak yazılı bir kanun hükmünün bulunmaması durumuna kanun boşluğu denirken, hem yazılı metinlerde hem de örf ve âdet hukukunda hiçbir kuralın bulunmaması haline ne ad verilir?","tooltips":{"kanun boşluğu":"Yazılı pozitif mevzuatta somut olaya uygulanabilecek bir kuralın yer almaması durumudur.","Hukuk boşluğu":"Uyuşmazlığın çözümü için hem yazılı kaynaklarda hem de yazılı olmayan örf ve âdet hukukunda hiçbir kural bulunmaması durumudur."},"options":{"A":"Kural içi boşluk","B":"Takdir yetkisi","C":"Hukuk boşluğu","D":"Örtülü boşluk","E":"Açık boşluk"},"correct_option":"C","explanations":{"A":"Yanlış. Kural içi boşluk, kanun koyucunun bilerek hâkime somut olayı takdir etme alanı bıraktığı hallerdir.","B":"Yanlış. Takdir yetkisi kanunun hâkime tanıdığı serbest değerlendirme yetkisidir.","C":"Doğru. Yazılı normlarda ve örf-âdet hukukunda somut kuralın bulunmaması hukuk boşluğu olarak adlandırılır.","D":"Yanlış. Örtülü boşluk kuralın lafzının çok geniş olup amacına göre daraltılması gereken haldir.","E":"Yanlış. Açık boşluk sadece yazılı metinde kuralın bulunmaması halidir."},"overall_explanation":"Pozitif hukukun yazılı kaynaklarında hüküm olmaması kanun boşluğudur; örf ve âdet dahil bağlayıcı hiçbir kuralın olmaması ise hukuk boşluğudur."},{"id":"W6_Q19","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk Medeni Kanunu\'nun 1. maddesi kapsamında hâkimin hukuk yaratması yetkisi ile ilgili aşağıdaki ifadelerden hangisi doğrudur?","tooltips":{"hukuk yaratması":"Hukuk boşluğu halinde hâkimin kanun koyucu gibi hareket ederek somut uyuşmazlığı çözecek kuralı üretmesidir."},"options":{"A":"Hâkimin yarattığı kural tüm ülke için genel ve soyut bir kanun niteliği kazanır","B":"Hâkim kendisi kanun koyucu olsaydı nasıl bir kural koyacak idiyse uyuşmazlığı ona göre çözer","C":"Hâkim yazılı bir kanun hükmünü beğenmediği takdirde doğrudan hukuk yaratabilir","D":"Hâkimin hukuk yaratması ancak örf ve âdet kurallarına başvurulmadan önce yapılabilir","E":"Hâkim yarattığı hukuku gerekçelendirirken Anayasa Mahkemesinden izin almak zorundadır"},"correct_option":"B","explanations":{"A":"Yanlış. Hâkimin hukuk yaratması genel bir kanun metni doğurmaz, kural yalnızca görülmekte olan uyuşmazlık için geçerlidir.","B":"Doğru. TMK m. 1 uyarınca yazılı norm ve örf-âdet bulunmadığında hâkim bizzat kanun koyucu gibi hareket ederek kıyas yoluyla hüküm kurar.","C":"Yanlış. Yazılı norm yürürlükte olduğu sürece hâkim kuralı uygulamak zorundadır.","D":"Yanlış. Hukuk yaratma yetkisi örf ve âdet tüketildikten sonra devreye girer.","E":"Yanlış. Hâkim kural üretirken herhangi bir makamdan izin almakla yükümlü değildir."},"overall_explanation":"Hâkimin hukuk yaratması, hukuk boşluğunun varlığı halinde hâkimin kanun koyucu rolünü üstlenerek somut davayı kıyas yoluyla çözüme bağlamasıdır."},{"id":"W6_Q20","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk Medeni Kanunu\'nun 1. maddesinin son cümlesinde geçen Hâkim, karar verirken bilimsel görüşlerden ve yargı kararlarından yararlanır ifadesi, bu iki kaynağın hukuki niteliği bakımından ne anlama gelir?","tooltips":{"bilimsel görüşlerden":"Hukuk bilginlerinin ve akademisyenlerin hukuki meselelere ilişkin kaleme aldığı doktriner açıklamalardır.","yargı kararlarından":"Mahkemelerin uyuşmazlıklar hakkında verdikleri ve emsal teşkil edebilen içtihatlardır."},"options":{"A":"Hâkim bu kaynaklardaki görüşlere uymakla kanunen zorunludur","B":"Bu kaynaklar normlar hiyerarşisinde kanunların üzerinde yer alır","C":"Bilimsel görüşler örf ve âdet hukukundan önce gelen bağlayıcı kaynaklardır","D":"Hâkim açısından yol gösterici nitelikte olan bağlayıcı olmayan yardımcı kaynaklardır","E":"Yargı kararları sadece ceza mahkemelerini bağlayan emredici normlardır"},"correct_option":"D","explanations":{"A":"Yanlış. Bilimsel görüşler ve münferit yargı kararları bağlayıcı değildir.","B":"Yanlış. Bu kaynaklar asli normların altında yardımcı konumdadır.","C":"Yanlış. Örf ve âdet asli kaynaktır; doktrin ise yardımcı niteliktedir.","D":"Doğru. Doktrin ve yargı kararları hâkimin yararlandığı fakat kendisini mutlak surette bağlamayan yardımcı kaynaklardır.","E":"Yanlış. Emsal yargı kararları bağlayıcı emredici norm vasfı taşımaz."},"overall_explanation":"Doktrin ve mahkeme içtihatları hukukun yardımcı kaynaklarıdır; hâkimi bağlamaz ancak kararın gerekçelendirilmesinde yol göstericidir."},{"id":"W6_Q21","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Tarafların kendi aralarında yapacakları sözleşmelerle aksini kararlaştıramayacakları, kamu düzeni ve genel ahlakı koruma gayesi güden hukuk kuralları aşağıdakilerden hangisidir?","tooltips":{"kamu düzeni":"Toplumun huzur, güvenlik ve düzen içinde yaşamasını sağlayan temel anayasal ve yasal kurumların bütünüdür."},"options":{"A":"Emredici hukuk kuralları","B":"Tamamlayıcı hukuk kuralları","C":"Yorumlayıcı hukuk kuralları","D":"Tanımlayıcı hukuk kuralları","E":"Yetki verici hukuk kuralları"},"correct_option":"A","explanations":{"A":"Doğru. Emredici hukuk kuralları kamu menfaatini koruduğu için tarafların farklı yönde anlaşma yapmalarını kesin olarak engeller.","B":"Yanlış. Tamamlayıcı kurallar aksine sözleşme yapılabilen yedek kurallardır.","C":"Yanlış. Yorumlayıcı kurallar taraflarca aksi kararlaştırılabilen kurallardır.","D":"Yanlış. Tanımlayıcı kurallar hukuki kavramların unsurlarını belirler.","E":"Yanlış. Yetki verici kurallar taraflara seçimlik hareket serbestisi tanır."},"overall_explanation":"Emredici kurallar, kamu düzenini ve zayıf tarafları korumak amacıyla irade serbestisini sınırlayan ve aksine düzenleme yapılamayan kurallardır."},{"id":"W6_Q22","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Tarafların serbest iradeleriyle aksini kararlaştırabildikleri ancak sözleşmede unuttukları veya düzenlemedikleri hususlarda kendiliğinden devreye giren yedek hukuk kurallarına ne ad verilir?","tooltips":{"yedek hukuk kurallarına":"Tarafların aksini kararlaştırmadığı durumlarda sözleşme ilişkilerine tatbik edilen kurallardır."},"options":{"A":"Emredici hukuk kuralları","B":"Yorumlayıcı hukuk kuralları","C":"Tamamlayıcı hukuk kuralları","D":"Tanımlayıcı hukuk kuralları","E":"Şekli hukuk kuralları"},"correct_option":"C","explanations":{"A":"Yanlış. Emredici kuralların aksinin kararlaştırılması hukuken mümkün değildir.","B":"Yanlış. Yorumlayıcı kurallar sözleşmedeki belirsiz terimleri aydınlatır, boşluk doldurmaz.","C":"Doğru. Tamamlayıcı kurallar tarafların sözleşmede üzerinde durmadıkları ve boş bıraktıkları hususları kendiliğinden doldurur.","D":"Yanlış. Tanımlayıcı kurallar hukuki müesseselerin tarifini yapar.","E":"Yanlış. Şekli kurallar hukuki işlemlerin kuruluş biçimini yönetir."},"overall_explanation":"Tamamlayıcı hukuk kuralları, tarafların sözleşmede suskun kaldığı eksik alanları doldurarak sözleşmenin ayakta kalmasını sağlar."},{"id":"W6_Q23","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk Borçlar Kanunu\'nun 207. maddesinde yer alan Sözleşme ile aksi kararlaştırılmadıkça veya aksine bir âdet bulunmadıkça, satıcı ve alıcı borçlarını aynı anda ifa etmekle yükümlüdürler hükmü hangi kural türüne örnektir?","tooltips":{"ifa":"Borçlunun borçlanmış olduğu edimi alacaklıya karşı yerine getirerek borcu sona erdirmesidir."},"options":{"A":"Emredici hukuk kuralı","B":"Yorumlayıcı hukuk kuralı","C":"Tanımlayıcı hukuk kuralı","D":"Şekil kuralı","E":"Tamamlayıcı hukuk kuralı"},"correct_option":"E","explanations":{"A":"Yanlış. Kanun metninde aksi kararlaştırılmadıkça dendiği için kural emredici değildir.","B":"Yanlış. Hüküm belirsiz bir vade terimini değil, ifa zamanı belirlenmediğinde ortaya çıkan boşluğu yönetir.","C":"Yanlış. Hüküm satım sözleşmesinin yasal tanımını yapmamaktadır.","D":"Yanlış. Maddede bir geçerlilik şekli öngörülmemiştir.","E":"Doğru. Taraflar sözleşmede ifa zamanını boş bıraktıklarında borçların aynı anda ifa edileceğini öngören kural tamamlayıcıdır."},"overall_explanation":"TBK m. 207/2, tarafların ifa zamanı kararlaştırmadığı durumlarda devreye girerek boşluğu dolduran tipik bir tamamlayıcı hukuk kuralıdır."},{"id":"W6_Q24","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Taraflarca sözleşmeye dahil edilmiş olan ancak birden fazla manaya gelebilecek belirsiz ifadelerin kanun tarafından tek bir anlama bağlandığı kural türü aşağıdakilerden hangisidir?","tooltips":{"belirsiz":"Birden çok anlama gelmeye müsait ve taraflar arasında ihtilaf doğurabilecek nitelikteki ifadedir."},"options":{"A":"Tamamlayıcı hukuk kuralı","B":"Yorumlayıcı hukuk kuralı","C":"Emredici hukuk kuralı","D":"Tanımlayıcı hukuk kuralı","E":"Cezai hukuk kuralı"},"correct_option":"B","explanations":{"A":"Yanlış. Tamamlayıcı kurallar sözleşmede hiç bulunmayan eksikliği giderir.","B":"Doğru. Yorumlayıcı kurallar taraflarca kullanılan ancak açık olmayan ifadeleri tek bir yasal anlama bağlar.","C":"Yanlış. Emredici kurallar tarafların irade serbestisini kamu düzeni gereği sınırlar.","D":"Yanlış. Tanımlayıcı kurallar hukuki kurumların yasal unsurlarını gösterir.","E":"Yanlış. Cezai kurallar suç ve yaptırım öngören düzenlemelerdir."},"overall_explanation":"Yorumlayıcı hukuk kuralları, sözleşmede yer verilen fakat muğlak bırakılan ifadelerin kanunen tek bir anlama bağlanmasını temin eder."},{"id":"W6_Q25","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk Borçlar Kanunu\'nun 91. maddesinde geçen Borcun ifası için ayın ortası belirlenmişse, bundan da ayın onbeşinci günü anlaşılır hükmü, işlevi bakımından hangi tür hukuk kuralıdır?","tooltips":{"ayın ortası":"Vade belirlenirken kullanılan ve takvimsel karşılığı kanunla netleştirilen süredir."},"options":{"A":"Emredici hukuk kuralı","B":"Tamamlayıcı hukuk kuralı","C":"Tanımlayıcı hukuk kuralı","D":"Yorumlayıcı hukuk kuralı","E":"Yetki verici hukuk kuralı"},"correct_option":"D","explanations":{"A":"Yanlış. Taraflar dilerlerse ayın ortası ile başka bir günü kastettiklerini sözleşmede belirtebilirler.","B":"Yanlış. İfa zamanı hiç belirlenmemiş olsaydı tamamlayıcı kural uygulanırdı; burada taraflarca kullanılmış bir terim vardır.","C":"Yanlış. Hüküm bir hukuki kurumu tanımlamamaktadır.","D":"Doğru. Tarafların sözleşmede kullandığı ayın ortası şeklindeki muğlak ifadeyi ayın on beşinci günü olarak aydınlattığı için yorumlayıcı kuraldır.","E":"Yanlış. Hüküm taraflardan birine özel bir takdir yetkisi vermemektedir."},"overall_explanation":"TBK m. 91/1, taraflarca sözleşmeye konulan ancak birden çok güne çekilebilecek bir ifadeyi netleştirdiği için yorumlayıcı bir kuraldır."},{"id":"W6_Q26","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk Medeni Kanunu\'nun 118. maddesinde yer alan Nişanlanma, evlenme vaadiyle olur hükmü, işlevine göre yapılan sınıflandırmada hangi kural türüne girer?","tooltips":{"Nişanlanma":"Evlenme vaadiyle kurulan ve taraflar arasında sadakat borcu doğuran aile hukuku ilişkisidir."},"options":{"A":"Tanımlayıcı hukuk kuralı","B":"Tamamlayıcı hukuk kuralı","C":"Yorumlayıcı hukuk kuralı","D":"Emredici yaptırım kuralı","E":"Yetki verici kural"},"correct_option":"A","explanations":{"A":"Doğru. TMK m. 118 nişanlanmanın kurucu unsurunu evlenme vaadi olarak açıklayıp kurumu tanımladığı için tanımlayıcı hukuk kuralıdır.","B":"Yanlış. Hüküm sözleşmedeki bir eksikliği doldurmamaktadır.","C":"Yanlış. Tarafların kullandığı muğlak bir terimi açıklamamaktadır.","D":"Yanlış. Hüküm cezai bir yaptırım kuralı değildir.","E":"Yanlış. Kişiye seçimlik bir yetki bahşetmemektedir."},"overall_explanation":"Tanımlayıcı hukuk kuralları, bir hukuki kurumun temel niteliklerini ve kurucu unsurlarını ortaya koyan normlardır."},{"id":"W6_Q27","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Tamamlayıcı hukuk kuralları ile yorumlayıcı hukuk kuralları arasındaki temel kavramsal fark aşağıdakilerden hangisidir?","tooltips":{"kavramsal":"Hukuki müesseselerin mantıksal tanım ve mahiyetlerine ilişkin olan niteliktir."},"options":{"A":"Tamamlayıcı kurallara uyulması zorunluyken yorumlayıcı kurallar tavsiye niteliğindedir","B":"Tamamlayıcı kurallar ceza hukukunda, yorumlayıcı kurallar idare hukukunda geçerlidir","C":"Yorumlayıcı kurallar boşluk doldururken tamamlayıcı kurallar Anayasa\'yı açıklar","D":"Tamamlayıcı kurallar kamu düzenini korurken yorumlayıcı kurallar sadece yabancılara uygulanır","E":"Tamamlayıcı kurallar sözleşmede hiç düzenlenmeyen boşlukları doldururken yorumlayıcı kurallar mevcut fakat belirsiz ifadeleri aydınlatır"},"correct_option":"E","explanations":{"A":"Yanlış. Her iki kural türü de yedek kuraldır ve aksi kararlaştırılmadığında bağlayıcı sonuç doğurur.","B":"Yanlış. Her iki kural grubu da esasen özel hukuk ve sözleşmeler hukukunda yer alır.","C":"Yanlış. Boşluk dolduran kural tamamlayıcı kuraldır.","D":"Yanlış. Kamu düzenini emredici kurallar korur, bu ayrım kural türlerini yansıtmaz.","E":"Doğru. Tamamlayıcı kurallar tarafların sustuğu boşlukları doldurur; yorumlayıcı kurallar ise tarafların kullandığı müphem ifadeleri tek anlama bağlar."},"overall_explanation":"Tamamlayıcı kural sözleşmedeki eksikliği kendiliğinden ikmal ederken, yorumlayıcı kural taraflarca kullanılmış olan belirsiz terimi aydınlatır."},{"id":"W6_Q28","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Türk yargı teşkilatında adli yargı kolunda yer alan ilk derece hukuk ve ceza mahkemelerinin kararlarına karşı son inceleme mercii olan yüksek mahkeme aşağıdakilerden hangisidir?","tooltips":{"adli yargı":"Özel hukuk uyuşmazlıkları ile ceza davalarının yürütüldüğü genel yargı koludur.","temyiz":"İlk derece ve istinaf mahkemelerinin kararlarının hukuka uygunluğunun yüksek mahkemece denetlenmesidir."},"options":{"A":"Danıştay","B":"Sayıştay","C":"Yargıtay","D":"Uyuşmazlık Mahkemesi","E":"Anayasa Mahkemesi"},"correct_option":"C","explanations":{"A":"Yanlış. Danıştay idari yargı kolunun en üst temyiz mahkemesidir.","B":"Yanlış. Sayıştay kamusal harcamaları ve hesapları denetleyen mali yargı merciidir.","C":"Doğru. Adli yargı kolundaki ilk derece ve istinaf incelemelerinin ardından en üst temyiz mercii Yargıtay\'dır.","D":"Yanlış. Uyuşmazlık Mahkemesi yargı kolları arasındaki görev çatışmalarını giderir.","E":"Yanlış. Anayasa Mahkemesi norm denetimi ve bireysel başvuruları inceler."},"overall_explanation":"Adli yargı düzeninde ilk derece mahkemeleri ve Bölge Adliye Mahkemelerinin ardından zirve denetim mercii Yargıtay\'dır."},{"id":"W6_Q29","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"İdarenin tek taraflı tasarruflarına karşı açılan iptal davaları ile idari eylemlerden doğan zararların giderildiği tam yargı davalarının görüldüğü yargı kolu ve temyiz mercii aşağıdakilerden hangisidir?","tooltips":{"iptal davaları":"İdari işlemlerin hukuka aykırılığı sebebiyle geçmişe etkili olarak yürürlükten kaldırılması talebiyle açılan davadır.","tam yargı davaları":"İdarenin eylem veya işlemlerinden dolayı kişisel hakları ihlal edilenlerin uğradığı zararların tazmini için açtığı davadır."},"options":{"A":"Adli Yargı ve Yargıtay","B":"İdari Yargı ve Danıştay","C":"Anayasa Yargısı ve Anayasa Mahkemesi","D":"Uyuşmazlık Yargısı ve Uyuşmazlık Mahkemesi","E":"Mali Yargı ve Sayıştay"},"correct_option":"B","explanations":{"A":"Yanlış. Adli yargı kişiler arasındaki özel hukuk ve ceza uyuşmazlıklarını inceler.","B":"Doğru. İdarenin işlem ve eylemlerine karşı açılan davalar idari yargı kolunda görülür ve temyiz mercii Danıştay\'dır.","C":"Yanlış. Anayasa yargısı kanunların anayasaya uygunluğunu inceler.","D":"Yanlış. Uyuşmazlık Mahkemesi yargı kolları arasındaki görev uyuşmazlıklarını çözer.","E":"Yanlış. Mali yargı kamu hesaplarının denetimiyle ilgilidir."},"overall_explanation":"İdarenin kamu gücüne dayanarak tesis ettiği işlem ve eylemlerin hukuka uygunluk denetimi idari yargı kolunda yapılır ve bu kolun üst mahkemesi Danıştay\'dır."},{"id":"W6_Q30","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Bir tazminat davasında hem İş Mahkemesinin hem de İdare Mahkemesinin kendisini görevsiz sayması sonucu ortaya çıkan görev uyuşmazlığını kesin olarak çözmeye yetkili yargı mercii aşağıdakilerden hangisidir?","tooltips":{"görev uyuşmazlığını":"Farklı yargı kollarına mensup mahkemelerin aynı davada kendilerini görevli veya görevsiz görmeleri durumudur."},"options":{"A":"Yargıtay","B":"Danıştay","C":"Anayasa Mahkemesi","D":"Uyuşmazlık Mahkemesi","E":"Bölge Adliye Mahkemesi"},"correct_option":"D","explanations":{"A":"Yanlış. Yargıtay adli yargı içerisindeki temyiz incelemesini yapar.","B":"Yanlış. Danıştay idari yargı içerisindeki temyiz incelemesini yürütür.","C":"Yanlış. Anayasa Mahkemesi kanunların norm denetimini ve temel hak ihlallerini inceler.","D":"Doğru. Adli ve idari yargı kolları arasındaki olumlu veya olumsuz görev uyuşmazlıklarını kesin olarak Uyuşmazlık Mahkemesi çözer.","E":"Yanlış. Bölge Adliye Mahkemesi adli yargıda istinaf merciidir."},"overall_explanation":"Farklı yargı düzenleri arasında ortaya çıkan görev ve hüküm uyuşmazlıklarını kesin karara bağlayan yargı mercii Uyuşmazlık Mahkemesidir."},{"id":"W6_Q31","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Kanunların, Cumhurbaşkanlığı kararnamelerinin ve TBMM İçtüzüğünün Anayasa\'ya uygunluğunu norm denetimi yoluyla inceleyen ve bireysel başvuruları karara bağlayan yargı mercii aşağıdakilerden hangisidir?","tooltips":{"norm denetimi":"Yasama veya yürütme işlemlerinin anayasal kurallara uygunluğunun yargısal yoldan incelenmesidir.","bireysel başvuruları":"Temel hakları kamu gücü tarafından ihlal edilen kişilerin başvurduğu anayasal yargı yoludur."},"options":{"A":"Anayasa Mahkemesi","B":"Yargıtay Hukuk Genel Kurulu","C":"Danıştay İdari Dava Daireleri Kurulu","D":"Uyuşmazlık Mahkemesi","E":"Hâkimler ve Savcılar Kurulu"},"correct_option":"A","explanations":{"A":"Doğru. Norm denetimi yapmak ve kamu gücünün temel hak ihlallerine karşı yapılan bireysel başvuruları incelemek Anayasa Mahkemesinin görevidir.","B":"Yanlış. Yargıtay adli yargı kolunda görev yapar.","C":"Yanlış. Danıştay idari yargı kolunda nihai denetim yapar.","D":"Yanlış. Uyuşmazlık Mahkemesi yargı kollarının görev çatışmalarını çözer.","E":"Yanlış. HSK hâkim ve savcıların özlük işlerini yöneten idari bir kuruldur."},"overall_explanation":"Anayasa Mahkemesi, kanun ve kararnamelerin anayasallık denetimini gerçekleştirir ve bireysel hak ihlallerini karara bağlar."},{"id":"W6_Q32","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Bir devletin yürürlüğe koyduğu hukuk kurallarının, kural olarak o devletin coğrafi egemenlik sınırları içerisindeki tüm olaylara ve kişilere uygulanmasını ifade eden ilke aşağıdakilerden hangisidir?","tooltips":{"coğrafi egemenlik":"Devletin kendi ülke sınırları üzerindeki mutlak hukuki ve idari yetki alanıdır."},"options":{"A":"Şahsilik ilkesi","B":"Geriye yürümezlik ilkesi","C":"Evleviyet ilkesi","D":"Ahde vefa ilkesi","E":"Mülkilik ilkesi"},"correct_option":"E","explanations":{"A":"Yanlış. Şahsilik ilkesi kanunların vatandaşın bulunduğu her yerde kişiye uygulanmasıdır.","B":"Yanlış. Geriye yürümezlik kuralın zaman bakımından uygulanışına ilişkindir.","C":"Yanlış. Evleviyet ilkesi bir mantıksal yorum yöntemidir.","D":"Yanlış. Ahde vefa sözleşmeye bağlılık prensibidir.","E":"Doğru. Hukuk kurallarının devletin coğrafi sınırları içerisindeki herkese ve her olaya tatbik edilmesi mülkilik ilkesidir."},"overall_explanation":"Hukukun yer bakımından uygulanmasında temel esas mülkilik ilkesidir; kurallar devletin sınırları dahilindeki tüm kişi ve olaylara uygulanır."},{"id":"W6_Q33","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Hukukun zaman bakımından uygulanmasında temel prensip kuralların ileriye etkili olması ve geriye yürümemesidir. Bu genel kuralın ceza hukukundaki en önemli istisnası aşağıdakilerden hangisidir?","tooltips":{"geriye yürümemesidir":"Yeni yürürlüğe giren kanunların geçmişte tamamlanmış eylemlere uygulanamaması kuralıdır.","Failin lehine":"Suç işleyen kişi hakkında daha hafif ceza öngören veya fiili suç olmaktan çıkaran yasal düzenlemedir."},"options":{"A":"Ağırlaştırıcı kanunun derhal yürürlüğe girmesi","B":"Failin lehine olan kanunun geriye yürümesi","C":"Zamanaşımı sürelerinin geriye dönük uzatılması","D":"Örf ve âdet kurallarının geçmişe uygulanması","E":"Soruşturma aşamasında sanık sıfatının kazanılması"},"correct_option":"B","explanations":{"A":"Yanlış. Failin aleyhine olan ağırlaştırıcı ceza kanunları geçmişe yürütülemez.","B":"Doğru. Kanunların geriye yürümezliği kuralının ceza hukukundaki evrensel istisnası, failin lehine olan hükümlerin geçmişe yürütülmesidir.","C":"Yanlış. Aleyhe olan zamanaşımı değişiklikleri geriye işletilemez.","D":"Yanlış. Ceza hukukunda örf ve âdetle suç ihdas edilemez.","E":"Yanlış. Sanık sıfatı kovuşturma evresine geçişle kazanılan usuli bir sıfattır."},"overall_explanation":"Kanunlar kural olarak ileriye etkilidir; ceza hukukunda failin yararına olan daha hafif kanun ise geçmişe etkili biçimde uygulanır."},{"id":"W6_Q34","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Kanun koyucunun belirli bir duruma özel olarak bağladığı hukuki sonucun tersinin, kanun metninde anılmayan diğer tüm durumlar için geçerli kabul edilmesini sağlayan yorum tekniği aşağıdakilerden hangisidir?","tooltips":{"yorum tekniği":"Kanun metinlerinin gerçek manasını ve kapsamını ortaya çıkarmak için kullanılan mantıksal yöntemlerdir."},"options":{"A":"Lafzi yorum","B":"Evleviyet yolu","C":"Aksi ile kanıt","D":"Amaçsal yorum","E":"Tarihsel yorum"},"correct_option":"C","explanations":{"A":"Yanlış. Lafzi yorum sadece sözcüklerin dil bilgisi yapısına odaklanır.","B":"Yanlış. Evleviyet çoğun içinde azın da bulunduğu kabulüne dayanır.","C":"Doğru. Kanunun belirli durumlar için getirdiği sonucun zıttının anılmayan hallere teşmil edilmesi aksi ile kanıt yöntemidir.","D":"Yanlış. Amaçsal yorum kanunun konuluş hedefini ve adalet gereksinimlerini araştırır.","E":"Yanlış. Tarihsel yorum yasa koyucunun kuralın yapıldığı andaki iradesini inceler."},"overall_explanation":"Aksi ile kanıt yöntemi, kanun koyucunun açıkça düzenlediği durumların dışındaki haller için kuralın zıttı sonucun uygulanmasını ifade eder."},{"id":"W6_Q35","domain_id":6,"domain_name":"Hafta 6: Normlar Hiyerarşisi, Hukuk Kuralları ve Yargı","question":"Çoğun içinde az da bulunur mantığına dayanan, bütün için kabul edilen bir sonucun o bütünün bir parçası veya ön adımı niteliğindeki durumlar için öncelikle ve haydi haydi geçerli olduğunu savunan yorum yöntemi aşağıdakilerden hangisidir?","tooltips":{"yorum yöntemi":"Hukuk normlarının kapsam ve etkisini belirlemede uygulanan akıl yürütme tekniğidir."},"options":{"A":"Aksi ile kanıt","B":"Lafzi yorum","C":"Gai yorum","D":"Kanunun evleviyetle uygulanması","E":"Daraltıcı yorum"},"correct_option":"D","explanations":{"A":"Yanlış. Aksi ile kanıt kuralın zıt anlamından yola çıkarak sonuca varır.","B":"Yanlış. Lafzi yorum gramer kurallarına dayalı sözel yorumdur.","C":"Yanlış. Gai yorum kuralın gayesini ve menfaat dengesini dikkate alır.","D":"Doğru. Ağır veya kapsamlı fiil için geçerli yasal sonucun, onun öncülü veya parçası olan hafif fiile öncelikle uygulanması evleviyet yorumudur.","E":"Yanlış. Daraltıcı yorum kanunun lafzının amacına göre dar uygulanmasıdır."},"overall_explanation":"Evleviyet yöntemi, çoğun içinde azın da bulunacağı kabulüyle bütünü yasaklayan veya yetkilendiren normun parçaya öncelikle uygulanmasını sağlar."}]'))},1051,a=>{a.v(JSON.parse('[{"id":"VIZE_Q1","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Yürürlük tarihine ilişkin metninde herhangi bir özel düzenleme yer almayan bir kanun, kural olarak ne zaman yürürlüğe girer?","tooltips":{"kanun":"Yasama organı tarafından anayasada belirtilen usullere uygun kabul edilen genel, soyut ve sürekli yazılı kural.","yürürlük":"Bir hukuk kuralının bağlayıcılık kazanarak hukuki uyuşmazlıklara ve olaylara fiilen uygulanabilir hâle gelmesi."},"options":{"A":"Türkiye Büyük Millet Meclisi Genel Kurulunda kabul edildiği tarihte","B":"Resmî Gazete\'de yayımlandığı günü izleyen kırk beşinci günde","C":"Resmî Gazete\'de yayımlandığı gün","D":"Cumhurbaşkanı tarafından onaylanıp meclise iade edilmediği tarihte","E":"Resmî Gazete\'de yayımlandığı ayı takip eden takvim ayının ilk gününde"},"correct_option":"C","explanations":{"A":"Yanlış. Kanunların bağlayıcılık kazanıp yürürlüğe girmesi mecliste kabul edildikleri tarihte değil, Resmî Gazete\'de yayımlanmalarıyla gerçekleşir.","B":"Yanlış. Yayımdan itibaren kırk beş gün sonra yürürlüğe girme kuralı eski mevzuatta yer alan ve yürürlükten kaldırılmış bir hükümdür.","C":"Doğru. Metninde ayrıca farklı bir yürürlük tarihi belirtilmeyen kanunlar Resmî Gazete\'de yayımlandıkları gün yürürlüğe girer.","D":"Yanlış. Cumhurbaşkanının kanunu onaylaması yayım sürecinin bir parçası olup tek başına yürürlük tarihi doğurmaz.","E":"Yanlış. Kanunların yayımını izleyen ayın başında yürürlüğe gireceğine ilişkin genel bir kanuni kural bulunmamaktadır."},"overall_explanation":"Pozitif Türk hukukunda yürürlük tarihi kanun metninde açıkça gösterilmemişse, söz konusu kanun Resmî Gazete\'de yayımlandığı gün doğrudan yürürlüğe girer. Eski mevzuatta yer alan kırk beş günlük süre kuralı mülga durumdadır."},{"id":"VIZE_Q2","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Ceza hukuku esasları çerçevesinde suç ile hukuka aykırılık kavramları arasındaki kapsam ilişkisi bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"suç":"Toplum düzenini bozan ve ceza kanunlarında hürriyeti bağlayıcı ceza veya adli para cezasına bağlanmış eylem.","hukuka aykırılık":"Hukuk düzeninin emrettiği veya yasakladığı davranış kurallarıyla çelişen fiillerin tamamını kapsayan genel nitelik."},"options":{"A":"Hukuka aykırı olan her davranış zorunlu olarak bir suç tipini meydana getirir","B":"Suç ile hukuka aykırılık birbirinden tamamen bağımsız ve kesişmeyen iki alandır","C":"Özel hukuk yaptırımı gerektiren her haksız eylem ceza kanunları kapsamında suçtur","D":"Hukuka aykırılık kavramı sadece ceza kanunlarında tanımlanan fiilleri kapsayan dar bir kavramdır","E":"Suç teşkil eden her fiil hukuka aykırıdır ancak hukuka aykırı her fiil suç niteliği taşımaz"},"correct_option":"E","explanations":{"A":"Yanlış. Hukuka aykırı her davranış suç teşkil etmez; örneğin borcun vadesinde ödenmemesi hukuka aykırıdır ancak suç değildir.","B":"Yanlış. Suç, hukuka aykırılık alanının ceza kanunlarınca yaptırıma bağlanan özel bir parçası olduğundan kavramlar iç içedir.","C":"Yanlış. Özel hukuktaki haksız fiiller veya sözleşmeye aykırılıklar tazminat yaptırımı doğurur, doğrudan suç sayılmazlar.","D":"Yanlış. Hukuka aykırılık medeni hukuk, idare hukuku ve borçlar hukuku gibi tüm alanları kapsayan geniş bir üst kavramdır.","E":"Doğru. Suç teşkil eden her fiil zorunlu olarak hukuka aykırılık barındırır; fakat hukuka aykırı olan her eylem ceza kanunlarında suç olarak tanımlanmamıştır."},"overall_explanation":"Hukuka aykırılık, hukuk düzeninin emir ve yasaklarına aykırı tüm davranışları kapsayan geniş bir çatı kavramdır. Suç ise bu geniş çerçevenin yalnızca ceza kanunlarınca hapis veya adli para cezasına bağlanmış özel bir kesitidir."},{"id":"VIZE_Q3","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Adalet kavramının tarihsel ve simgesel anlatımında benimsenen Themis heykelindeki göz bağı figürü aşağıdakilerden hangisini temsil etmektedir?","tooltips":{"tarafsızlık":"Yargılama faaliyetinde hâkimin tarafların kimliğine veya dış yönlendirmelere bakılmaksızın objektif karar vermesi ilkesi.","adalet":"Uyuşmazlıklarda hakkaniyeti sağlama, suç ve kusuru objektif tartarak herkese hakkı olanı teslim etme ideali."},"options":{"A":"Kişilerin statüsünden ve dış etkilerden bağımsız kalınarak sağlanan tarafsızlığı","B":"Hukuk kurallarının toplumun tüm fertlerine mutlak ve değişmez bir eşitlikle uygulanmasını","C":"Devlet otoritesinin sahip olduğu maddi cebrin ve yaptırımın caydırıcılığını","D":"Failin kusur derecesi ile ceza arasındaki menfaat dengesinin hassas tartımını","E":"Mahkeme kararlarının münhasıran yürürlükteki yazılı kanun metnine dayanmasını"},"correct_option":"A","explanations":{"A":"Doğru. Themis heykelindeki göz bağı, adaletin kişilerin mevkisine, unvanına ve dış baskılara bakılmaksızın tarafsızlıkla dağıtılmasını simgeler.","B":"Yanlış. Eşitlik anlayışı doğrudan göz bağı ile değil, hakkaniyet ve terazi unsurlarıyla bağlantılıdır.","C":"Yanlış. Yaptırımın gücü ve devlet cebri heykeldeki kılıç motifiyle ifade edilir.","D":"Yanlış. Kusur ve menfaat dengesinin hassas biçimde ölçülmesi terazi ile sembolize edilir.","E":"Yanlış. Kararların kanuna dayanması zorunluluğu heykelin ayakları altındaki kitap ile temsil edilir."},"overall_explanation":"Themis tasvirinde göz bağı tarafsızlığı, terazi hakkaniyet ve menfaat dengesini, kılıç yaptırım gücünü, ayaklar altındaki kitap ise keyfiliğin reddedilerek kanuna bağlılığı simgeler."},{"id":"VIZE_Q4","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Türk Borçlar Kanunu\'nda düzenlenen \'Sözleşme ile aksi kararlaştırılmadıkça veya aksine bir âdet bulunmadıkça, satıcı ve alıcı borçlarını aynı anda ifa etmekle yükümlüdürler.\' hükmü, işlevi bakımından hangi hukuk kuralı türüdür?","tooltips":{"tamamlayıcı hukuk kuralı":"Tarafların aksini kararlaştırabildiği ancak sözleşmede düzenlemedikleri boşlukları dolduran kural.","ifa":"Borçlanılan edimin alacaklıya karşı sözleşmeye ve kanuna uygun olarak bizzat yerine getirilmesi."},"options":{"A":"Emredici hukuk kuralı","B":"Tamamlayıcı hukuk kuralı","C":"Yorumlayıcı hukuk kuralı","D":"Tanımlayıcı hukuk kuralı","E":"Yetki verici hukuk kuralı"},"correct_option":"B","explanations":{"A":"Yanlış. Emredici hukuk kuralları tarafların serbest iradeleriyle aksini kararlaştıramayacağı kesin kurallardır.","B":"Doğru. Taraflarca ifa zamanı sözleşmede açıkça düzenlenmediğinde ortaya çıkan irade boşluğunu doldurduğu için tamamlayıcı hukuk kuralıdır.","C":"Yanlış. Yorumlayıcı kurallar sözleşmede mevcut olan belirsiz bir terimi açıklar; burada ise tarafların üzerinde durmadığı bir husus doldurulmaktadır.","D":"Yanlış. Tanımlayıcı kurallar bir hukuki kurumun temel unsurlarını tarif eder.","E":"Yanlış. Yetki verici kurallar taraflara veya kamu makamlarına belirli bir işlemi yapma serbestisi tanıyan kurallardır."},"overall_explanation":"TBK m. 207/2 hükmü, sözleşmede ifa zamanı kararlaştırılmadığında kendiliğinden devreye girerek tarafların irade boşluğunu doldurduğundan tamamlayıcı bir yedek hukuk kuralıdır."},{"id":"VIZE_Q5","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Jellinek tarafından geliştirilen kamu hakları tasnifinde yer alan ve kural olarak yalnızca vatandaşlar tarafından kullanılabilen hak kategorisi aşağıdakilerden hangisidir?","tooltips":{"kamu hakları":"Bireylerin devlet ile olan kamusal münasebetlerinden doğan ve kamu hukuku tarafından tanınan haklar.","aktif statü hakları":"Kişinin devlet yönetimine, siyasi organlara ve kamu gücünün kullanımına katılımını temin eden haklar."},"options":{"A":"Negatif statü hakları","B":"Koruyucu kamu hakları","C":"Pozitif statü hakları","D":"Aktif statü hakları","E":"Sosyal ve ekonomik haklar"},"correct_option":"D","explanations":{"A":"Yanlış. Negatif statü hakları devletin karışmaması gereken kişisel haklar olup kural olarak yabancılara da tanınır.","B":"Yanlış. Koruyucu kamu hakları negatif statü haklarının diğer adıdır ve münhasıran vatandaşlara özgü değildir.","C":"Yanlış. Pozitif statü hakları devletten hizmet isteme haklarıdır ve yabancılar da belirli şartlarla yararlanabilir.","D":"Doğru. Seçme ve seçilme gibi siyasal katılımı sağlayan aktif statü hakları münhasıran vatandaşlara tanınmıştır.","E":"Yanlış. Sosyal ve ekonomik haklar pozitif statü grubu içinde yer alır ve sadece vatandaşlara özgülenmemiştir."},"overall_explanation":"Jellinek tasnifinde yer alan aktif statü hakları, bireyin devlet yönetimine ve siyasal karar alma mekanizmalarına katılımını düzenler; bu haklar kural olarak yalnızca vatandaşlar tarafından kullanılabilir."},{"id":"VIZE_Q6","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Anglo-Amerikan Hukuk Sisteminde alt mahkemelerin benzer hukuki uyuşmazlıklarda geçmişte verilmiş üst mahkeme kararlarına bağlı olmasını ifade eden temel doktrin aşağıdakilerden hangisidir?","tooltips":{"Anglo-Amerikan Hukuk Sistemi":"İngiltere kökenli, yargıçların kararlarına ve geleneksel içtihatlara dayalı olarak işleyen hukuk düzeni.","emsal karar":"Geçmişte benzer bir uyuşmazlıkta verilmiş ve gelecekteki benzer davalarda bağlayıcı kabul edilen mahkeme ilamı."},"options":{"A":"Kodifikasyon ilkesi","B":"Emsal karar doktrini","C":"Mülkilik ilkesi","D":"Kanunilik prensibi","E":"İhsak-ı hak yetkisi"},"correct_option":"B","explanations":{"A":"Yanlış. Kodifikasyon, kuralların sistemli kanun kitaplarında toplanması olup Kara Avrupası sisteminin belirleyici vasfıdır.","B":"Doğru. Common Law sisteminde alt mahkemelerin geçmiş yargı kararlarıyla bağlı olması emsal karar doktrini ile ifade edilir.","C":"Yanlış. Mülkilik ilkesi kanunların devletin coğrafi sınırları içinde uygulanmasını düzenleyen ilkedir.","D":"Yanlış. Kanunilik prensibi suç ve cezaların ancak yazılı kanunla konulabileceğini belirten ceza hukuku ilkesidir.","E":"Yanlış. İhsak-ı hak, kişinin kendi hakkını kendi gücüyle almasıdır ve modern hukuk sistemlerince men edilmiştir."},"overall_explanation":"Common Law sisteminde yargıçlar tarafından geçmişte verilmiş kararlar bağlayıcı birincil kaynaktır; bu bağlayıcılık emsal karar doktrinine dayanır."},{"id":"VIZE_Q7","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"2547 sayılı Yükseköğretim Kanunu\'nun 54. maddesi uyarınca, sınavlarda kendi yerine başkasını sınava sokan veya başkasının yerine sınava giren bir öğrenciye verilecek disiplin cezası aşağıdakilerden hangisidir?","tooltips":{"disiplin cezası":"Kurum düzenini ihlal eden öğrenci veya personele mevzuatta yetkilendirilmiş organlar tarafından verilen idari yaptırım.","uzaklaştırma":"Öğrencinin belirlenen süre boyunca öğrencilik haklarından yararlanmasını, ders ve sınavlara katılımını engelleyen yaptırım."},"options":{"A":"Kınama","B":"Bir haftadan bir aya kadar uzaklaştırma","C":"Bir yarıyıl için uzaklaştırma","D":"Yükseköğretim kurumundan çıkarma","E":"İki yarıyıl için uzaklaştırma"},"correct_option":"E","explanations":{"A":"Yanlış. Kınama cezası sınav düzenini bozmak veya kopyaya teşebbüs etmek gibi daha hafif ihlallere uygulanır.","B":"Yanlış. Bir haftadan bir aya kadar uzaklaştırma huzur bozucu diğer eylemler için öngörülmüştür.","C":"Yanlış. Bir yarıyıl için uzaklaştırma fiilen kopya çekmek veya çektirmek fiilinin yaptırımıdır.","D":"Yanlış. Yükseköğretim kurumundan çıkarma örgüt faaliyeti yürütmek veya silah taşımak gibi en ağır eylemlere bağlanmıştır.","E":"Doğru. 2547 sayılı Kanun m. 54/1-ç-4 uyarınca kendi yerine başkasını sınava sokmak veya başkasının yerine sınava girmek iki yarıyıl için uzaklaştırma cezası gerektirir."},"overall_explanation":"2547 sayılı Kanun m. 54/1 uyarınca sınavlarda kopyaya teşebbüs kınama, fiilen kopya çekmek bir yarıyıl uzaklaştırma, yerine başkasını sınava sokmak veya başkasının yerine sınava girmek ise iki yarıyıl uzaklaştırma yaptırımına bağlanmıştır."},{"id":"VIZE_Q8","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Ceza muhakemesinde suç şüphesi altındaki kişi hakkında savcılıkça düzenlenen iddianamenin mahkeme tarafından kabul edilmesiyle birlikte başlayan evre ve bu evredeki kişinin sıfatı aşağıdakilerden hangisinde doğru verilmiştir?","tooltips":{"soruşturma":"Suç şüphesinin öğrenilmesinden iddianamenin mahkemece kabulüne kadar geçen hazırlık ve delil toplama süreci.","kovuşturma":"İddianamenin kabulüyle başlayıp mahkeme hükmünün kesinleşmesine kadar devam eden yargılama evresi."},"options":{"A":"Soruşturma evresi ve şüpheli","B":"Soruşturma evresi ve sanık","C":"Kovuşturma evresi ve sanık","D":"Kovuşturma evresi ve hükümlü","E":"İnfaz evresi ve hükümlü"},"correct_option":"C","explanations":{"A":"Yanlış. İddianamenin kabulü soruşturma evresini sona erdirir.","B":"Yanlış. Soruşturma evresinde bulunan kişi sanık değil şüpheli sıfatını taşır.","C":"Doğru. İddianamenin kabulüyle soruşturma biter, kovuşturma evresi başlar ve kişi sanık sıfatını alır.","D":"Yanlış. Hükümlü sıfatı kovuşturma neticesinde mahkûmiyet kararının kesinleşmesiyle kazanılır.","E":"Yanlış. İnfaz evresi cezanın kesinleşmesinden sonra ceza infaz kurumunda çektirilmesi sürecidir."},"overall_explanation":"İddianamenin mahkemece kabulü temel usuli eşiktir; bu kabul ile soruşturma evresi sona erip kovuşturma evresi başlar ve birey şüpheli sıfatından sanık sıfatına geçer."},{"id":"VIZE_Q9","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Temel hak ve hürriyetlere getirilen kamusal sınırlamaların anayasaya uygunluğunu denetleyen ölçülülük ilkesinin üç zorunlu alt unsuru aşağıdakilerden hangisinde eksiksiz verilmiştir?","tooltips":{"ölçülülük ilkesi":"Temel haklara getirilen sınırlamada kamu yararı amacı ile müdahale aracı arasındaki dengenin gözetilmesi şartı.","elverişlilik":"Sınırlama için seçilen aracın ulaşılmak istenen meşru amacı gerçekleştirmeye uygun bulunması."},"options":{"A":"Elverişlilik, gereklilik ve orantılılık","B":"Kanunilik, süreklilik ve nesnellik","C":"Mülkilik, şahsilik ve geriye yürümezlik","D":"Eşitlik, adalet ve hakkaniyet","E":"Aleniyet, tarafsızlık ve isnat yeteneği"},"correct_option":"A","explanations":{"A":"Doğru. Ölçülülük ilkesi elverişlilik, gereklilik ve orantılılık olmak üzere üç kümülatif alt ilkeden teşekkül eder.","B":"Yanlış. Kanunilik ve süreklilik hukuk normlarının genel nitelikleridir, ölçülülüğün alt unsurları değildir.","C":"Yanlış. Mülkilik ve şahsilik hukukun yer ve kişi bakımından uygulanmasına dair ilkelerdir.","D":"Yanlış. Eşitlik ve adalet hukukun genel etik gayeleridir.","E":"Yanlış. Aleniyet ve tarafsızlık yargılama hukukuna ilişkin anayasal prensiplerdir."},"overall_explanation":"Temel hakların sınırlanmasında ölçülülük denetimi; aracın amaca uygunluğunu ifade eden elverişlilik, en hafif tedbirin seçilmesini dikte eden gereklilik ve menfaat dengesini gözeten orantılılık unsurlarını arar."},{"id":"VIZE_Q10","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Türk Medeni Kanunu\'nun 1. maddesi kapsamında yazılı hukukta ve örf-âdet hukukunda hüküm bulunmaması durumunda hâkimin hukuk yaratması yetkisine ilişkin aşağıdaki ifadelerden hangisi doğrudur?","tooltips":{"hukuk yaratması":"Hukuk boşluğu durumunda hâkimin kanun koyucu gibi hareket ederek somut olaya uygulanacak kuralı üretmesi.","hukuk boşluğu":"Yazılı normlarda ve örf-âdet hukukunda somut meseleyi çözecek pozitif hiçbir kuralın bulunmaması durumu."},"options":{"A":"Hâkimin yarattığı kural yasama organının kanunu gibi genel ve soyut nitelikte olup herkesi bağlar","B":"Hâkim uyuşmazlığı çözerken anayasal ilkelerle bağlı olmaksızın dilediği kuralı oluşturabilir","C":"Hâkimin yarattığı hüküm istinaf veya temyiz denetimine tabi tutulmaksızın kesin hüküm doğurur","D":"Hâkimin oluşturduğu kural genel bir norm teşkil etmeyip yalnızca bakılmakta olan davanın taraflarını bağlar","E":"Hâkimin hukuk yaratma yetkisi ceza hukuku alanındaki suç ve cezaların belirlenmesinde de aynen geçerlidir"},"correct_option":"D","explanations":{"A":"Yanlış. Hâkimin hukuk yaratarak oluşturduğu kural bir kanun metni değildir, genel ve soyut bağlayıcılık taşımaz.","B":"Yanlış. Hâkim hukuk yaratırken hukuk düzeninin genel ilkelerine ve anayasal değerlere uygun hareket etmek mecburiyetindedir.","C":"Yanlış. Hâkimin hukuk yaratarak verdiği kararlar istinaf ve temyiz gibi üst mahkeme denetimlerine tabidir.","D":"Doğru. Hâkimin yarattığı kural genel bir kanun niteliği kazanmaz, yalnızca eldeki davanın tarafları açısından bağlayıcıdır.","E":"Yanlış. Ceza hukukunda kanunilik ilkesi hâkim olduğundan kıyas yoluyla veya hâkimin hukuk yaratmasıyla suç ve ceza ihdas edilemez."},"overall_explanation":"Hâkimin hukuk yaratması faaliyeti genel bir yasama yetkisi değildir; üretilen kural yalnızca bakılmakta olan somut uyuşmazlığın tarafları açısından bağlayıcı bir mahkeme kararı niteliğindedir."},{"id":"VIZE_Q11","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Toplumsal yaşamı tanzim eden ahlak, din ve görgü kuralları ile hukuk kuralları karşılaştırıldığında, hukuk kurallarını diğer tüm kurallardan ayıran temel unsur aşağıdakilerden hangisidir?","tooltips":{"maddi yaptırım":"Hukuk kuralına aykırılık hâlinde kamu gücü tarafından uygulanan hapis, para cezası, tazminat veya cebri icra tedbirleri.","görgü kuralları":"Topluluk içinde nezaket ve saygı gereği benimsenen, ihlali manevi tepkiyle karşılanan yazısız davranış modelleri."},"options":{"A":"Bireylerin vicdani huzurunu ve iç muhakemesini hedeflemesi","B":"Toplumda kendiliğinden doğarak asırlar boyunca süreklilik kazanması","C":"İhlali hâlinde kişiyi toplumdan soyutlama ve ayıplama tepkisi doğurması","D":"Emir ve yasaklar ihtiva ederek insan davranışlarını sınırlaması","E":"Devlet erki marifetiyle uygulanan maddi bir cebir ve yaptırıma dayanması"},"correct_option":"E","explanations":{"A":"Yanlış. Bireyin iç dünyası ve vicdani muhakemesi ahlak kurallarının konusunu oluşturur.","B":"Yanlış. Kendiliğinden doğup süreklilik kazanma örf ve âdetlerde de mevcuttur.","C":"Yanlış. Ayıplama ve dışlama görgü ve ahlak kurallarının manevi yaptırımlarıdır.","D":"Yanlış. Din ve ahlak kuralları da insan davranışlarını sınırlayan emir ve yasaklar ihtiva eder.","E":"Doğru. Hukuk kurallarını diğer kurallardan ayıran ayırıcı nitelik, devlet gücüyle desteklenen maddi cebir ve yaptırıma sahip olmasıdır."},"overall_explanation":"Din, ahlak ve görgü kurallarının yaptırımları manevi veya uhrevi nitelikteyken; hukuk kuralları kamu otoritesi marifetiyle yürütülen maddi yaptırıma bağlanmıştır."},{"id":"VIZE_Q12","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Türk Medeni Kanunu\'nun 1. maddesine göre, önüne gelen özel hukuk uyuşmazlığında yazılı hukuk metinlerinde uygulanabilir bir hüküm bulunmadığını tespit eden hâkimin başvurması gereken asli kaynak aşağıdakilerden hangisidir?","tooltips":{"Türk Medeni Kanunu":"Kişiler hukuku, aile hukuku, eşya hukuku ve miras hukuku ilişkilerini tanzim eden temel özel hukuk kanunu.","örf ve âdet hukuku":"Toplumda yerleşmiş, uyulması zorunlu kabul edilen ve devletin yaptırımıyla desteklenen yazılı olmayan bağlayıcı hukuk kaynağı."},"options":{"A":"Hukuk doktrinindeki bilimsel görüşler","B":"Örf ve âdet hukuku","C":"Yargıtay dairelerinin emsal yargı kararları","D":"Hâkimin bizzat kanun koyucu gibi hukuk yaratması","E":"Bölge Adliye Mahkemesi istinaf kararları"},"correct_option":"B","explanations":{"A":"Yanlış. Bilimsel görüşler hâkimin karar verirken faydalandığı bağlayıcı olmayan yardımcı kaynaktır.","B":"Doğru. TMK m. 1 uyarınca yazılı kaynakta hüküm bulunmadığında hâkim öncelikle örf ve âdet hukukuna başvurmak zorundadır.","C":"Yanlış. Emsal yargı kararları yardımcı kaynak niteliğindedir.","D":"Yanlış. Hâkim hukuk yaratma yetkisine ancak örf ve âdet hukukunda da bir kural bulunmadığı takdirde başvurabilir.","E":"Yanlış. İstinaf kararları yalnızca davanın taraflarını bağlayan münferit yargısal kararlardır."},"overall_explanation":"TMK m. 1\'de öngörülen sıralama gereğince hâkim uyuşmazlıkta önce yazılı kaynakları inceler; yazılı hüküm bulunmaması durumunda kanun boşluğu doğar ve hâkim örf ve âdet hukukunu uygular."},{"id":"VIZE_Q13","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Ceza hukukunda geçerli olan kanunilik ilkesinin zorunlu bir sonucu olarak aşağıdakilerden hangisi hukuken kesinlikle yasaktır?","tooltips":{"kanunilik ilkesi":"Kanunsuz suç ve ceza olmaz prensibi uyarınca ceza ve tedbirlerin münhasıran yasama organının kanununa dayanması zorunluluğu.","isnat yeteneği":"Kişinin işlediği fiilin hukuki anlam ve sonuçlarını algılama ve davranışlarını yönlendirme yeteneği."},"options":{"A":"Ceza kanunu hükümlerinin yürürlüğe girdiği andan itibaren ileriye etkili uygulanması","B":"Suçların ve yaptırımların Türkiye Büyük Millet Meclisi tarafından kanunla belirlenmesi","C":"Suç şüphesi altındaki kişinin kesinleşmiş mahkeme hükmüne kadar masum sayılması","D":"Örf ve âdet kurallarına dayanılarak yeni bir suç veya ceza ihdas edilmesi","E":"Akıl hastalığı sebebiyle isnat yeteneği bulunmayan kişiye güvenlik tedbiri verilmesi"},"correct_option":"D","explanations":{"A":"Yanlış. Kanunların ileriye etkili uygulanması kanunilik ilkesi ve hukuki güvenliğin doğal sonucudur.","B":"Yanlış. Suç ve cezaların meclis tarafından kanunla tanzimi kanunilik ilkesinin temel şartıdır.","C":"Yanlış. Bireyin kesin hükme dek suçsuz sayılması masumiyet karinesinin gereğidir.","D":"Doğru. Kanunilik ilkesi gereğince örf ve âdete dayanılarak suç yaratılamaz, ceza veya güvenlik tedbiri konulamaz.","E":"Yanlış. İsnat yeteneği olmayana ceza yerine tedbir uygulanması kusur prensibinin bir sonucudur."},"overall_explanation":"Ceza hukukundaki kanunilik ilkesi gereğince suçlar ve cezalar yalnızca yazılı kanunla ihdas edilebilir; örf ve âdet kurallarıyla suç ya da ceza yaratılması kesin olarak yasaklanmıştır."},{"id":"VIZE_Q14","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Özel hakların niteliklerine göre yapılan sınıflandırmasında mutlak hakları nispi haklardan ayıran temel özellik aşağıdakilerden hangisidir?","tooltips":{"mutlak hak":"Sahibine eşya veya şahıslar üzerinde geniş yetkiler veren ve toplumdaki herkese karşı ileri sürülebilen hak.","nispi hak":"Yalnızca aralarında hukuki münasebet bulunan belirli kişi veya kişilere karşı ileri sürülebilen hak."},"options":{"A":"Mutlak hakların herkese karşı ileri sürülebilmesi ve herkes tarafından ihlal edilebilmesi","B":"Mutlak hakların yalnızca belirli bir borç ilişkisinin karşı tarafına karşı ileri sürülebilmesi","C":"Mutlak hakların münhasıran para ile ölçülebilir malvarlığı değerlerinden oluşması","D":"Mutlak hakların tek taraflı irade beyanı ile mevcut hukuki ilişkiyi değiştirebilmesi","E":"Mutlak hakların kullanılmasının mutlaka mahkeme kararı ile hükme bağlanması zorunluluğu"},"correct_option":"A","explanations":{"A":"Doğru. Mutlak haklar herkese karşı ileri sürülebilen, herkesin ihlalinden kaçınmakla yükümlü olduğu haklardır.","B":"Yanlış. Sadece belirli bir hukuki ilişkinin muhatabına karşı ileri sürülebilen haklar nispi haklardır.","C":"Yanlış. Mutlak haklar şeref, haysiyet ve yaşam hakkı gibi ekonomik değeri olmayan manevi kişilik haklarını da kapsar.","D":"Yanlış. Tek taraflı irade beyanıyla yeni hukuki durum yaratan veya mevcut durumu değiştiren haklar yenilik doğuran haklardır.","E":"Yanlış. Mutlak hakların kullanımı kural olarak mahkeme hükmüne tabi değildir; hak sahibi hakkını doğrudan kullanabilir."},"overall_explanation":"Mutlak haklar sahibine en geniş yetkileri bahşeden, herkese karşı ileri sürülebilen ve herkesçe ihlali mümkün olan haklardır. Nispi haklar ise sadece belirli borç ilişkisinin muhatabına karşı ileri sürülebilir."},{"id":"VIZE_Q15","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Türk hukukunun da dâhil olduğu Kara Avrupası Hukuk Sisteminin tarihsel kökeni ve sistemik omurgası bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"Kara Avrupası Hukuk Sistemi":"Roma hukukuna dayanan, yazılı kuralların ve kamu-özel hukuk ikili ayrımının esas alındığı hukuk düzeni.","kamu hukuku":"Devletin egemenlik yetkisini kullanarak taraf olduğu ve kamu yararının üstün tutulduğu hukuk kuralları bütünü."},"options":{"A":"İngiltere\'deki gezici yargıçların içtihatlarına dayanır ve yazısız hukuk esastır","B":"Yargıçlar meclislerin çıkardığı soyut kanunlara değil geçmiş mahkeme kararlarına bağlıdır","C":"Roma Hukukuna dayanır ve sistemin temel omurgasını kamu hukuku ile özel hukuk ayrımı kurar","D":"Bireysel mülkiyet reddedilerek üretim araçları tamamen kamu mülkiyetine tahsis edilmiştir","E":"Her somut davada alt mahkemelerin selefi olan yargıçların kararlarını uygulama zorunluluğu vardır"},"correct_option":"C","explanations":{"A":"Yanlış. Gezici krallık yargıçlarının içtihatlarına dayanan sistem Common Law sistemidir.","B":"Yanlış. Geçmiş mahkeme kararlarının birincil kaynak sayılması Anglo-Amerikan hukukuna özgüdür.","C":"Doğru. Kara Avrupası sistemi Roma Hukukuna dayanır ve temel sistemik yapısını kamu hukuku ile özel hukuk ayrımı oluşturur.","D":"Yanlış. Bireysel mülkiyetin reddi ve üretim araçlarının devlet mülkiyetine geçmesi Sosyalist Hukuk Sisteminin vasfıdır.","E":"Yanlış. Geçmiş yargıç kararlarının bağlayıcılığı emsal karar doktrinine dayanan Anglo-Sakson sistemine aittir."},"overall_explanation":"Kara Avrupası Hukuk Sistemi, temelleri Roma Hukukuna uzanan, kodifiye edilmiş yazılı mevzuata dayanan ve kamu hukuku ile özel hukuk ayrımını ana eksen kabul eden hukuk sistemidir."},{"id":"VIZE_Q16","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Anayasa hükümleri çerçevesinde olağan Cumhurbaşkanlığı Kararnamelerinin sınırları dikkate alındığında, bu kararnamelerle aşağıdakilerden hangisi hukuken düzenlenemez?","tooltips":{"Olağan Cumhurbaşkanlığı Kararnamesi":"Anayasa\'nın yürütme yetkisine bıraktığı konularda kanunlara aykırı olmamak üzere çıkarılan düzenleyici norm.","kişi hakları":"Anayasa\'da güvenceye bağlanan ve bireyin maddi ve manevi varlığını devlete karşı koruyan temel haklar."},"options":{"A":"Bakanlıkların merkez ve taşra teşkilat yapılarının kurulması","B":"Kamu tüzel kişiliğine haiz idari birimlerin teşkilatlanması","C":"Üst kademe kamu yöneticilerinin atanma usul ve şartları","D":"Cumhurbaşkanlığına bağlı başkanlık ve ofislerin idari görevleri","E":"Kişi hakları ve ödevleri, siyasi haklar ile suç ve ceza ihdası"},"correct_option":"E","explanations":{"A":"Yanlış. Bakanlıkların teşkilat yapısı Anayasa gereği doğrudan CBK ile düzenlenebilen yürütme alanlarındandır.","B":"Yanlış. İdarenin teşkilatlanmasına ilişkin düzenlemeler CBK ile yapılabilir.","C":"Yanlış. Üst kademe kamu yöneticilerinin atanma usulleri CBK\'nın meşru düzenleme sahasındadır.","D":"Yanlış. Cumhurbaşkanlığı bünyesindeki ofislerin görev tanımları CBK ile tanzim edilir.","E":"Doğru. Olağan CBK\'lar ile Anayasa\'da düzenlenen temel kişi hakları, siyasi haklar ile suç ve ceza ihdası alanlarında düzenleme yapılamaz."},"overall_explanation":"Anayasa uyarınca olağan Cumhurbaşkanlığı Kararnameleri ile temel haklar, kişi hakları ve ödevleri ile siyasi haklar düzenlenemez; ayrıca kanunda açıkça düzenlenen veya münhasıran kanunla düzenlenmesi öngörülen alanlarda CBK çıkarılamaz."},{"id":"VIZE_Q17","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Hak sahibinin tek taraflı irade beyanıyla mevcut bir hukuki ilişkiyi tamamen ortadan kaldıran hak türü ve buna ilişkin somut örnek aşağıdakilerden hangisinde doğru verilmiştir?","tooltips":{"bozucu yenilik doğuran hak":"Tek taraflı irade beyanı ile karşı tarafın rızası aranmaksızın mevcut hukuki münasebeti sonlandıran hak.","fesih":"Sürekli bir borç ilişkisini ileriye etkili olarak sona erdiren tek taraflı irade beyanı."},"options":{"A":"Kurucu yenilik doğuran hak olup alım opsiyonunun kullanılması","B":"Bozucu yenilik doğuran hak olup iş sözleşmesinin haklı nedenle feshedilmesi","C":"Değiştirici yenilik doğuran hak olup ayıplı eşyada bedel indirimi talep edilmesi","D":"Alelade hak olup kiracının kiralanan konutta oturmayı sürdürmesi","E":"Nispi hak olup vadesi gelmiş borcun alacaklı tarafından talep edilmesi"},"correct_option":"B","explanations":{"A":"Yanlış. Alım hakkının kullanılması yeni bir mülkiyet devri borcu doğurduğundan kurucu yenilik doğuran haktır.","B":"Doğru. Sözleşmenin feshi mevcut hukuki bağı tek taraflı iradeyle tamamen sona erdirdiğinden bozucu yenilik doğuran haktır.","C":"Yanlış. Bedel indirimi talebi sözleşmeyi ortadan kaldırmayıp şartlarını değiştirdiğinden değiştirici haktır.","D":"Yanlış. Kiracının konutta oturması var olan hakkın kullanılmasıdır ve yenilik doğurmayan alelade haktır.","E":"Yanlış. Borcun talep edilmesi bir nispi alacak hakkının olağan ileri sürülüşüdür."},"overall_explanation":"Bozucu yenilik doğuran haklar, hak sahibinin tek taraflı irade beyanıyla hüküm doğurarak mevcut bir hukuki durumu tamamen sona erdiren haklardır; iş sözleşmesinin veya kira akdinin feshi buna örnektir."},{"id":"VIZE_Q18","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"2547 sayılı Yükseköğretim Kanunu\'nun 54. maddesi uyarınca, yükseköğretim kurumlarında yapılan sınavlarda kopyaya teşebbüs eden bir öğrenci hakkında uygulanacak disiplin cezası aşağıdakilerden hangisidir?","tooltips":{"kopyaya teşebbüs":"Sınavda kurallara aykırı menfaat temin etmek amacıyla hazırlık hareketlerine girişip eylemi tamamlayamama hâli.","kınama":"Öğrenciye öğrencilikle ilgili kusurlu davranışlarından dolayı kınandığının resmi yazı ile bildirilmesi cezası."},"options":{"A":"Kınama","B":"Uyarma","C":"Bir haftadan bir aya kadar uzaklaştırma","D":"Bir yarıyıl için uzaklaştırma","E":"İki yarıyıl için uzaklaştırma"},"correct_option":"A","explanations":{"A":"Doğru. 2547 sayılı Kanun m. 54/1-a-5 hükmü uyarınca sınavlarda kopyaya teşebbüs etmek kınama cezasını gerektirir.","B":"Yanlış. 2547 sayılı Kanun\'un 54. maddesindeki öğrenci disiplin suç ve cezaları arasında kopyaya teşebbüs için uyarma cezası yer almaz.","C":"Yanlış. Bir haftadan bir aya kadar uzaklaştırma huzur bozucu fiiller ve soruşturmayı engelleme eylemleri için öngörülmüştür.","D":"Yanlış. Bir yarıyıl için uzaklaştırma fiilen kopya çekmek veya çektirmek fiilinin karşılığıdır.","E":"Yanlış. İki yarıyıl için uzaklaştırma tehditle kopya çekmek veya yerine başkasını sınava sokmak fiillerine verilir."},"overall_explanation":"2547 sayılı Yükseköğretim Kanunu m. 54/1-a-5 hükmü gereğince sınavlarda kopyaya teşebbüs etmek açıkça kınama cezası yaptırımına bağlanmıştır."},{"id":"VIZE_Q19","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Pozitif hukukta hak süjesi olma niteliği ve hak-ödev dengesi dikkate alındığında hayvanların hukuki statüsüne ilişkin aşağıdaki ifadelerden hangisi doğrudur?","tooltips":{"hak süjesi":"Hukuk düzeninde hakların ve borçların sahibi olabilen varlık.","ödev":"Hukuk düzeninin belirli bir davranışı yapma ya da yapmama yönünde kişiye yüklediği mükellefiyet."},"options":{"A":"Hayvanlar doğrudan hak süjesi olup kendi adlarına dava açma yetkisini haizdir","B":"Hayvanlar ile insanlar arasında borçlandırıcı hukuki sözleşmeler kurulabilir","C":"Hayvanlar hukuk düzeninde dernek ve vakıflar gibi tüzel kişilik sıfatı taşır","D":"Hayvanlar hak süjesi olmayıp insanların kanunen koruma ve eziyet etmeme ödevinin nesnesidir","E":"Hayvanların hukuki statüsü gerçek kişilerin tam fiil ehliyeti ile eşdeğerdir"},"correct_option":"D","explanations":{"A":"Yanlış. Hayvanlar hukuk düzeninde bağımsız hak süjesi kabul edilmez ve dava ehliyetleri bulunmaz.","B":"Yanlış. Hayvanların hukuki muamele yapma iradeleri hukuken tanınmadığından sözleşme tarafı olamazlar.","C":"Yanlış. Hayvanlar kişi veya sermaye topluluğu niteliği taşımadıklarından tüzel kişilik kazanamazlar.","D":"Doğru. Hayvanlar subjektif hak sahibi bir süje değildir; ancak insanların kanunen uymak zorunda olduğu koruma ve eziyet etmeme ödevinin nesnesidirler.","E":"Yanlış. Hayvanların fiil ehliyeti veya hak ehliyeti bulunmamaktadır."},"overall_explanation":"Pozitif hukukta yalnızca gerçek kişiler ve tüzel kişiler hak süjesidir. Hayvanlar hak süjesi olmayıp eşya statüsünde değerlendirilmekte, buna karşılık insanlar için kanuni koruma ödevinin nesnesini oluşturmaktadır."},{"id":"VIZE_Q20","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Maddi hukukun kişilere tanıdığı özel hakların mahkemeler önünde nasıl talep edileceğini, dilekçelerin verilmesini, yargılama sürelerini ve delillerin ikame usulünü düzenleyen şekli hukuk disiplini aşağıdakilerden hangisidir?","tooltips":{"usul hukuku":"Bir hakkın mahkemede hangi yargılama prosedürüyle savunulup karara bağlanacağını düzenleyen şekli kurallar bütünü.","delil":"Davada ileri sürülen iddiaların doğruluğunu ispatlamaya yarayan hukuki araç."},"options":{"A":"Maddi Ceza Hukuku","B":"İcra ve İflas Hukuku","C":"Medeni Usul Hukuku","D":"Borçlar Hukuku Genel Hükümler","E":"Milletlerarası Özel Hukuk"},"correct_option":"C","explanations":{"A":"Yanlış. Maddi Ceza Hukuku suç teşkil eden eylemleri ve yaptırımlarını belirleyen daldır.","B":"Yanlış. İcra ve İflas Hukuku mahkemece hüküm altına alınan hakların cebri icra yoluyla tahsilini tanzim eder.","C":"Doğru. Özel hukuktaki uyuşmazlıkların mahkemeler huzurundaki yargılama usullerini şekli kurallarla belirleyen dal Medeni Usul Hukukudur.","D":"Yanlış. Borçlar Hukuku alacak ve borç ilişkilerinin doğumu ve hükümlerini belirleyen bir maddi hukuk dalıdır.","E":"Yanlış. Milletlerarası Özel Hukuk yabancılık unsuru taşıyan davalarda yetkili hukuku belirleyen bağlama kurallarını inceler."},"overall_explanation":"Maddi hukukun hak sahiplerine tanıdığı yetkilerin mahkemelerde dava yoluyla ileri sürülme biçimini, dilekçelerin teatisi ve delil kurallarını tanzim eden şekli karma hukuk disiplini Medeni Usul Hukukudur."},{"id":"VIZE_Q21","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Türkiye Cumhuriyeti Anayasası\'nın 90. maddesi uyarınca, usulüne göre yürürlüğe konulmuş temel hak ve özgürlüklere ilişkin milletlerarası andlaşmalar ile kanunların aynı konuda farklı hükümler içermesi hâlinde ortaya çıkan çatışma nasıl giderilir?","tooltips":{"milletlerarası andlaşma":"Devletler arasında karşılıklı hak ve borç doğuran, usulünce onaylanarak bağlayıcılık kazanan metin.","normlar hiyerarşisi":"Hukuk kurallarının altlık-üstlük ilişkisini gösteren ve alt normun üst norma aykırı olamayacağını belirten piramit."},"options":{"A":"Normlar hiyerarşisinde kanun üstte yer aldığından münhasıran kanun hükümleri tatbik edilir","B":"Çatışan hükümlerden yürürlük tarihi daha yeni olan düzenlemeye öncelik tanınır","C":"Uyuşmazlık çözümü amacıyla öncelikle Anayasa Mahkemesine somut norm denetimi başvurusu yapılır","D":"Hâkim kanun boşluğu oluştuğunu kabul ederek meseleyi örf ve âdet hukukuna göre çözer","E":"Milletlerarası andlaşma ile kanun farklı hükümler içerdiğinde andlaşma hükümleri esas alınır"},"correct_option":"E","explanations":{"A":"Yanlış. Anayasa m. 90 son fıkrası temel hak ve özgürlüklere ilişkin andlaşmalara açıkça öncelik tanımıştır.","B":"Yanlış. Kronolojik tarih kuralı değil, doğrudan temel haklara ilişkin andlaşmaya üstünlük tanıma kuralı tatbik edilir.","C":"Yanlış. Usulüne göre yürürlüğe konulmuş andlaşmalar hakkında Anayasa Mahkemesine aykırılık iddiasıyla başvurulamaz.","D":"Yanlış. Ortada çatışan iki pozitif norm mevcut olduğundan kanun boşluğundan söz edilemez.","E":"Doğru. Anayasa m. 90 son fıkrası gereğince temel hak ve özgürlüklere ilişkin andlaşmalarla kanunlar çeliştiğinde milletlerarası andlaşma hükümleri esas alınır."},"overall_explanation":"Anayasa m. 90 son fıkrası uyarınca, usulüne uygun yürürlüğe konulmuş temel hak ve özgürlüklere ilişkin milletlerarası andlaşmalar ile kanunların aynı konuda farklı hüküm içermesi hâlinde andlaşma hükümleri uygulanır."},{"id":"VIZE_Q22","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Eşya hukukunda yerel âdetlere göre asıl şeyin temel unsuru olan, o şey yok edilmedikçe, zarara uğratılmadıkça veya yapısı değiştirilmedikçe ondan ayrılması mümkün bulunmayan ve asıl şeyin mülkiyetine tabi olan unsura ne ad verilir?","tooltips":{"mütemmim cüz":"Asıl şeyin ayrılmaz parçası olup bağımsız mülkiyete konu edilemeyen ve asıl şeyin kaderini paylaşan parça.","eklenti":"Asıl şeyin mâliki tarafından o şeyin kullanılmasına tahsis edilen ancak ondan bağımsız niteliğini koruyan eşya."},"options":{"A":"Mütemmim cüz","B":"Eklenti","C":"Semere","D":"Taşınır eşya","E":"Misli eşya"},"correct_option":"A","explanations":{"A":"Doğru. Asıl şeyden ayrılması hasar, yok olma veya nitelik değişimi doğuran unsurlar mütemmim cüzdür ve asıl şeyin kaderine tabidir.","B":"Yanlış. Eklenti ayrıldığında her iki eşya da niteliğini korur; eklenti bağımsız bir eşya vasfını sürdürür.","C":"Yanlış. Semere bir şeyin dönemsel olarak verdiği doğal veya hukuki ürünlerdir.","D":"Yanlış. Taşınır eşya özüne zarar gelmeksizin bir yerden başka yere taşınabilen eşyalardır.","E":"Yanlış. Misli eşya piyasada adet, ağırlık veya ölçüyle belirlenebilen eşyalardır."},"overall_explanation":"Mütemmim cüz (ayrılmaz parça), asıl şey yok edilmedikçe veya yapısı bozulmadıkça ondan ayrılamayan ve hukuken asıl şeyin akıbetini paylaşan unsurdur."},{"id":"VIZE_Q23","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Bir hakkın ihlali durumunda, hak sahibinin bizzat kuvvet veya cebir kullanarak hakkını elde etmesinin yasaklanması ve hakkın münhasıran yargı ve icra organları eliyle talep edilmesi mecburiyetini ifade eden ilke aşağıdakilerden hangisidir?","tooltips":{"ihsak-ı hak yasağı":"Kişilerin kendi haklarını kendi güçleriyle zorla almaya kalkışmalarının kamu düzeni amacıyla yasaklanması.","cebri icra":"Mahkeme ilamlarının veya para alacaklarının devlet gücüyle borçlunun malvarlığından tahsil edilmesi usulü."},"options":{"A":"Masumiyet karinesi","B":"İhsak-ı hak yasağı","C":"Kanunilik ilkesi","D":"Kusursuz ceza olmaz kuralı","E":"Nispi eşitlik ilkesi"},"correct_option":"B","explanations":{"A":"Yanlış. Masumiyet karinesi kesinleşmiş mahkeme hükmüne kadar bireyin suçsuz sayılmasını teminat altına alır.","B":"Doğru. Bireyin hakkını bizzat güç kullanarak almasının men edilip devlet mekanizmalarına başvurmasının zorunlu tutulması ihsak-ı hak yasağıdır.","C":"Yanlış. Kanunilik ilkesi suç ve cezaların kanunla konulmasını ifade eder.","D":"Yanlış. Kusursuz ceza olmaz kuralı ceza sorumluluğunun ancak kusurlu bir iradeyle doğabileceğini belirtir.","E":"Yanlış. Nispi eşitlik ilkesi aynı hukuki durumdakilere aynı kuralların uygulanması prensibidir."},"overall_explanation":"Hukuk düzeninde kamu barışını sağlamak amacıyla ihsak-ı hak yasaklanmış; bir hakkın yerine getirilmesi yetkisi bizzat hak sahibinden alınarak devletin yargı ve icra organlarına bırakılmıştır."},{"id":"VIZE_Q24","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Kanun koyucunun belirli bir duruma özel olarak bağladığı hukuki sonucun zıttının, kanun metninde açıkça sayılmayan diğer bütün durumlar için geçerli sayılmasına dayanan mantıksal yorum tekniği aşağıdakilerden hangisidir?","tooltips":{"sistematik yorum":"Hukuk kuralının ait olduğu kanunun genel mimarisi ve ilkeleriyle bağlantı kurularak anlamlandırılması tekniği.","aksi ile kanıt":"Kanun metninde sınırlı olarak sayılan durumların zıttı sonucun sayılmayan durumlara teşmil edilmesi usulü."},"options":{"A":"Lafzi yorum","B":"Amaçsal yorum","C":"Aksi ile kanıt","D":"Evleviyet yolu","E":"Tarihsel yorum"},"correct_option":"C","explanations":{"A":"Yanlış. Lafzi yorum kanun sözcüklerinin gramer yapısına ve doğrudan anlamına odaklanan sözel yöntemdir.","B":"Yanlış. Amaçsal yorum kanunun konuluş hedefini ve tarafların menfaat dengesini esas alır.","C":"Doğru. Kanunun belirli durumlar için öngördüğü sonucun zıttının diğer durumlar için geçerli sayılması aksi ile kanıt tekniğidir.","D":"Yanlış. Evleviyet yolu çoğun içinde azın da bulunduğu mantığıyla bütüne uygulanan kuralın öncelikle parçaya uygulanmasıdır.","E":"Yanlış. Tarihsel yorum kanun yapılırken yasama organının taşıdığı tarihsel iradeyi araştırmaktır."},"overall_explanation":"Sistematik yorum araçlarından aksi ile kanıt (zıt kanıt), kanunda tahdidi olarak sayılan durumlar dışındakilere kanundaki sonucun tam tersi bir yasal sonucun bağlanmasını ifade eder."},{"id":"VIZE_Q25","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Tüzel kişiler kişi toplulukları ve mal toplulukları olarak iki ana gruba ayrılmaktadır. Buna göre aşağıdakilerden hangisi kişi topluluğu niteliğindeki bir özel hukuk tüzel kişisidir?","tooltips":{"tüzel kişi":"Belli bir amacı gerçekleştirmek üzere bağımsız bir hukuki kişilik kazanan kişi veya mal topluluğu.","dernek":"Kazanç paylaşma amacı gütmeksizin belirli ve ortak bir gayeyi gerçekleştirmek üzere kurulan kişi topluluğu."},"options":{"A":"Vakıf","B":"Devlet üniversitesi","C":"Belediye iktisadi teşekkülü","D":"Dernek","E":"Tasarruf Mevduatı Sigorta Fonu"},"correct_option":"D","explanations":{"A":"Yanlış. Vakıf belirli bir amaca tahsis edilmiş bağımsız mal varlığından oluşan mal topluluğudur.","B":"Yanlış. Devlet üniversitesi kamu tüzel kişiliğine haiz kamusal bir hizmet kuruluşudur.","C":"Yanlış. İktisadi teşekküller kamu sermayesiyle kurulan mal varlığı ağırlıklı yapılardır.","D":"Doğru. Dernek en az yedi gerçek veya tüzel kişinin kazanç paylaşma amacı gütmeksizin kurduğu tipik bir kişi topluluğudur.","E":"Yanlış. Fon, kamu hukuku çerçevesinde belli bir malvarlığının yönetimi için kurulan mal topluluğudur."},"overall_explanation":"Dernekler, üyelerinin ortak bir gayeyi gerçekleştirmek üzere güç ve faaliyetlerini birleştirdikleri kişi topluluklarıdır; vakıflar ise belirli bir amaca tahsis edilen mal topluluklarıdır."},{"id":"VIZE_Q26","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Hukuk sisteminin temel ayrımında tarafların eşitliği ve irade özerkliği ilkelerine dayanan özel hukukun alt dallarından biri aşağıdakilerden hangisidir?","tooltips":{"özel hukuk":"Eşit statüdeki süjelerin kendi aralarında irade serbestisiyle kurdukları hukuki münasebetleri düzenleyen alan.","Milletlerarası Özel Hukuk":"İçinde yabancılık unsuru barındıran özel hukuk davalarında hangi ülke hukukunun uygulanacağını tespit eden dal."},"options":{"A":"Vergi Hukuku","B":"Milletlerarası Özel Hukuk","C":"İdare Hukuku","D":"Ceza Hukuku","E":"Anayasa Hukuku"},"correct_option":"B","explanations":{"A":"Yanlış. Vergi Hukuku devletin kamusal gelir toplama yetkisini tanzim eden bir kamu hukuku disiplinidir.","B":"Doğru. Milletlerarası Özel Hukuk, yabancılık unsuru taşıyan özel hukuk uyuşmazlıklarında yetkili hukuku belirleyen özel hukuk dalıdır.","C":"Yanlış. İdare Hukuku kamu idaresinin işleyişini düzenleyen kamu hukuku dalıdır.","D":"Yanlış. Ceza Hukuku kamu barışını korumak üzere suç ve cezaları belirleyen kamu hukuku dalıdır.","E":"Yanlış. Anayasa Hukuku devletin temel yapısını ve egemenlik organlarını düzenleyen kamu hukuku alanıdır."},"overall_explanation":"Özel hukuk Medeni Hukuk, Borçlar Hukuku, Ticaret Hukuku ve Milletlerarası Özel Hukuk dallarını içerir. Anayasa, İdare, Ceza ve Vergi hukuku ise kamu hukuku bünyesinde yer alır."},{"id":"VIZE_Q27","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Hukuk düzeninde kabul edilen nispi yani hukuki eşitlik ilkesinin anlamı ve gereği bakımından aşağıdakilerden hangisi doğrudur?","tooltips":{"nispi eşitlik":"Eşitler arasında eşitlik anlayışına dayanan, aynı hukuki statüdekileri aynı, farklı statüdekileri durumuna göre değerlendiren ilke.","hak ehliyeti":"Sağ ve tam doğumla başlayıp ölümle sona eren, haklara ve borçlara sahip olabilme iktidarı."},"options":{"A":"Toplumdaki tüm fertlere kişisel durumlarına bakılmaksızın mutlak ve matematiksel olarak aynı işlemin yapılmasıdır","B":"Hak ehliyeti yönünden bireylerin cinsiyet veya ırk gibi biyolojik temellere göre farklı haklara tabi kılınmasıdır","C":"Aynı hukuki durumda bulunanlara aynı kuralın, farklı durumda bulunanlara ise durumlarının gerektirdiği ölçüde farklı kuralın uygulanmasıdır","D":"Kanun koyucunun her türlü kamu hizmetinde ekonomik durumu zayıf olanlara mutlak dokunulmazlık sağlamasıdır","E":"Yargılama makamlarının hiçbir istisna tanımaksızın her vatandaşı aynı ceza yaptırımına çarptırması zorunluluğudur"},"correct_option":"C","explanations":{"A":"Yanlış. Kişilerin durumuna bakılmaksızın herkese aynı işlemin yapılması mutlak eşitliktir ve adaletsiz sonuçlar doğurabilir.","B":"Yanlış. Bireyler arasında cinsiyet veya ırk temelli ayrım yapılması eşitlik ilkesine doğrudan aykırıdır.","C":"Doğru. Nispi eşitlik ilkesi aynı hukuki durumdakilere aynı, farklı hukuki durumdakilere ise durumlarının gerektirdiği ölçüde farklı işlem yapılmasını emreder.","D":"Yanlış. Nispi eşitlik zayıf taraflara mutlak dokunulmazlık sağlamak değil, adil denge kurmaktır.","E":"Yanlış. Kusur durumu ve isnat yeteneği farklı olanlara farklı yaptırımlar uygulanması nispi eşitliğin gereğidir."},"overall_explanation":"Hukuki (nispi) eşitlik eşitler arasında eşit davranmayı dikte eder. Aynı hukuki durumda bulunanlara aynı muamele yapılırken, farklı statü ve şartlardaki kişilere durumlarına uygun kuralların uygulanması adaletin teminatıdır."},{"id":"VIZE_Q28","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Türk Borçlar Kanunu\'nda yer alan \'Borcun ifası için bir ayın başlangıcı veya sonu belirlenmişse, bundan ayın birinci ve sonuncu günü; ayın ortası belirlenmişse, bundan da ayın onbeşinci günü anlaşılır.\' kuralı, işlevi bakımından hangi hukuk kuralı türüdür?","tooltips":{"yorumlayıcı hukuk kuralı":"Tarafların sözleşmede yer verdikleri fakat birden fazla manaya gelebilecek belirsiz terimleri kanunen tek anlama bağlayan kural.","ifa":"Borçlunun borçlandığı edimi yerine getirmesi suretiyle borç ilişkisini sonlandırması."},"options":{"A":"Yorumlayıcı hukuk kuralı","B":"Emredici hukuk kuralı","C":"Tanımlayıcı hukuk kuralı","D":"Tamamlayıcı hukuk kuralı","E":"Yetki verici hukuk kuralı"},"correct_option":"A","explanations":{"A":"Doğru. Sözleşmede yer alan muğlak bir ifadenin kanun koyucu tarafından tek bir anlama bağlanmasını sağladığı için yorumlayıcı hukuk kuralıdır.","B":"Yanlış. Emredici kuralların aksini taraflar serbest iradeleriyle kararlaştıramazlar; oysa taraflar ayın ortası ile başka bir günü kastettiklerini belirtebilirler.","C":"Yanlış. Tanımlayıcı kurallar bir hukuki kavramın yasal kurucu unsurlarını tarif eder.","D":"Yanlış. Tamamlayıcı kurallar sözleşmede hiç bulunmayan irade boşluğunu doldurur; burada ise mevcut ifadenin anlamı netleştirilmektedir.","E":"Yanlış. Yetki verici kural kişilere bir hakkı kullanma veya tasarrufta bulunma kudreti verir."},"overall_explanation":"TBK m. 91/1 hükmü, sözleşmede yer verilen ancak birden fazla manaya çekilebilecek muğlak ifadeleri kesin bir tarihe bağladığı için yorumlayıcı yedek hukuk kuralıdır."},{"id":"VIZE_Q29","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Sosyolojik bir alışkanlığın veya geleneğin pozitif hukukta bağlayıcı bir \'örf ve âdet hukuku kuralı\' hüviyeti kazanabilmesi için bulunması zorunlu olan üç kurucu unsur aşağıdakilerden hangisinde birlikte verilmiştir?","tooltips":{"örf ve âdet hukuku":"Toplumda kendiliğinden doğan, uzun süreli tatbikatla yerleşen ve devlet yaptırımıyla bağlayıcılık kazanan yazısız kural.","süreklilik":"Maddi unsur olarak bir davranış biçiminin toplumda çok uzun süredir kesintisiz şekilde tekrarlanması."},"options":{"A":"Yazılılık, kanun koyucunun tasdiki ve vicdani kanaat","B":"Mülkilik, kanunilik ve yargısal içtihada dayanma","C":"Ekonomik fayda, kodifikasyon ve idari denetim","D":"Soyutluk, genellik ve meclis kararıyla kabul edilme","E":"Süreklilik, genel inanış ve devlet yaptırımıyla desteklenme"},"correct_option":"E","explanations":{"A":"Yanlış. Örf ve âdet hukuku yazılı olmayan bir kaynaktır, yazılılık unsuru içermez.","B":"Yanlış. Mülkilik ve kanunilik ceza ve kamu hukukunun genel ilkeleridir.","C":"Yanlış. Kodifikasyon kuralların kanunlaştırılmasıdır, örf ve âdetin doğasıyla bağdaşmaz.","D":"Yanlış. Meclis kararıyla kabul edilme kanunların kurucu unsurudur.","E":"Doğru. Bir uygulamanın örf ve âdet hukuku sayılması için süreklilik, genel inanış ve devlet yaptırımıyla desteklenme unsurları birlikte bulunmalıdır."},"overall_explanation":"Bir geleneğin örf ve âdet hukuku vasfı kazanması; maddi unsur olan süreklilik, manevi unsur olan genel inanış ve hukukilik unsuru olan devlet yaptırımı ile desteklenmesine bağlıdır."},{"id":"VIZE_Q30","domain_id":7,"domain_name":"Hafta 7: Vizeye Hazırlık","question":"Türkiye Cumhuriyeti yargı düzeninde adli yargı ile idari yargı mercileri arasında ortaya çıkan görev ve hüküm uyuşmazlıklarını kesin olarak karara bağlayan yüksek yargı organı aşağıdakilerden hangisidir?","tooltips":{"Uyuşmazlık Mahkemesi":"Adli ve idari yargı mercileri arasındaki görev ve hüküm uyuşmazlıklarını kesin çözüme bağlayan anayasal yüksek yargı mercii.","görev uyuşmazlığı":"Adli ve idari yargı kollarındaki mahkemelerin aynı davada kendilerini görevli veya görevsiz saymaları hâli."},"options":{"A":"Yargıtay","B":"Danıştay","C":"Anayasa Mahkemesi","D":"Uyuşmazlık Mahkemesi","E":"Hakimler ve Savcılar Kurulu"},"correct_option":"D","explanations":{"A":"Yanlış. Yargıtay adli yargı kolundaki ilk derece mahkemelerinin kararlarını inceleyen üst temyiz mahkemesidir.","B":"Yanlış. Danıştay idari yargı kolundaki iptal ve tam yargı davalarının en üst temyiz merciidir.","C":"Yanlış. Anayasa Mahkemesi norm denetimi ve bireysel başvuruları karara bağlayan özel yargı organıdır.","D":"Doğru. Adli ve idari yargı organları arasındaki görev ve hüküm uyuşmazlıklarını kesin olarak çözmekle görevli merci Uyuşmazlık Mahkemesidir.","E":"Yanlış. Hâkimler ve Savcılar Kurulu bir yüksek mahkeme olmayıp hâkim ve savcıların mesleki özlük işlerini yürüten idari kuruldur."},"overall_explanation":"Farklı yargı kollarının aynı davada görev çatışması yaşaması veya birbirlerinin görev alanına girdiğini savunması durumunda görev uyuşmazlığını kesin olarak çözen organ Uyuşmazlık Mahkemesidir."}]'))}]);